INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('b70f71a0-7270-58cd-acd1-6d070a58c15e', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 24, 24, 'ኢያሱም የዛራን ልጅ አካንን፥ ብሩንም፥ ልብሱንም፥ ልሳነ ወርቁንም ወደ አኮር ሸለቆ ወሰዳቸው፤ ወንዶችና ሴቶች ልጆቹንም፥ በሬዎቹንም፥ አህያዎቹንም፥ በጎቹንም፥ ድንኳኑንም፥ ንብረቱንም ሁሉ ወደ ዔሜቃኮር ወሰደ።'),
  ('b80ca976-5415-508c-a733-29b764fc446a', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 25, 25, 'ኢያሱም፥ “ለምን አጠፋኸን? ዛሬ እንዳጠፋኸን እግዚአብሔር ዛሬ ያጥፋህ” አለው፤ እስራኤልም ሁሉ በድንጋይ ወገሩት፤ በእሳትም አቃጠሉት፤ በድንጋይም ወገሩአቸው።'),
  ('11192977-b4ec-570d-a458-22e905717f48', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 26, 26, 'በላዩም እስከ ዛሬ ድረስ ያለ ታላቅ የድንጋይ ክምር ከመሩ፤ እግዚአብሔርም ከቍጣው መቅሠፍት ተመለሰ። ስለዚህም የዚያ ስፍራ ስም እስከ ዛሬ ድረስ ዔሜቃኮር ተብሎ ተጠራ።'),
  ('9c4b4c64-8184-5833-ac14-e6550ee56daa', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 1, 1, 'እግዚአብሔርም ኢያሱን፥ “አትፍራ፤ አትደንግጥ፤ ተዋጊዎችን ሁሉ ከአንተ ጋር ውሰድ፤ ተነሥተህም ወደ ጋይ ውጣ፤ እነሆ፥ የጋይንም ንጉሥ፥ ሕዝቡንም ከተማውንም ምድሩንም በእጅህ አሳልፌ ሰጥቼሃለሁ።'),
  ('898acce4-3a16-5316-a24c-8a9f077d1d00', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 2, 2, 'በኢያሪኮና በንጉሥዋም እንዳደረግህ እንዲሁ በጋይና በንጉሥዋ ታደርጋለህ፤ የከብቱን ምርኮ ግን ለራሳችሁ ትዘርፋላችሁ፤ ከከተማዪቱም በስተኋላ ይከብቧት ዘንድ ጦር ላክ” አለው።'),
  ('7f04bb0d-7a6e-5e37-a262-ac331cafdd9c', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 3, 3, 'ኢያሱም፥ ተዋጊዎቹም ሕዝብ ሁሉ ተነሥተው ወደ ጋይ ወጡ፤ ኢያሱም ጽኑዓን፥ ተዋጊዎችና ኀያላን የሆኑትን ሠላሳ ሺህ ሰዎች መረጠ፤ በሌሊትም ላካቸው።'),
  ('0419b547-d425-5fe7-acbe-7b0258092928', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 4, 4, 'እንዲህም ብሎ አዘዛቸው፥ “እነሆ፥ ሂዱና ከከተማዪቱ በስተኋላ ተደበቁ፤ ከከተማዪቱ አትራቁ፤ ሁላችሁም ተዘጋጅታችሁ ተቀመጡ፤'),
  ('2c4953a7-579b-5590-aa01-8c00099df0f6', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 5, 5, 'እኔ፥ ከእኔም ጋር ያለው ሕዝብ ሁሉ ወደ ከተማዪቱ እንቀርባለን፤ የጋይም ሰዎች እኛን ሊገናኙ እንደ ፊተኛው በወጡ ጊዜ ከፊታቸው እንሸሻለን፤'),
  ('3868f501-d863-5d45-a30b-bc7eea13dc4c', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 6, 6, 'ወጥተውም በተከተሉን ጊዜ ከከተማ እናርቃቸዋለን፤ እነርሱም እንደ በፊቱ ከፊታችን ሸሹ ይላሉ፤ እኛም ከፊታቸው እንሸሻለን።'),
  ('9c1b97e0-87ba-5fcc-a817-8d55b593a1ce', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 7, 7, 'እንግዲህ እናንተም ከተደበቃችሁበት ስፍራ ተነሡ፤ አምላካችሁም እግዚአብሔር እርስዋን በእጃችሁ አሳልፎ ይሰጣልና ከተማዪቱን ያዙ።'),
  ('6eed67ee-dc9c-5c0b-a072-9da49374d678', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 8, 8, 'በያዛችኋትም ጊዜ ከተማዪቱን በእሳት አቃጥሉአት፤ እንደ አልኋችሁ አድርጉ፤ እነሆ፥ አዝዣችኋለሁ።”'),
  ('8b6ca193-00d1-5f9c-ab98-26a1620f292b', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 9, 9, 'ኢያሱም ላካቸው፤ ወደሚደበቁበትም ስፍራ ሄዱ፤ በጋይና በቤቴል መካከልም በጋይ በባሕር በኩል ተቀመጡ፤ ኢያሱ ግን በዚያች ሌሊት በሕዝቡ መካከል አደረ።'),
  ('162bfb7d-178a-5681-a664-f89f15718898', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 10, 10, 'ኢያሱም ማልዶ ተነሣ፤ ሕዝቡንም አያቸው፤ እርሱም፥ የእስራኤልም ሽማግሌዎች ከሕዝቡ በፊት ወደ ጋይ ወጡ።'),
  ('b19283b6-13cf-5e6b-a29b-2ceeddcdca71', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 11, 11, 'ከእርሱም ጋር የነበሩ ተዋጊዎች ሕዝብ ሁሉ ወጥተው ቀረቡ፤ ወደ ከተማዪቱም ፊት ደረሱ፤ በጋይም በምሥራቅ በኩል ሰፈሩ፤ በእነርሱና በጋይም መካከል ሸለቆ ነበረ።'),
  ('720603e4-44b4-58b6-a72c-4beef7359918', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 12, 12, 'ኢያሱም አምስት ሺህ ሰዎችን ወስዶ በቤቴልና በጋይ መካከል በጋይ ባሕር በኩል ይከብቡ ዘንድ አስቀመጣቸው።'),
  ('cc79ac9f-aed8-567e-a90f-ac26f087ed09', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 13, 13, 'ሕዝቡም ሁሉ ሠራዊቶቻቸውን በከተማው መስዕ በኩል አኖሩ፤ ዳርቻውም እስከ ከተማው ባሕር ድረስ ነው፤ ኢያሱም በዚያች ሌሊት ወደ ሸለቆው መካከል ሄደ።'),
  ('56d1804b-a45d-5bdf-a9e6-4ae960f01dc0', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 14, 14, 'የጋይም ንጉሥ በሰማ ጊዜ ፈጥኖ ሄደ። የከተማዪቱም ሰዎች ወጡ፤ እርሱና ሕዝቡም ሁሉ በተወሰነው ጊዜ በዓረባ ፊት ባለው አንድ ስፍራ እስራኤልን በጦርነት ተቀበሉአቸው፤ እርሱ ግን ከከተማዪቱ በስተኋላ እንደ ተደበቁ አያውቅም ነበር።'),
  ('f326f627-2729-53ff-a0e2-2fc3ea9e7553', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 15, 15, 'በደረሱባቸውም ጊዜ ኢያሱና እስራኤል ሁሉ ከፊታቸው አፈገፈጉ፤ በምድረ በዳው መንገድም ሸሹ።'),
  ('4af8dadf-e0f7-537d-ac21-9e5ca2ed8fa0', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 16, 16, 'የሀገሪቱም ሰዎች ሁሉ ተጠሩ፤ የእስራኤልንም ልጆች ተከትለው አሳደዱአቸው፤ ከከተማዪቱም እንዲርቁ አደረጓቸው።'),
  ('a9bbd87c-4f72-5d6a-aa2a-4d51b436b6e0', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 17, 17, 'በጋይና በቤቴልም ውስጥ እስራኤልን ለማሳደድ ያልወጣ ሰው አልነበረም፤ ከተማዪቱንም ከፍተው ተዉ፤ እስራኤልንም አሳደዱት።'),
  ('62ff92fb-39c5-5d7a-a6fd-36f7dc40e0a4', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 18, 18, 'እግዚአብሔርም ኢያሱን፥ “ጋይን በእጅህ አሳልፌ እሰጥሃለሁና በእጅህ ያለውን ጦር በላይዋ ዘርጋ፤ ከተማዪቱንም የከበቡአት ፈጥነው ከስፍራቸው ይነሣሉ” አለው፤ ኢያሱም በከተማዋ ላይ በእጁ ያለውን ጦር ዘረጋ።'),
  ('8fd66f89-a10e-53b3-a190-1e7231a770b8', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 19, 19, 'የተደበቁትም ፈጥነው ከስፍራቸው ተነሡ፤ ኢያሱም እጁን በዘረጋ ጊዜ ወጡ፤ ወደ ከተማዋም ገብተው ያዙአት፤ ፈጥነውም በእሳት አቃጠሉአት።'),
  ('c99dae4d-3146-53e6-a595-30543856ad3f', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 20, 20, 'የጋይም ሰዎች ወደ ኋላቸው ዞረው በተመለከቱ ጊዜ የከተማዪቱ ጢስ ወደ ሰማይ ሲወጣ አዩ፤ ወዲህና ወዲያ መሸሽ አልቻሉም፤ ወደ ምድረ በዳም የሸሹ ሕዝብ በሚያሳድዱአቸው ላይ ተመለሱ።'),
  ('9afb0029-79f1-5011-a7bd-c06c29ddc450', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 21, 21, 'ኢያሱ፥ እስራኤልም ሁሉ ተደብቀው የነበሩት ከተማዪቱን እንደ ያዙ፥ የከተማዪቱም ጢስ ወደ ሰማይ ሲወጣ ባዩ ጊዜ ወደኋላ ተመልሰው የጋይን ሰዎች ገደሉአቸው።'),
  ('d83f85dc-235e-5c82-a9c7-3d994a3819c7', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 22, 22, 'እነዚያም ከከተማ ወጥተው ተቀበሉአቸው፤ በእስራኤል ልጆች ሠራዊት መካከልም አገቡአቸው፤ እኒያ ከወዲያ፥ እኒህም ከወዲህ ሆነው አንድ እንኳን ሳይቀርና ሳያመልጥ ገደሉአቸው።'),
  ('46a6707d-74e2-5124-a69f-b292826951b6', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 23, 23, 'የጋይንም ንጉሥ ሳይሞት ይዘው ወደ ኢያሱ አመጡት።'),
  ('bdb9a313-9e6e-57e0-a48b-4ed79d148829', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 24, 24, 'የእስራኤልም ልጆች ተከትለዋቸው በነበረበት በተራራው ቍልቍለትና በምድረ በዳ የጋይን ሰዎች መግደልን ከጨረሱ፥ ሁሉንም በጦር ወግተው ከአጠፉአቸው በኋላ ኢያሱ ወዲያውኑ ወደ ጋይ ተመልሶ፥ በሰይፍ አጠፋት።'),
  ('37cf9e1f-b676-5584-a5c6-ee1720616776', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 25, 25, 'በዚያም ቀን የወደቁት ሁሉ ወንድም፥ ሴትም፥ የጋይ ሰዎች ሁሉ ዐሥራ ሁለት ሺህ ነፍስ ነበሩ።'),
  ('b4b0de7f-98ef-5bfb-a92a-e7129646ba1f', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 26, 26, 'ኢያሱም የጋይን ሰዎች እስኪያጠፋ ድረስ ጦር የዘረጋበትን እጁን አላጠፈም።'),
  ('f3f6b6d7-f781-5281-a077-6d93fb2b1551', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 27, 27, 'ነገር ግን እግዚአብሔር ኢያሱን እንዳዘዘው የዚያችን ከተማ ከብትና ምርኮ ሁሉ የእስራኤል ልጆች ለራሳቸው ዘረፉ፤'),
  ('6fad0f72-578a-5fbe-aa93-fccb8f10674b', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 28, 28, 'ኢያሱም ከተማዋን በእሳት አቃጠላት፤ ዐመድም ሆነች፤ እስከ ዛሬም ድረስ ለዘለዓለሙ የሚኖርባት እንዳይኖር አደረጋት።'),
  ('60550df5-756c-562c-a88e-24dfefed24a1', 'cb3662a3-816b-5797-aa03-f437b1844d69', '8038dd16-2720-5306-a15f-185d336ccd6c', 29, 29, 'የጋይንም ንጉሥ በዝግባ ዛፍ ላይ ሰቀለው፤ እስከ ማታም ድረስ በዛፉ ላይ ቈየ። ፀሐይም በገባች ጊዜ ኢያሱ ያወርዱት ዘንድ አዘዘ፤ ከዛፉም አወረዱት፤ በከተማዪቱም በር አደባባይ ጣሉት፤ በላዩም እስከ ዛሬ ድረስ ያለውን ታላቅ የድንጋይ ክምር ከመሩበት።'),
  ('11c4e6b1-c2d7-5332-a105-8217b5c18a99', 'cb3662a3-816b-5797-aa03-f437b1844d69', '9f529dd0-ad3c-54f8-af5b-ddf806928eec', 1, 30, 'የዚያ ጊዜም ኢያሱ በጌባል ተራራ ላይ ለእስራኤል አምላክ ለእግዚአብሔር መሠዊያን ሠራ።'),
  ('aea90e0e-edf9-551a-aac3-fb3018f2c590', 'cb3662a3-816b-5797-aa03-f437b1844d69', '9f529dd0-ad3c-54f8-af5b-ddf806928eec', 2, 31, 'የእግዚአብሔር አገልጋይ ሙሴ የእስራኤልን ልጆች እንዳዘዘ፥ በሙሴም ሕግ መጽሐፍ እንደ ተጻፈው፥ መሠዊያው ካልተወቀረና ብረት ካልነካው ድንጋይ ነበረ፤ በእርሱም ላይ ለእግዚአብሔር የሚቃጠለውን መሥዋዕት አቀረበ፤ የደኅንነትንም መሥዋዕት ሠዋ።'),
  ('55ae8e12-ec4d-56c2-a88a-cff45b3d7c6d', 'cb3662a3-816b-5797-aa03-f437b1844d69', '9f529dd0-ad3c-54f8-af5b-ddf806928eec', 3, 32, 'ኢያሱም በእስራኤል ልጆች ሁሉ ፊት በድንጋዮቹ ላይ ሙሴ የጻፈውን ይህን ሁለተኛውን ሕግ በድንጋዮች ላይ ጻፈ።'),
  ('2863ce65-c182-5212-a5cf-e28ac1e3c1a1', 'cb3662a3-816b-5797-aa03-f437b1844d69', '9f529dd0-ad3c-54f8-af5b-ddf806928eec', 4, 33, 'የእስራኤልንም ሕዝብ አስቀድሞ ይባርኩአቸው ዘንድ የእግዚአብሔር ባሪያ ሙሴ እንዳዘዘ፥ እስራኤል ሁሉ፥ ሽማግሌዎቻቸውም፥ ጸሓፊዎቻቸውም፥ ፈራጆቻቸውም፥ የሀገሩ ልጆችም፥ መጻተኞችም እኩሌቶቹ በገሪዛን ተራራ አጠገብ፥ እኩሌቶቹም በጌባል ተራራ አጠገብ ሆነው፥ የእግዚአብሔርን ታቦተ ሕግ በተሸከሙት በሌዋውያን ካህናት ፊት ለፊት፥ በታቦቱም ፊት በግራና በቀኝ ቆመው ነበር።'),
  ('c3204ef3-855c-5663-a959-9a0520967933', 'cb3662a3-816b-5797-aa03-f437b1844d69', '9f529dd0-ad3c-54f8-af5b-ddf806928eec', 5, 34, 'ከዚህም በኋላ ኢያሱ በሙሴ ሕግ የተጻፈውን ሁሉ፥ የሕጉን ቃሎች ሁሉ በረከቱንና ርግማኑን አነበበ።'),
  ('0f4461c5-81c5-527d-acd0-ddedf761fd74', 'cb3662a3-816b-5797-aa03-f437b1844d69', '9f529dd0-ad3c-54f8-af5b-ddf806928eec', 6, 35, 'ኢያሱም በእስራኤል ጉባኤ ሁሉ፥ በወንዶቹም፥ በሴቶቹም፥ በሕፃናቱም፥ በመካከላቸውም በሚኖሩት መጻተኞች ፊት ሙሴ ካዘዘው ያላነበበውና ያላሰማው ቃል የለም።'),
  ('93b032c1-c2f2-5df5-a0bc-040fb5bb5a02', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 1, 1, 'እንዲህም ሆነ፤ በዮርዳኖስ ማዶ በተራራማው በሜዳውም በታላቁ ባሕር ዳር በሊባኖስም ፊት ለፊት የነበሩ ነገሥት ሁሉ፥ ኬጤዎናዊዉ፥ አሞሬዎናዊዉም፥ ከነዓናዊዉም፥ ፌርዜዎናዊዉም፥ ኤዌዎናዊዉም፥ ኢያቡሴዎናዊዉም፥ ጌርጌሴዎናዊዉም ይህን በሰሙ ጊዜ፥'),
  ('963f3f14-0947-5d1f-a8a7-e10aae1fb247', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 2, 2, 'ኢያሱንና እስራኤልን ሁሉ ሊወጉ አንድ ሆነው ተሰበሰቡ።'),
  ('13a35c0c-7c3b-57aa-a646-d8c782dbcfbd', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 3, 3, 'በገባዖን የሚኖሩ ሰዎች ግን እግዚአብሔር በኢያሪኮና በጋይ ያደረገውን በሰሙ ጊዜ፥'),
  ('edcbca92-a75b-564c-ae8c-27e41796f799', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 4, 4, 'እነርሱ ደግሞ ተንኰል አድርገው መጡ፤ ለራሳቸውም ስንቅ ያዙ፤ በትከሻቸውም ላይ አሮጌ ዓይበትና ያረጀና የተቀደደ የተጠቀመም የጠጅ ረዋት ተሸከሙ።'),
  ('f2b17d56-b2bd-5640-ad9f-1e4478d81876', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 5, 5, 'በእግራቸውም ያደረጉት ጫማ ያረጀና ማዘቢያው የተበጣጠሰ፥ ልብሳቸውም በላያቸው ያረጀ ነበረ፤ ለስንቅም የያዙት እንጀራ ሁሉ የደረቀ፥ የሻገተና የተበላሸ ነበረ።'),
  ('c2245114-0e63-5783-ab97-9d89ffd83780', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 6, 6, 'ወደ ኢያሱና ወደ እስራኤል ጉባኤ ወደ ጌልገላ መጥተው ለኢያሱና ለእስራኤል ሁሉ፥ “ከሩቅ ሀገር መጥተናል፤ አሁንም ከእኛ ጋር ቃል ኪዳን አድርጉ” አሉ።'),
  ('49e8aaed-40b5-58f5-a66b-58e84a672088', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 7, 7, 'የእስራኤልም ልጆች ኤዌዎናውያንን፥ “ምናልባት በመካከላችን የምትቀመጡ እንደ ሆነ እንዴትስ ከእናንተ ጋር ቃል ኪዳን እናደርጋለን?” አሉአቸው።'),
  ('b9a39346-b405-545c-ab9f-0e376dbd663e', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 8, 8, 'ኢያሱንም፥ “እኛ ባሪያዎችህ ነን፤ ከሩቅ ሀገርም ነን” አሉት። ኢያሱም፥ “እናንተ እነማን ናችሁ? ከወዴትስ መጣችሁ?” አላቸው።'),
  ('3fd701bf-e084-5d76-ae0d-a913b664eb49', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 9, 9, 'እነርሱም አሉት፥ “በአምላክህ በእግዚአብሔር ስም እጅግ ከራቀ ሀገር ባሪያዎችህ መጥተናል፤ ዝናውንም፥ በግብፃውያንም ያደረገውን ሁሉ፥'),
  ('db42bc8d-9033-5880-ad5e-3b3de831e40b', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 10, 10, 'በዮርዳኖስ ማዶም በነበሩት በሁለቱ በአሞሬዎን ነገሥት በሐሴቦን ንጉሥ በሴዎን፥ በአስታሮትና በኤድራይን በነበረው በባሳን ንጉሥ በዐግ ያደረገውን ሁሉ ሰምተናል።'),
  ('9d32b463-3cf8-5a2a-a341-627a2fef2ae0', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 11, 11, 'ሽማግሌዎቻችንና የሀገራችን ሰዎች ሁሉ፦ ለመንገድ ስንቅ ያዙ፤ ልትገናኙአቸውም ሂዱ፦ እኛ ባሪያዎቻችሁ ነን፤ አሁንም ከእኛ ጋር ቃል ኪዳን አድርጉ በሉአቸው አሉን።'),
  ('3171dacc-67b8-5364-adc7-52902fd54b0f', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 12, 12, 'ወደ እናንተ ለመምጣት በተነሣንበት ቀን ይህን እንጀራ ትኩሱን ለስንቅ ከቤታችን ያዝነው፤ አሁንም እነሆ፥ ደርቆአል፤ ሻግቶአልም።'),
  ('6c89ddcb-0761-5df9-af20-7f225389ba67', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 13, 13, 'እነዚህም የጠጅ ረዋቶች አዲሶች ሳሉ ሞላንባቸው፤ እነሆም፥ አርጅተው ተቀድደዋል፤ መንገዳችንም እጅግ ስለ ራቀብን እነዚህ ልብሶቻችንና ጫማዎቻችን አርጅተዋል።”'),
  ('deb17def-e18a-5af7-a425-a0936817927e', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 14, 14, 'አለቆችም ከስንቃቸው ወሰዱ፤ እግዚአብሔርንም አልጠየቁም።'),
  ('65883f50-b1ab-5434-a218-323e77a15423', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 15, 15, 'ኢያሱም ከእነርሱ ጋር ሰላም አደረገ፤ በሕይወት እንዲተዋቸውም ከእነርሱ ጋር ቃል ኪዳን አደረገ፤ የማኅበሩም አለቆች ማሉላቸው።'),
  ('587d8b79-38cc-5183-ab91-f4e9153e1adf', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 16, 16, 'ከእነርሱም ጋር ቃል ኪዳን ካደረጉ ከሦስት ቀን በኋላ ከቅርብ እንደሆኑና በአጠገባቸው እንደሚኖሩ ሰሙ።'),
  ('6d0785f8-6658-5aaa-a18a-a58ba92796bc', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 17, 17, 'የእስራኤልም ልጆች ተጕዘው በሦስተኛው ቀን ወደ ከተሞቻቸው ደረሱ፤ ከተሞቻቸውም ገባዖን፥ ከፊራ፥ ብኤሮትና ኢያሪም ነበሩ።'),
  ('a8d2c871-7723-516d-a538-4efe28fab6a6', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 18, 18, 'የማኅበሩም አለቆች በእስራኤል አምላክ በእግዚአብሔር ስለ ማሉላቸው የእስራኤል ልጆች አልገደሉአቸውም። ማኅበሩም ሁሉ በአለቆቹ ላይ አጕረመረሙ።'),
  ('c6943ce6-4b00-56bc-afa8-25d711f8af16', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 19, 19, 'አለቆቹም ሁሉ ለማኅበሩ ሁሉ፥ “በእስራኤል አምላክ በእግዚአብሔር ምለንላቸዋል፤ ስለዚህም እንነካቸው ዘንድ ምንም አንችልም።'),
  ('4f2d7a61-6fe1-5484-a39b-fc15bd87c813', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 20, 20, 'ስለማልንላቸው መሐላ ጥፋት እንዳይሆንብን ይህን አናድርግባቸው፤ በሕይወትም እንተዋቸው፤ እንግዛቸውም” አሉአቸው።'),
  ('2349a273-4477-57ce-ad9f-e63a89cdc349', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 21, 21, 'አለቆቹም “አዳንናችሁ፤ ለማኅበሩም እንጨት ትቈርጡና ውኃ ትቀዱ ዘንድ መደብናችሁ” አሉአቸው። አለቆቹም እንዲሁ አዘዙአቸው።'),
  ('8db8b812-7f6c-56da-a4a5-bfb64d85b90e', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 22, 22, 'ኢያሱም ጠርቶ፥ “እናንተ በመካከላችን የምትኖሩ ስትሆኑ፦ ‘ከእናንተ እጅግ የራቅን ነን’ ብላችሁ ለምን አታለላችሁን?'),
  ('fb0bf2eb-5781-59d5-a52d-b5ebfab73ccc', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 23, 23, 'አሁንም የተረገማችሁ ሁኑ፤ ለእኔም፥ ለአምላኬም እንጨት ቈራጭ፥ ውኃም ቀጂ የሆነ ባሪያ ከእናንተ አይጠፋም” አላቸው።'),
  ('a2b951db-21be-586c-a4dd-c833f20c194e', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 24, 24, 'መልሰውም ኢያሱን፥ “እኛ ባሪያዎችህ ምድሪቱን ሁሉ ይሰጣችሁ ዘንድ፥ በእርስዋም የሚኖሩትን ሁሉ ከፊታችሁ ያጠፋ ዘንድ አምላክህ እግዚአብሔር ባሪያውን ሙሴን እንዳዘዘ በእውነት ሰምተናል፤ ስለዚህም ከእናንተ የተነሣ ስለ ነፍሳችን እጅግ ፈራን፤ ይህንም ነገር አድርገናል፤'),
  ('cd6fcc7f-9146-5df3-a301-ae4d2ac10b7f', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 25, 25, 'አሁንም እነሆ፥ በእጃችሁ ውስጥ ነን፤ እንደ ወደዳችሁና ደስ እንደሚላችሁ አድርጉብን” አሉት፤'),
  ('160b50bc-f44b-5664-a71f-e39167a4b993', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 26, 26, 'ኢያሱም እንዲሁ አደረገባቸው፤ ከእስራኤልም ልጆች እጅ አዳናቸው፤ አልገደሉአቸውምም።'),
  ('90d58d41-22d5-5db1-a818-47e8ca349866', '6d06382b-cc5c-5af7-a30b-06e080d67043', '21de2fb7-d0c2-52e8-a7e7-b5f52705ed10', 27, 27, 'በዚያም ቀን ኢያሱ እነርሱን ለማኅበሩና ለእግዚአብሔር መሠዊያ እንጨት ቈራጮችና ውኃ ቀጂዎች አደረጋቸው። ስለዚህም የገባዖን ሰዎች ለማኅበሩና ለእግዚአብሔር መሠዊያ፥ እግዚአብሔርም ለመረጠው ስፍራ እስከ ዛሬ ድረስ እንጨት ቈራጮች፥ ውኃም ቀጂዎች ሆኑ።'),
  ('3c22d568-5508-55b6-a0a3-19cd94b1be27', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 1, 1, 'እንዲህም ሆነ፤ የኢየሩሳሌም ንጉሥ አዶኒቤዜቅ ኢያሱ ጋይን እንደ ያዘ፥ ፈጽሞም እንዳጠፋት፥ በኢያሪኮና በንጉሥዋም ያደረገውን እንዲሁ በጋይና በንጉሥዋም እንዳደረገ፥ የገባዖንም ሰዎች ከኢያሱና ከእስራኤል ጋር ሰላም እንዳደረጉ፥ በመካከላቸውም እንደ ሆኑ በሰማ ጊዜ፥'),
  ('7c294463-be11-5aaa-a7e9-87087b3ebf23', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 2, 2, 'ገባዖን ከመንግሥታት ከተሞች እንደ አንዲቱ ታላቅ ከተማ ስለሆነች፥ ከጋይም ስለ በለጠች፥ ሰዎችዋም ሁሉ ኀያላን ስለ ነበሩ እጅግ ፈራ።'),
  ('1b585579-8fe5-5635-a2fd-28652a2c5dfb', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 3, 3, 'ስለዚህም የኢየሩሳሌም ንጉሥ አዶኒቤዜቅ ወደ ኬብሮን ንጉሥ ወደ ኤላም፥ ወደ የርሙት ንጉሥም ወደ ፊዶን፥ ወደ ለኪስ ንጉሥም ወደ ኤፍታ፥ ወደ አዶላም ንጉሥም ወደ ዳቤር ልኮ፥'),
  ('f8b8296b-3ad0-5431-afb0-ebba7e35fd2d', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 4, 4, '“ወደ እኔ ኑ፤ ከኢያሱና ከእስራኤልም ልጆች ጋር ሰላም አድርገዋልና ገባዖንን ለመውጋት አግዙኝ” አለ።'),
  ('fa6f46f3-dbeb-552e-a6a4-57bd86391f55', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 5, 5, 'አምስቱም የኢያቡሴዎን ነገሥት፥ የኢየሩሳሌም ንጉሥ የኬብሮን ንጉሥ፥ የየርሙት ንጉሥ፥ የላኪስ ንጉሥ፥ የአዶላም ንጉሥ፥ ከሠራዊቶቻቸው ሁሉ ጋር ተሰብስበው ወጡ፤ ከገባዖንም ጋር ሊጋጠሙ ከበቡአት።'),
  ('d2a3003a-506a-59f9-a3ab-64f1e7739d55', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 6, 6, 'የገባዖንም ሰዎች ኢያሱ ወደ ሰፈረበት ወደ ጌልገላ ልከው፥ “ባሪያዎችህን ለመርዳት እጅህን አትመልስ፤ በተራራማው ሀገር የሚኖሩ የአሞሬዎናውያን ነገሥት ሁሉ ተሰብስበውብናልና ፈጥነህ ወደ እኛ ውጣ፤ አድነንም፤ ርዳንም፤” አሉት።'),
  ('71a4cc71-11a0-5551-a67a-c4612b74a0fa', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 7, 7, 'ኢያሱም ከእርሱም ጋር የነበሩ ተዋጊዎች ሁሉ፥ ጽኑዓን ኀያላኑም ሁሉ ከጌልጌላ ወጡ።'),
  ('c164ce81-7903-5693-ade2-1cb632c43fe3', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 8, 8, 'እግዚአብሔርም ኢያሱን፥ “በእጅህ አሳልፌ ሰጥቼአቸዋለሁና አትፍራቸው፤ ከእነርሱም አንድ ሰው በፊትህ የሚተርፍ የለም፤” አለው።'),
  ('c08c729a-067f-5b6c-ade2-7d4c04fffaad', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 9, 9, 'ኢያሱም ከጌልገላ ሌሊቱን ሁሉ ገሥግሦ በድንገት ደረሰባቸው።'),
  ('163ed987-ad08-5742-a59a-aab0e821b44b', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 10, 10, 'እግዚአብሔርም በእስራኤል ፊት አስደነገጣቸው፤ በገባዖንም ታላቅ መምታት መታቸው።'),
  ('f257a666-4302-569d-a423-4aa41149c4c8', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 11, 11, 'ከእስራኤልም ልጆች ፊት እየሸሹ በቤትሖሮን ቍልቍለት ሲወርዱ፥ ወደ ዓዜቃና ወደ መቄዳ እስኪደርሱ ድረስ እግዚአብሔር ከሰማይ ታላላቅ የበረዶ ድንጋይ አወረደባቸውና ሞቱ፤ የእስራኤል ልጆች በሰይፍ ከገደሉአቸው ይልቅ በበረዶ ድንጋይ የሞቱት በለጡ።'),
  ('844b3ad5-aa3f-5002-aaa5-55313bd0acfe', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 12, 12, 'ያን ጊዜም እግዚአብሔር በእስራኤል ልጆች እጅ አሞሬዎናውያንን አሳልፎ ሰጠ፤ እርሱ በገባዖን እነርሱን ባጠፋበት፥ እነርሱም ከእስራኤል ልጆች ፊት በጠፉበት ቀን ኢያሱ ከእግዚአብሔር ጋር ተነጋገረ፤ እንዲህም አለ፥ “በገባዖን ላይ ፀሐይ ትቁም፤ በኢሎንም ሸለቆ ጨረቃ፤”'),
  ('129d4847-ace6-59a8-a8fb-4b20c5c2d24f', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 13, 13, 'እግዚአብሔርም ጠላቶቻቸውን እስኪያጠፋ ድረስ ፀሐይና ጨረቃ በየቦታቸው ቆሙ። ይህም እነሆ በዚህ መጽሐፍ በጊዜው ተጻፈ። ፀሐይም በሰማይ መካከል ቆመች፤ አንድ ቀንም ሙሉ ያህል አልጠለቀችም።'),
  ('6af387ab-d3f1-5b42-a15d-9d230d1bfac5', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 14, 14, 'እግዚአብሔር ለእስራኤል ይዋጋ ነበርና እግዚአብሔር የሰውን ቃል የሰማበት እንደዚያ ያለ ቀን ከዚያም በፊት ከዚያም በኋላ አልነበረም።'),
  ('0d3e7d10-8b7d-5c8d-ac24-cc740065f837', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', 'cb6da58b-deab-5985-a129-8ab1cff5669e', 15, 15, 'ኢያሱም፥ ከእርሱም ጋር እስራኤል ሁሉ ወደ ሰፈራቸው ወደ ጌልገላ ተመለሱ።'),
  ('26c554be-2936-50a5-ad78-9f827a4b31bc', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 1, 16, 'እነዚህም አምስት ነገሥት ሸሽተው በመቄዳ ዋሻ ተሸሸጉ።'),
  ('3a7c1faa-9fca-5c66-a4e3-331cd5bf4de0', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 2, 17, 'ለኢያሱም “አምስቱ ነገሥት በመቄዳ ዋሻ ተሸሽገው ተገኙ፤” ብለው ነገሩት።'),
  ('3cc233b9-bef7-5aca-a3e1-0bb89e22565b', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 3, 18, 'ኢያሱም እንዲህ አለ፥ “ወደ ዋሻው አፍ ታላላቅ ድንጋይ አንከባልላችሁ፥ ይጠብቋቸው ዘንድ ሰዎችን በዚያ አኑሩ፤'),
  ('65154715-eb95-574a-a6e3-583041ccc58d', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 4, 19, 'እናንተ ግን አትዘግዩ፤ ጠላቶቻችሁንም እስከ መጨረሻው ተከታትላችሁ ያዙአቸው፤ አምላካችሁም እግዚአብሔር በእጃችሁ አሳልፎ ሰጥቶአቸዋልና ወደ ከተሞቻቸው እንዳይገቡ ከልክሉአቸው፤” አለ።'),
  ('dcc78d0f-8353-5197-a662-a04fbe108d49', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 5, 20, 'እስኪጠፉም ድረስ ኢያሱና የእስራኤል ልጆች በታላቅ መምታት መምታታቸውን በፈጸሙ ጊዜ፥ ከእነርሱም ያመለጡት ወደ ተመሸገ ከተማ በገቡ ጊዜ፥'),
  ('87e46093-c95f-555b-a5b5-9034a0cb8135', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 6, 21, 'ሕዝቡ ሁሉ ኢያሱ ወደ ሰፈረበት ወደ መቄዳ በደኅና ተመለሱ፤ በእስራኤል ልጆች ላይ ምላሱን ማንቀሳቀስ የደፈረ ማንም ሰው የለም።'),
  ('3818c4fa-28a3-552c-a1b2-9ffaba80ad4b', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 7, 22, 'ኢያሱም፥ “የዋሻውን አፍ ክፈቱ፤ እነዚያንም አምስት ነገሥት ከዋሻው ወደ እኔ አውጡአቸው” አለ።'),
  ('8d750a14-4877-536a-ac33-f061ccc844ef', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 8, 23, 'እንዲህም አደረጉ፤ አምስቱንም ነገሥት፥ የኢየሩሳሌምን ንጉሥ፥ የኬብሮንንም ንጉሥ፥ የየርሙትንም ንጉሥ፥ የላኪስንም ንጉሥ፥ የአዶላምንም ንጉሥ ከዋሻው ወደ እርሱ አወጡአቸው።'),
  ('8554c2d0-8ab6-5f1e-a9bf-96e53a23001e', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 9, 24, 'እነዚያንም ነገሥት ወደ ኢያሱ ባመጡአቸው ጊዜ ኢያሱ የእስራኤልን ሰዎች ሁሉ ጠራ፤ ከእርሱም ጋር የሄዱትን የተዋጊዎችን አለቆች “ቅረቡ፤ በእነዚህም ነገሥት አንገት ላይ እግራችሁን አኑሩ” አላቸው። ቀረቡም በአንገታቸውም ላይ እግራቸውን አኖሩ።'),
  ('857ee04e-6763-5d4c-abae-b2182192d55b', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 10, 25, 'ኢያሱም፥ “በምትወጉአቸው በጠላቶቻችሁ ሁሉ ላይ እንዲሁ እግዚአብሔር ያደርጋልና አትፍሩ፤ አትደንግጡ፤ ጽኑ፤ አይዞአችሁ” አላቸው።'),
  ('92422827-9f60-56da-a057-63f0e9364bac', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 11, 26, 'ከዚህም በኋላ መትተው ገደሉአቸው፤ በአምስቱም ዛፎች ላይ ሰቀሉአቸው፤ እስከ ማታም ደረስ በዛፎቹ ላይ ተሰቅለው ቈዩ።'),
  ('51afea31-9d1b-57ce-ac8e-f0bb14602b0c', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '48fd24b6-918a-5b43-ac5b-a4fd14af5ac8', 12, 27, 'ፀሐይም ልትገባ በቀረበች ጊዜ ኢያሱ አዘዘ፤ ከዛፎችም አወረዱአቸው፤ ተሸሽገውም በነበሩበት ዋሻ ጣሉአቸው፤ እስከ ዛሬም ድረስ በዋሻው አፍ ታላላቅ ድንጋይ ተደርጎአል።'),
  ('351bcf1a-d22a-5395-ae24-8711ff305ca6', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 1, 28, 'በዚያም ቀን መቄዳን ያዟት፤ እርስዋንና ንጉሥዋንም በሰይፍ ስለት ገደሉ፤ በእርስዋም ያሉትን ነፍሳት ሁሉ ፈጽመው አጠፉአቸው፤ ከእነርሱም አንዱን ስንኳ አላስቀሩም፤ የዳነም፥ ያመለጠም የለም፤ በኢያሪኮም ንጉሥ እንዳደረጉ በመቄዳ ንጉሥ አደረጉ።'),
  ('cb8a493d-da8a-5a14-a9e1-bda0aeeea6a8', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 2, 29, 'ኢያሱም፥ ከእርሱም ጋር እስራኤል ሁሉ ከመቄዳ ወደ ልብና አለፉ፤ ልብናንም ወጉ።'),
  ('7e8f115f-6c08-588b-a89c-60ce10f4716c', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 3, 30, 'እግዚአብሔርም እርስዋንና ንጉሥዋን በእስራኤል እጅ አሳልፎ ሰጠ፤ እርስዋንም በእርስዋም ያሉትን ነፍሳት ሁሉ በሰይፍ ስለት መታ፤ በእርስዋም አንዱን ስንኳ አላስቀረም፤ በኢያሪኮም ንጉሥ እንዳደረገው በልብና ንጉሥ አደረገ።'),
  ('f84c9e21-a0d6-5ff5-a3f2-57dcf30465f5', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 4, 31, 'ኢያሱም ከእርሱም ጋር እስራኤል ሁሉ ከልብና ወደ ላኪስ አለፉ፤ በዙሪያዋም ሰፈሩ፤ ከበቡአትም።'),
  ('a18383d3-2f94-5d25-a7e6-1bfc66a15e3a', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 5, 32, 'እግዚአብሔርም ላኪስን በእስራኤል እጅ አሳልፎ ሰጣት፤ በሁለተኛውም ቀን ያዙአት፤ በልብናም እንዳደረጉት ሁሉ፥ እርስዋን፥ በእርስዋም ያሉትን ነፍሳት ሁሉ በሰይፍ ስለት መቱአቸው።'),
  ('ef85bb6d-3eb6-59af-ad2e-7f1b01be4922', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 6, 33, 'በዚያ ጊዜም የጋዜር ንጉሥ ኤላም ላኪስን ለመርዳት ወጣ፤ ኢያሱም አንድ ስንኳ ሳይቀር በሰይፍ ስለት እርሱንና ሕዝቡን መታ፤ የዳነም፥ ያመለጠም የለም።'),
  ('34096c2e-af58-5c79-aa80-03108635bbee', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 7, 34, 'ኢያሱም ከእርሱም ጋር እስራኤል ሁሉ ከላኪስ ወደ አዶላም አለፉ፤ ከበቡአትም፤ ወጉአትም፤'),
  ('f3ac737e-321d-5665-a601-7c4253ae7259', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 8, 35, 'እግዚአብሔርም በእስርኤል እጅ አሳልፎ ሰጣት፤ በዚያም ቀን ያዙአት፤ በሰይፍም ስለት መቱአት፤ በላኪስም እንዳደረገው ሁሉ፥ በእርስዋ ያሉትን ነፍሳት ሁሉ ፈጽሞ አጠፋ።'),
  ('612933f9-a1ec-591d-aa29-2613eee07a3a', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 9, 36, 'ኢያሱም ከእርሱም ጋር እስራኤል ሁሉ ከአዶላም ወደ ኬብሮን ወጡ፤ ወጉአትም፤ ያዙአትም፤'),
  ('627010eb-3b8a-5dea-a34e-071e3b224df6', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 10, 37, 'እርስዋንም፥ ንጉሥዋንም፥ ከተሞችዋንም ሁሉ፥ በእርስዋም ያሉትን ነፍሳት ሁሉ በሰይፍ ስለት መቱ፤ በአዶላም እንዳደረገው ሁሉ ማንንም አላስቀረም ፤ እርስዋንም፥ በእርስዋም ያሉትን ነፍሳት ሁሉ ፈጽሞ አጠፋ።'),
  ('8f9d6129-723e-5c48-aad7-021dc4068841', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 11, 38, 'ኢያሱም፥ ከእርሱም ጋር እስራኤል ሁሉ ወደ ዳቤር ተመለሱ፤ ወጉአትም፤'),
  ('c1c299ac-3da0-58ff-affb-680ec8a233d1', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 12, 39, 'እርስዋንም፥ ንጉሥዋንም፥ ከተሞችዋንም ያዙ፤ በሰይፍም ስለት መቱአቸው፤ በእነርሱም ውስጥ ያሉትን ነፍሳት ሁሉ ፈጽመው አጠፉ፤ ማንንም አላስቀረም፤ በኬብሮንና በንጉሥዋም እንዳደረገው እንዲሁ በዳቤርና በንጉሥዋ አደረገ።'),
  ('b27bec0c-448e-5f10-a7e2-e0d78741ef10', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 13, 40, 'እንዲሁም ኢያሱ ምድሪቱን ሁሉ፥ ተራራማውን ሀገር፥ ደቡቡንም፥ ቆላውንም፥ ቍልቍለቱንም፥ ንጉሦቻቸውንም ሁሉ መታ፤ ማንንም አላስቀረም፤ የእስራኤል አምላክ እግዚአብሔር እንዳዘዘውም ነፍስ ያለበትን ሁሉ ፈጽሞ አጠፋ።'),
  ('e18e48c2-59e3-5c8e-a02a-ccccec603a74', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 14, 41, 'ኢያሱም ከቃዴስ በርኔ እስከ ጋዛ ድረስ፥ የጎሶምንም ምድር ሁሉ እስከ ገባዖን ድረስ መታ።'),
  ('d93967ef-b162-540f-a576-8a68c4086f35', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 15, 42, 'የእስራኤልም አምላክ እግዚአብሔር ለእስራኤል ስለ ተዋጋላቸው ኢያሱ እነዚህን ነገሥታት ሁሉ ምድራቸውንም በአንድ ጊዜ ያዘ።'),
  ('6d4837b6-8cb6-586e-a0ed-74f15db89ff3', '23cb22a1-e3a4-5df0-a310-7b40e2844d64', '23b70cc5-e303-54bd-a3a4-a1346c75f33b', 16, 43, 'ኢያሱም፥ ከእርሱም ጋር እስራኤል ሁሉ ወደ ሰፈሩ ወደ ጌልገላ ተመለሱ።'),
  ('bb49fd3a-5432-550a-ab83-d37e4b6cb278', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 1, 1, 'እንዲህም ሆነ፤ የአሶር ንጉሥ ኢያቢስ ይህን በሰማ ጊዜ ወደ ማሮን ንጉሥ ወደ ዮባብ፥ ወደ ስሚዖን ንጉሥ፥ ወደ አዚፍም ንጉሥ፥'),
  ('26ba8e97-bfca-52fc-a206-abe4c8146297', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 2, 2, 'በመስዕም በተራራማው ሀገር ፥ በከነሬትም ዐዜብ በዓረባ፥ በቆላውም ባለ በፊናዶር ሸለቆ ወደ ነበሩ ነገሥታት፥'),
  ('50060faa-9ce8-520e-a504-f8b88b37f20c', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 3, 3, 'በምሥራቃዊ ባሕር ዳርቻ ወዳለው ወደ ከነዓናዊው፥ ወደ አሞሬዎናዊውም፥ ወደ ኬጤዎናዊውም፥ ወደ ፌርዜዎናዊውም፥ በተራራማውም ሀገር ወዳለው ወደ ኢያቡሴዎናዊው፥ በቆላማውና በመሴፋ ወዳለው ወደ ኤዌዎናዊዉም ላከ።'),
  ('e002e979-74ba-5dfe-a21a-50d46fd2d935', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 4, 4, 'እነርሱ፥ ከእነርሱም ጋር ሠራዊቶቻቸው ሁሉ ብዛታቸው እንደ ባሕር አሸዋ ሆነው ወጡ፤ ፈረሶችና ሰረገሎችም እጅግ ብዙዎች ነበሩ።'),
  ('f2de8764-42e5-5136-a86e-6f9cd7545c68', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 5, 5, 'እነዚህም ነገሥታት ሁሉ ተሰብስበው መጡ፤ እስራኤልንም በማሮን ውኃ አጠገብ አንድ ሆነው ተያያዙአቸው።'),
  ('8fe48b50-d047-5c68-aad1-a8514bd14223', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 6, 6, 'እግዚአብሔርም ኢያሱን፥ “በእስራኤል ፊት ይሞቱ ዘንድ ነገ በዚህ ጊዜ ሁሉን በእጅህ አሳልፌ እሰጣቸዋለሁና አትፍራቸው፤ የፈረሶቻቸውን ቋንጃ ትቈርጣለህ፤ ሰረገሎቻቸውንም በእሳት ታቃጥላለህ” አለው።'),
  ('3770a483-958e-5d2d-adfc-a978157aa7e6', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 7, 7, 'ኢያሱና ተዋጊዎች ሕዝብም ሁሉ በድንገት ወደ ማሮን ውኃ መጡባቸው፤ በተራራማውም ቦታ ወደቁባቸው።'),
  ('2426e9e7-ab12-59b4-a8e9-432d0ec8055f', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 8, 8, 'እግዚአብሔርም በእስራኤል እጅ አሳልፎ ሰጣቸው፤ መቱአቸውም፤ ወደ ታላቂቱም ሲዶና፥ ወደ ማሴሮንም፥ በምሥራቅም በኩል ወዳለው ወደ ሞሳሕ ሸለቆ አሳደዱአቸው፤ ማንንም ሳያስቀሩ መቱአቸው።'),
  ('1c7ec421-35d5-5493-a535-3c20ecb6164a', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 9, 9, 'ኢያሱም እግዚአብሔር እንዳዘዘው አደረገባቸው፤ የፈረሶቻቸውንም ቋንጃ ቈረጠ፤ ሰረገሎቻቸውንም በእሳት አቃጠለ።'),
  ('754f76f1-37b9-525a-a87b-5c559ab9b95a', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 10, 10, 'በእነዚያም ወራት ኢያሱ ተመልሶ አሶርን ያዘ፤ ንጉሥዋንም በሰይፍ ገደለ፤ አሶርም አስቀድሞ የእነዚህ መንግሥታት ዋና ከተማ ነበረች።'),
  ('f72a9911-0f93-51cf-af59-d26f7f17c19c', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 11, 11, 'በእርስዋም ያሉትን ሰዎች ሁሉ በሰይፍ ገደሉ፤ እስትንፋስ ያላቸውንም ሁሉ ሳያስቀሩ ሁሉንም አጠፉአቸው፤ አሶርንም በእሳት አቃጠላት፤'),
  ('a0a31c29-e16c-5cbc-a014-cac3a1de8081', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 12, 12, 'የእግዚአብሔርም አገልጋይ ሙሴ እንዳዘዘው፥ ኢያሱ የእነዚህን መንግሥታት ከተሞች ሁሉ፥ ንጉሦቻቸውንም ሁሉ ያዘ፤ በሰይፍም መታቸው፤ ፈጽሞም አጠፋቸው።'),
  ('755e3875-6e12-531c-a1c1-76bb00c3d4da', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 13, 13, 'ከአቃጠሏት ከአሶር ብቻ በቀር እስራኤል በየአውራጃቸው የነበሩትን ሌሎች ከተሞች ሁሉ አላቃጠሉም።'),
  ('3130a03d-4449-5c48-a40a-049f7c751395', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 14, 14, 'የእስራኤልም ልጆች የእነዚህን ከተሞች ምርኮ ሁሉ፥ ከብቶቹንም ለራሳቸው ዘረፉ፤ ሰዎቹን ሁሉ ግን እስኪጠፉ ድረስ በሰይፍ ስለት መቱአቸው፤ እስትንፋስ ያለውንም ሁሉ አንድም አላስቀሩም።'),
  ('0e0ac68d-4ee1-5b4e-a6ba-2dc8879cefaa', '45393288-1091-58ba-a8e3-1e957f7d7537', '2f3df843-51ab-5b26-aff0-98e422e818ee', 15, 15, 'እግዚአብሔርም አገልጋዩን ሙሴን እንዳዘዘ እንዲሁ ሙሴ ኢያሱን አዝዞት ነበር፤ ኢያሱም እንዲሁ አደረገ፤ እግዚአብሔርም ሙሴን ካዘዘው ሁሉ ምንም አላስቀረም።'),
  ('9b85b7c8-8208-50e6-a2a7-84a994019cad', '45393288-1091-58ba-a8e3-1e957f7d7537', 'c475a8e0-0c2a-5194-a08d-aeac88aafb6e', 1, 16, 'ኢያሱም ያን ምድር ሁሉ፥ ተራራማውን፥ ደቡቡንም ሁሉ፥ የጎሶምንም ምድር ሁሉ ፥ ሜዳውንም፥ በምዕራብ በኩል ያለውንም፥ የእስራኤልንም ተራራማውንና ቆላውን ያዘ፤'),
  ('036d6e82-c122-562e-a312-480d9c094645', '45393288-1091-58ba-a8e3-1e957f7d7537', 'c475a8e0-0c2a-5194-a08d-aeac88aafb6e', 2, 17, 'እስከ ሴይርም ከሚያወጣው ከኤኬል ተራራ ጀምሮ ከአርሞንዔም ተራራ በታች እስከ ሊባኖስ ሜዳና እስከ በላጋድ ድረስ፤ ንጉሦቻቸውን ሁሉ ይዞ መታቸው፤ ገደላቸውም።'),
  ('f8174348-9bf3-5369-aeaa-3f28d46da543', '45393288-1091-58ba-a8e3-1e957f7d7537', 'c475a8e0-0c2a-5194-a08d-aeac88aafb6e', 3, 18, 'ኢያሱም ብዙ ዘመን ከእነዚሁ ነገሥታት ሁሉ ጋር ይዋጋ ነበር።'),
  ('a079ae6e-35dd-5c96-a973-c35a966d0204', '45393288-1091-58ba-a8e3-1e957f7d7537', 'c475a8e0-0c2a-5194-a08d-aeac88aafb6e', 4, 19, 'በገባዖን ከሚኖሩ ከኤዎናውያን በቀር፤ እስራኤል ያልያዙት ከተማ አልነበረም፥ ሁሉን በጦርነት ያዙ።'),
  ('685b8b14-fc8f-55cf-ac2a-82a89704e0f4', '45393288-1091-58ba-a8e3-1e957f7d7537', 'c475a8e0-0c2a-5194-a08d-aeac88aafb6e', 5, 20, 'እግዚአብሔር ሙሴን እንዳዘዘ፥ ያጠፉአቸው ዘንድ እንዳይራሩላቸው ፈጽመው እንዲያጠፉአቸው፥ ከእስራኤል ጋር ይጋጠሙ ዘንድ ልባቸውን እንዲያደነድኑ እግዚአብሔር ልባቸውን አጸና።'),
  ('645bb649-66a8-5782-a212-47818a1ef451', '45393288-1091-58ba-a8e3-1e957f7d7537', 'c475a8e0-0c2a-5194-a08d-aeac88aafb6e', 6, 21, 'በዚያ ጊዜም ኢያሱ ሄደ፤ በተራራማውም ሀገር የሚኖሩ ኤናቃውያንን ከኬብሮንና ከዳቤር፥ ከአናቦትም፥ ከእስራኤልም ተራራ ሁሉ፥ ከይሁዳም ተራራ ሁሉ አጠፋቸው፤ ኢያሱም ከከተሞቻቸው ጋር ፈጽሞ አጠፋቸው።'),
  ('f82b9971-85a6-5adc-afc1-423f72dae978', '45393288-1091-58ba-a8e3-1e957f7d7537', 'c475a8e0-0c2a-5194-a08d-aeac88aafb6e', 7, 22, 'በጋዛ፥ በጌትም፥ በአዛጦንም ከቀሩት በቀር በእስራኤል መካከል ከኤናቃውያን ማንንም አላስቀረም።'),
  ('a21ffb33-4434-5207-a4e5-053314dc1dcf', '45393288-1091-58ba-a8e3-1e957f7d7537', 'c475a8e0-0c2a-5194-a08d-aeac88aafb6e', 8, 23, 'እግዚአብሔርም ለሙሴ እንዳዘዘው ሁሉ ኢያሱ ምድሪቱን ሁሉ ያዘ፤ ኢያሱም ለእስራኤል እንደ ክፍላቸው በየነገዳቸው ርስት አድርጎ ምድሪቱን ሰጣቸው፤ ምድሪቱም ከጦርነት ዐረፈች።'),
  ('dbbfced3-ee1e-54e1-ace7-36234a560338', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', 'ff5250ba-1162-5a3c-af57-c4917fadebd2', 1, 1, 'የእስራኤልም ልጆች የመቱአቸው፥ ከአርኖንም ሸለቆ ጀምሮ እስከ አርሞንዔም ተራራ ድረስ በምሥራቅ በኩል ያለውን ዓረባ ሁሉ በዮርዳኖስም ማዶ በፀሐይ መውጫ ያለውን ሀገራቸውን የወረሱአቸው የምድር ነገሥት እነዚህ ናቸው፤'),
  ('cb240944-d8f5-5539-a18a-1f42c26e410b', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', 'ff5250ba-1162-5a3c-af57-c4917fadebd2', 2, 2, 'በሐሴቦን የተቀመጠው፥ በአርኖንም ሸለቆ አጠገብ ካለችው ከአሮዔር፥ ከሸለቆውም መካከል ጀምሮ የገለዓድን እኩሌታ እስከ ኢያቦቅ ወንዝ እስከ አሞን ልጆች ዳርቻ ድረስ፤'),
  ('7c0189c5-ebeb-5aac-a6db-3a7a7a8d933f', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', 'ff5250ba-1162-5a3c-af57-c4917fadebd2', 3, 3, 'በምሥራቅም በኩል ያለውን ዓረባ እስከ ኬኔሬት ባሕር ድረስ፥ በአሴሞት መንገድ አጠገብ እስካለው እስከ ዓረባ ባሕር እስከ ጨው ባሕር ድረስ፥ በደቡብም በኩል ከፋስጋ ተራራ አፋፍ በታች ያለውን ምድር የገዛው የአሞሬዎናውያን ንጉሥ ሴዎን፤'),
  ('01dcbde0-af48-55ba-acfe-ff92ec927135', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', 'ff5250ba-1162-5a3c-af57-c4917fadebd2', 4, 4, 'ከረዓይት ወገን የቀረ፥ በአስጣሮትና በኤንድራይን የተቀመጠው፥'),
  ('d75e7174-7de9-5002-a403-e4e62b58eaec', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', 'ff5250ba-1162-5a3c-af57-c4917fadebd2', 5, 5, 'የአርሞንኤምን ተራራ፥ ካሴኪን፥ ባሳንንም ሁሉ እስከ ጌርጌሲና እስከ መከጢ ዳርቻ፥ የገለዓድንም እኩሌታ እስከ ሐሴቦን ንጉሥ እስከ ሴዎን ዳርቻ ድረስ የገዛው የባሳን ንጉሥ ዐግ፤'),
  ('64b7b23c-296e-54d3-ade9-7e315cd86b91', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', 'ff5250ba-1162-5a3c-af57-c4917fadebd2', 6, 6, 'የእግዚአብሔር አገልጋይ ሙሴና የእስራኤል ልጆች ገደሉአቸው፤ የእግዚአብሔርም አገልጋይ ሙሴ ርስት አድርጎ ለሮቤል ልጆች፥ ለጋድም ልጆች፥ ለምናሴም ነገድ እኩሌታ ምድሪቱን ሰጣቸው።'),
  ('d2edca44-91c2-5063-a26f-16e943187139', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 1, 7, 'የእስራኤል ልጆችና ኢያሱ በሊባኖስ ቆላ፥ በበላጋድ ባሕር፥ በዮርዳኖስ ማዶ ወደ ሴይር በሚደርስ በኬልኪ ተራራ የገደሉአቸው የከነዓን ነገሥት እነዚህ ናቸው። ኢያሱም ያችን ምድር ለእስራኤል ወገኖች ሰጣቸው።'),
  ('417aa7c6-8260-5ed4-a8b1-5b0202a0dcdf', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 2, 8, 'በተራራና በሜዳ በዓረባ፥ በአሴዶት በቆላው፥ በናጌብ፥ በኬጤዎንና በአሞሬዎን፥ በከናኔዎንና በፌርዜዎን፥ በኢያቡሴዎንና በኤዌዎን ያለ ርስታቸውን አወረሳቸው።'),
  ('d25f94ac-7d7b-5e14-aca1-a3db399039b7', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 3, 9, 'የኢያሪኮ ንጉሥ፥ በቤቴል አጠገብ ያለችው የጋይ ንጉሥ፥'),
  ('299b835e-f448-53fc-abd4-8ff19bd1752c', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 4, 10, 'የኢየሩሳሌም ንጉሥ፥ የኬብሮን ንጉሥ፥'),
  ('656e4b7a-e958-5790-adfe-c499fe826e10', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 5, 11, 'የኢያሪሙት ንጉሥ፥ የለኪስ ንጉሥ፥'),
  ('4911be15-fa58-5ba2-a11c-b93c1ae3862a', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 6, 12, 'የኤላም ንጉሥ፥ የጋዜር ንጉሥ፥'),
  ('2a45aaf2-43eb-5eae-af4b-5989a301c60f', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 7, 13, 'የዳቤር ንጉሥ፥ የጋሴ ንጉሥ፥'),
  ('02ddda1b-38c3-5d54-a3a3-78effff7e6de', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 8, 14, 'የኤርሞት ንጉሥ፥ የዓራድ ንጉሥ፥'),
  ('9c0d88e6-e82b-5b15-a849-6243042ed640', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 9, 15, 'የልብና ንጉሥ፥ የዓዶላም ንጉሥ፥'),
  ('451deb62-c478-5a4c-a520-d7160ad35a79', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 10, 16, 'የመቄዳ ንጉሥ፥'),
  ('794e8ff5-c028-507c-aa8d-d28e3a5f35ea', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 11, 17, 'የኤጣፋድ ንጉሥ፥'),
  ('6023a7c3-3b83-5497-a4e3-cace3a895190', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 12, 18, 'የኦፌር ንጉሥ፥'),
  ('e25fa108-8ca9-5a78-a247-ae129b3b8a94', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 13, 19, 'የአፌጠቀሰሩት ንጉሥ፥ የአሶር ንጉሥ፥'),
  ('1f678c39-b58d-53c9-a44c-b31df8c05fba', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 14, 20, 'የስሚዖን ንጉሥ፥ የመምሮት ንጉሥ፥'),
  ('744ba491-b196-5123-a8b3-82e3d5988183', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 15, 21, 'የአዚፍ ንጉሥ፥ የቃዴስ ንጉሥ፥'),
  ('3308e5a7-18b8-5dd5-aa98-82b61755c42b', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 16, 22, 'የዘቃክ ንጉሥ፥ የማርዶት ንጉሥ፥ በቀርሜሎስ የነበረ የዴቆም ንጉሥ፥'),
  ('f2a2d54a-79e0-5b0b-a777-95063ea79867', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 17, 23, 'በፌናድር ክፍል የምትሆን የኤዶር ንጉሥ፥ በጋልያ ክፍል የምትሆን የሐጌ ንጉሥ፥ የቲርሣ ንጉሥ፥'),
  ('07fc7a94-ebd8-5726-ab8e-c17d7fa653c1', '9ea08b0d-e59b-5b77-a319-d73dc01ee830', '43808374-47c4-58a8-a423-d78bd918c3ba', 18, 24, 'እነዚህ ነገሥት ሁሉ ሃያ ዘጠኝናቸው።'),
  ('ba4c4f1c-e922-59cc-accb-30a4ef055ec3', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'a2ee82c4-36e0-53b1-ab61-737525ad979e', 1, 1, 'ኢያሱም ሸመገለ፤ ዘመኑም አለፈ፤ እግዚአብሔርም ኢያሱን አለው፥ “እነሆ ዘመንህ አለፈ፤ ያልተወረሰች እጅግ ብዙ ምድር ገና ቀርታለች፤'),
  ('89475df4-9ecb-5538-aa4b-260296e42791', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'a2ee82c4-36e0-53b1-ab61-737525ad979e', 2, 2, 'የቀረችውም ምድር ይህች ናት፤ የፍልስጥኤማውያን፥ የጌሴርያውያንና የከነዓናውያን ሀገር ሁሉ፥'),
  ('783804cf-5c6e-5fff-a2b8-b06b1338ceeb', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'a2ee82c4-36e0-53b1-ab61-737525ad979e', 3, 3, 'በግብፅ ፊት ካለው ምድረ በዳ ጀምሮ ለአምስቱ የፍልስጥኤም ግዛቶች ለጋዛ፥ ለአዛጦን፥ ለአስቀሎና፥ ለጌት፥ ለአቃሮን፥ እንዲሁም ለኤዌዎናውያን በተቈጠረችው በከነዓን ግራ በኩል እስካለችው እስከ አቃሮን ዳርቻ ድረስ ነው፤'),
  ('ce770d79-6a17-5803-aa0d-d9261ca71b71', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'a2ee82c4-36e0-53b1-ab61-737525ad979e', 4, 4, 'ከደቡብ ጀምሮ በጋዛና በሲዶና ፊት ያለውን የከነዓናውያን ምድር ሁሉ እስከ አሞሬዎናውያን ዳርቻ እስከ አፌቅ ድረስ፥'),
  ('f0c2986c-b246-5a2b-a056-59deaff0004e', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'a2ee82c4-36e0-53b1-ab61-737525ad979e', 5, 5, 'በፍልስጥኤም ያለው የጌባላውያን ምድር ሁሉ፥ በምሥራቅም በኩል ከአርሞንዔም ተራራ በታች ካለችው ጌልገላ ጀምሮ እስከ ኤማት መግቢያ ድረስ ያለችው ሊባኖስ ሁሉ፥'),
  ('0c4f2d43-1aff-57ab-a836-d7a29c4ba4e5', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'a2ee82c4-36e0-53b1-ab61-737525ad979e', 6, 6, 'በተራራማውም ሀገር የሚኖሩትን ሁሉ ከሊባኖስ ጀምሮ እስከ ማሴሬትሜምፎማይም መያያዣ ድረስ ሲዶናውያን ሁሉ፤ እነዚህን ከእስራኤል ልጆች ፊት አጠፋቸዋለሁ፤ እንዳዘዝሁህም ምድራቸውን ለእስራኤል ርስት አድርገህ አካፍላቸው።'),
  ('f129a6ac-28c9-5e40-a127-6e122f98f99c', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'a2ee82c4-36e0-53b1-ab61-737525ad979e', 7, 7, 'አሁንም ይህን ምድር ለዘጠኙ ነገድ፥ ለምናሴም ነገድ እኩሌታ ርስት አድርገህ ክፈለው። ከዮርዳኖስ ጀምሮ በምዕራብ እስካለው ታላቁ ባሕር ድረስ ትሰጣቸዋለህ፤ ድንበራቸውም ታላቁ ባሕር ይሆናል።”'),
  ('f044d779-1d36-5562-a8ab-1533056beb9e', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'd116bf50-daf3-5c3a-a063-8b457d55cbb6', 1, 8, 'የእግዚአብሔር አገልጋይ ሙሴም እንደ ሰጣቸው ከእርሱ ከምናሴ ጋር የሮቤልና የጋድ ልጆች፥ በምሥራቅ በኩል በዮርዳኖስ ማዶ ሙሴ የሰጣቸውን ርስታቸውን ተቀበሉ።'),
  ('90287f7c-be5d-5597-ade4-20fe87d37ac3', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'd116bf50-daf3-5c3a-a063-8b457d55cbb6', 2, 9, 'በአርኖን ሸለቆ ዳር ካለችው ከአሮዔር፥ በሸለቆውም መካከል ካለችው ከተማ ጀምሮ የሚሶር ሜዳ ሁሉ እስከ ዲቦን ድረስ፥'),
  ('bff94261-f605-5d5e-ae7e-347ce1b8bcfd', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'd116bf50-daf3-5c3a-a063-8b457d55cbb6', 3, 10, 'በሐሴቦንም የነገሠ የአሞሬዎን ንጉሥ የሴዎን ከተሞችን ሁሉ እስከ አሞን ልጆች ዳርቻ ድረስ፥'),
  ('e0d02c3d-1b7a-5b3b-a97f-d1fccc945ed3', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'd116bf50-daf3-5c3a-a063-8b457d55cbb6', 4, 11, 'ገለዓድንም፥ የጌሴሪያውያንንና የመከጢያውያንን ዳርቻ ሁሉ፥ የአርሞንዔምንም ተራራ ሁሉ፥ ባሳንንም ሁሉ፥ እስከ ሰልካ ድረስ፥'),
  ('5c73c74b-cd94-58f9-a769-cc1b800c990e', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'd116bf50-daf3-5c3a-a063-8b457d55cbb6', 5, 12, 'በባሳን የነበረውን፥ በአስታሮትና በኤንድራይን የነገሠውን የዐግን መንግሥት ሁሉ፤ እርሱም ከረዓይት የቀረ ነበረ፤ እነዚህንም ሙሴ አወጣቸው፤ ገደላቸውም።'),
  ('bfd98bfd-d39f-536d-ab4c-f85a1520e9ce', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'd116bf50-daf3-5c3a-a063-8b457d55cbb6', 6, 13, 'የእስራኤል ልጆች ግን ጌሴሪያውያንን፥ መከጢያውያንንና ከነዓናውያንን አላጠፉአቸውም፤ እስከ ዛሬም ድረስ ጌሴሪና መከጢ በእስራኤል መካከል ይኖራሉ።'),
  ('5dbee6ba-13b3-5ea4-a16c-5deef809bb14', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'd116bf50-daf3-5c3a-a063-8b457d55cbb6', 7, 14, 'ለሌዊ ነገድ ግን ርስት አልተሰጠም፤ እግዚአብሔር እንደ ተናገራቸው የእስራኤል አምላክ እግዚአብሔር ርስታቸው ነውና፥ በኢያሪኮ በኩል በዮርዳኖስ ማዶ በሞዓብ ሜዳ ሙሴ ለእስራኤል ልጆች እንዳካፈላቸው እንዲሁ ተካፈሉ።'),
  ('a24708bb-80ce-5379-aabb-5a8ba6c71d81', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '9328732d-fb07-553e-ad14-61619bd398f2', 1, 15, 'ሙሴም ለሮቤል ነገድ በየወገናቸው ርስትን ሰጣቸው።'),
  ('4aebf778-b867-5f0d-a151-83eb1f3c6577', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '9328732d-fb07-553e-ad14-61619bd398f2', 2, 16, 'ድንበራቸውም በአርኖን ሸለቆ ዳር ካለችው ከአሮዔር ጀምሮ በሸለቆው መካከል ያለችው ከተማ፥ ሜሶርም ሁሉ፥'),
  ('3708e8cc-1976-5599-ad44-989676070e98', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '9328732d-fb07-553e-ad14-61619bd398f2', 3, 17, 'ሐሴቦን፥ በሜሶርም ያሉት ከተሞች ሁሉ፥ ዲቦን፥ ባሞትበዐል፥ ቤትበአልምዖን፥'),
  ('db86adef-94de-5b61-ab05-afa9ff7df669', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '9328732d-fb07-553e-ad14-61619bd398f2', 4, 18, 'ባሳን፥ ቀዲሞት፥ ሜፍዓ፥'),
  ('e92201ee-8641-508c-acc0-cb7f0322f316', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '9328732d-fb07-553e-ad14-61619bd398f2', 5, 19, 'ቂርያታይም፥ ሴባማ፥ ሲራዳት፥ በሸለቆውም ተራራ ያለችው ሲዮን፥'),
  ('50c6e68a-afb2-5824-a894-5766af0db9c9', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '9328732d-fb07-553e-ad14-61619bd398f2', 6, 20, 'ቤተ ፌጎር፥ ከፈስጋ ተራራ በታች ያለው ምድር፥ ቤትሲሞት፥'),
  ('65636e9b-6e84-540f-a923-58ccffa7f3c2', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '9328732d-fb07-553e-ad14-61619bd398f2', 7, 21, 'የሚሶር ከተሞች ሁሉ፥ በሐሴቦንም የነገሠው የአሞሬዎናውያን ንጉሥ የሴዎን መንግሥት ሁሉ ነበረ፤ ሙሴም እርሱንና በምድሪቱ የተቀመጡትን የሴዎንን መሳፍንት፥ የምድያምን አለቆች ኤዊን፥ ሮቦቅን፥ ሱርን፥ ኡርን፥ ሮቤን በሲዮን የሚኖሩትንም ገደላቸው።'),
  ('db90ec34-559d-5be1-a6bf-881565bad032', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '9328732d-fb07-553e-ad14-61619bd398f2', 8, 22, 'ሟርተኛውን የቢዖርን ልጅ በለዓምንም በአንድነት በሰይፍ ገደሉት።'),
  ('5e52bdd0-4922-5b24-a7ea-b1d3aa784d85', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '9328732d-fb07-553e-ad14-61619bd398f2', 9, 23, 'የሮቤልም ልጆች ድንበር የዮርዳኖስ ወንዝና ዳርቻው ነበረ። የሮቤል ልጆች ርስት ከተሞቻቸውም መንደሮቻቸውም በየወገኖቻቸው ይህ ነበረ።'),
  ('bcbc3fe0-1281-5037-a2bc-d442fb98e120', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '24eabdf6-ecff-535c-a0f0-05654b929a4e', 1, 24, 'ሙሴም ለጋድ ነገድ ለጋድም ልጆች በየወገኖቻቸው ርስት አድርጎ ሰጣቸው።'),
  ('00c3a3e9-9ae8-5cce-a15a-96f778e63314', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '24eabdf6-ecff-535c-a0f0-05654b929a4e', 2, 25, 'ድንበራቸውም ኢያዜርና የገለዓድ ከተሞች ሁሉ፥ የአሞንም ልጆች ምድር እኩሌታ በራባት ፊት እስካለችው እስከ አሮዔር ድረስ፥'),
  ('96bf460a-4408-56df-a7c8-68019591fd0a', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '24eabdf6-ecff-535c-a0f0-05654b929a4e', 3, 26, 'ከሐሴቦን ጀምሮ እስከ አራቦት መሴፋ፥ እስከ ቦጣኒም ድረስ፥ ከማኦን ጀምሮ እስከ ዴቦን ዳርቻ ድረስ፥'),
  ('3dadc647-1f26-52a8-a81a-2a183fbf3377', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '24eabdf6-ecff-535c-a0f0-05654b929a4e', 4, 27, 'በሸለቆውም ቤትሀራም፥ ቤትንምራ፥ ሱኮት፥ ጻፎን፥ የሐሴቦን ንጉሥ የሴዎን መንግሥት ቅሬታ ነበረ። ድንበሩም ዮርዳኖስና በምሥራቅ በኩል ባለው በዮርዳኖስ ማዶ የኬኔሬት ባሕር ወዲያኛው ዳርቻ ነበረ።'),
  ('580574bc-ae3c-5138-ab71-fad6f80b41e8', 'd915bf50-4498-598b-ac8d-2d1e032cc551', '24eabdf6-ecff-535c-a0f0-05654b929a4e', 5, 28, 'የጋድ ልጆች ርስት ከተሞቻቸውም፥ መንደሮቻቸውም በየወገኖቻቸው ይህ ነበረ። በጠላቶቻቸውም ፊት ጀርባቸውን መልሰው ሸሹ፤ መንደሮቻቸውና ከተሞቻቸው በየወገናቸው ሆነዋልና።'),
  ('90c75c61-1c4a-5e75-a445-1d5541054477', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'c342face-d198-5598-a40f-3ccf10d42598', 1, 29, 'ሙሴም ለምናሴ ነገድ እኩሌታ በየወገኖቻቸው ርስት ሰጣቸው፤'),
  ('55f32dd1-05a2-5ff2-a8a3-38c9509027a2', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'c342face-d198-5598-a40f-3ccf10d42598', 2, 30, 'ድንበራቸውም ከመሐናይም ጀምሮ የባሳን ንጉሥ የዐግ መንግሥት፥ ባሳን ሁሉ፥ በባሳንም ያሉት የኢያዕር መንደሮች ሁሉ ስድሳው ከተሞች፥ የገለዓድም እኩሌታ፥'),
  ('e3b6a1f8-1a57-5057-a3c2-8b725778f71f', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'c342face-d198-5598-a40f-3ccf10d42598', 3, 31, 'በባሳንም ያሉት የዐግ መንግሥት ከተሞች፥ አስጣሮትና ኤድራይን ነበረ። እነዚህም ለምናሴ ልጅ ለማኪር ልጆች ሆኑ፤ ለምናሴ ልጅ ለማኪር ልጆች እኩሌታም በየወገኖቻቸው ይህ ነበረ።'),
  ('7353f169-c6ee-5147-ad2f-591e9d2474e9', 'd915bf50-4498-598b-ac8d-2d1e032cc551', 'c342face-d198-5598-a40f-3ccf10d42598', 4, 32, 'ሙሴ በምሥራቅ በኩል በኢያሪኮ አንጻር በዮርዳኖስ ማዶ በሞዓብ ሜዳ ሳለ ርስት ያካፈላቸው እነዚህ ናቸው።'),
  ('8174dc39-bf58-5b9a-a022-e1f9c8eea39c', 'c995a0de-25c9-586d-a4d2-d0df793726ef', 'cbdcc3ee-e032-5356-ac02-2cb8a005b9d9', 1, 1, 'የእስራኤልም ልጆች በከነዓን ምድር የወረሱት ካህኑ አልዓዛርና የነዌ ልጅ ኢያሱ፥ የእስራኤልም ልጆች ነገድ የአባቶቻቸው አለቆች ያወረሱአቸው ርስት ይህ ነው።'),
  ('ab51b1b6-14c5-5107-a9cd-4023a140893e', 'c995a0de-25c9-586d-a4d2-d0df793726ef', 'cbdcc3ee-e032-5356-ac02-2cb8a005b9d9', 2, 2, 'እግዚአብሔር በሙሴ እጅ እንዳዘዘ ለዘጠኙ ነገድና ለእኩሌታው በየርስታቸው በዕጣ አከፋፈሉአቸው።'),
  ('eee8f369-02e2-5ae3-aa56-c7ef37af5b97', 'c995a0de-25c9-586d-a4d2-d0df793726ef', 'cbdcc3ee-e032-5356-ac02-2cb8a005b9d9', 3, 3, 'ለሁለቱ ነገድና ለእኩሌታው ነገድ በዮርዳኖስ ማዶ ሙሴ ርስት ሰጥቶ ነበር፤ ነገር ግን በመካከላቸው ለሌዋውያን ርስት አልሰጣቸውም።'),
  ('58f62af0-c5cc-58fc-afc2-c69f1f425821', 'c995a0de-25c9-586d-a4d2-d0df793726ef', 'cbdcc3ee-e032-5356-ac02-2cb8a005b9d9', 4, 4, 'የዮሴፍ ልጆች ምናሴና ኤፍሬም ሁለት ነገዶች ነበሩ፤ ለሌዋውያንም ከሚቀመጡባቸው ከተሞች ለእንስሶቻቸው ከሚሆን ማሰማሪያቸውና ከእንስሶቻቸውም በቀር በምድሩ ውስጥ ድርሻ አልሰጡአቸውም።'),
  ('ed6ded1c-21d6-5c22-a5d7-f53cf4d2d0f7', 'c995a0de-25c9-586d-a4d2-d0df793726ef', 'cbdcc3ee-e032-5356-ac02-2cb8a005b9d9', 5, 5, 'እግዚአብሔር ሙሴን እንዳዘዘ እንዲሁ የእስራኤል ልጆች አደረጉ፤ ምድሪቱንም ተካፈሉ።'),
  ('8c61d4e0-5f8b-5169-a5c0-12a32cc206cc', 'c995a0de-25c9-586d-a4d2-d0df793726ef', '50f3528a-8434-57fe-a5f8-8fc01e47cd8c', 1, 6, 'የይሁዳም ልጆች በጌልገላ ወደ ኢያሱ ቀረቡ፤ ቄኔዛዊውም የዮፎኒ ልጅ ካሌብ አለው፥ “ለአምላክ ሰው ለሙሴ ስለ እኔና ስለ አንተ እግዚአብሔር በቃዴስ በርኔ የተናገረውን ቃል ታውቃለህ።'),
  ('8cd932a0-1b4d-5878-a5af-919380122dbe', 'c995a0de-25c9-586d-a4d2-d0df793726ef', '50f3528a-8434-57fe-a5f8-8fc01e47cd8c', 2, 7, 'የእግዚአብሔር አገልጋይ ሙሴ ምድርን እሰልል ዘንድ ከቃዴስ በርኔ በላከኝ ጊዜ እኔ የአርባ ዓመት ሰው ነበርሁ፤ እኔም በልቡ የነበረውን ቃል መለስሁለት።'),
  ('3662d3d7-9bd7-5e22-a1c5-27f1c30c33b8', 'c995a0de-25c9-586d-a4d2-d0df793726ef', '50f3528a-8434-57fe-a5f8-8fc01e47cd8c', 3, 8, 'ከእኔ ጋር የወጡ ወንድሞች ግን የሕዝቡን ልብ አስካዱ፤ እኔ ግን አምላኬን እግዚአብሔርን ፈጽሜ እከተለው ዘንድ ተመለስሁ።'),
  ('cbc28cc5-517f-56ab-a049-739d8d539606', 'c995a0de-25c9-586d-a4d2-d0df793726ef', '50f3528a-8434-57fe-a5f8-8fc01e47cd8c', 4, 9, 'ሙሴም በዚያ ቀን፦ ‘አምላኬን እግዚአብሔርን ፈጽመህ ተከትለሃልና እግርህ የረገጠው ምድር ለአንተና ለልጆችህ ለዘለዓለም በርግጥ ርስት ይሆናል’ ብሎ ማለ።'),
  ('04399f08-70ed-5b5c-a24d-ce0d2e547e1a', 'c995a0de-25c9-586d-a4d2-d0df793726ef', '50f3528a-8434-57fe-a5f8-8fc01e47cd8c', 5, 10, 'አሁንም፥ እነሆ፥ እግዚአብሔር ለሙሴ ይህን ቃል ከተናገረ በኋላ፥ እስራኤል በምድረ በዳ ሲዞሩ፥ እርሱ እንደ ተናገረኝ እግዚአብሔር እነዚህን አርባ አምስት ዓመታት በሕይወት አኖረኝ፤ አሁንም፥ እነሆ፥ ለእኔ ዛሬ ሰማንያ አምስት ዓመት ሆነኝ።'),
  ('04e9c47c-e5c6-551f-a342-9c228db718bc', 'c995a0de-25c9-586d-a4d2-d0df793726ef', '50f3528a-8434-57fe-a5f8-8fc01e47cd8c', 6, 11, 'ሙሴም በላከኝ ጊዜ ጽኑዕ እንደ ነበርሁ፥ ዛሬም ገና እንዲሁ ለመዋጋት ለመውጣትም ለመግባትም ጽኑዕ ነኝ።'),
  ('59c8595f-6dc4-5b2c-a5f7-276ffb380e74', 'c995a0de-25c9-586d-a4d2-d0df793726ef', '50f3528a-8434-57fe-a5f8-8fc01e47cd8c', 7, 12, 'አሁን እንግዲህ በዚያ ቀን እግዚአብሔር የተናገረውን ይህን ተራራማ ሀገር ስጠኝ፤ አንተ በዚያ ቀን ዔናቃውያን፥ ታላላቆችና የተመሸጉ ከተሞችም በዚያ እንዳሉ ሰምተህ ነበር፤ እግዚአብሔር ከእኔ ጋር ቢሆን እግዚአብሔር እንደ ተናገረኝ አጠፋቸዋለሁ።”'),
  ('accfe28a-a9ec-54f8-ade4-2451ec44a633', 'c995a0de-25c9-586d-a4d2-d0df793726ef', '50f3528a-8434-57fe-a5f8-8fc01e47cd8c', 8, 13, 'ኢያሱም የቄኔዝ ልጅ፥ የዮፎኒ ልጅ ካሌብን ባረከው፤ ኬብሮንንም ርስት አድርጎ ሰጠው።'),
  ('cf4302fa-90f7-5ca2-aa38-12a155e97238', 'c995a0de-25c9-586d-a4d2-d0df793726ef', '50f3528a-8434-57fe-a5f8-8fc01e47cd8c', 9, 14, 'ስለዚህም የእስራኤልን አምላክ እግዚአብሔርን ፈጽሞ ስለ ተከተለ ኬብሮን እስከ ዛሬ ለቄኔዛዊው ለዮፎኒ ልጅ ለካሌብ ርስት ሆነች።'),
  ('96881e71-1c9e-51fe-ae0f-9ffbb7b2e8a2', 'c995a0de-25c9-586d-a4d2-d0df793726ef', '50f3528a-8434-57fe-a5f8-8fc01e47cd8c', 10, 15, 'የኬብሮንም ስም አስቀድሞ የአርቦቅ ከተማ ትባል ነበር፤ እርስዋም የዔናቃውያን ዋና ከተማ ነበረች። ምድሪቱም ከውጊያ ዐረፈች።'),
  ('435e16b8-6d09-5822-a1b4-d1ae29755eef', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 1, 1, 'የይሁዳም ነገድ ድንበር በየወገናቸው ከኤዶምያስ ዳርቻ፥ ከጺን ምድረ በዳ ጀምሮ በዐዜብ በኩል እስከ ቃዴስ ድረስ ነው።'),
  ('45a36c26-0be5-50f1-ac37-96b85c8861d9', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 2, 2, 'በደቡብም በኩል ያለው ድንበራቸው እስከ ጨው ባሕር ዳርቻ ወደ ሊባ እስከሚወስደው መንገድ ነበረ።'),
  ('a2c25238-915d-56d6-a197-3f99cd5be3bf', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 3, 3, 'ከዚያም በአቅረቢን ዐቀበት ፊት ይሄዳል፤ ወደ ጺንም ይወጣል፤ በቃዴስ በርኔ ወደ ደቡብ በኩል ይወጣል፤ በአስሮንም በኩል ያልፋል፤ ወደ ሰራዳም ይወጣል፥ ወደ ቃዴስ ምዕራብም ይዞራል።'),
  ('f23ae322-9d1f-52c8-abb4-5ccd7944b208', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 4, 4, 'ወደ አጽሞንም ያልፋል፤ በግብፅም ሸለቆ በኩል ይወጣል፤ የድንበሩም መውጫ በባሕሩ አጠገብ ነበረ፤ በደቡብ በኩል ያለው ድንበራቸው ይህ ነው።'),
  ('abcd80e5-e2f9-5a50-ab05-b342bbec7a1d', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 5, 5, 'በምሥራቅም በኩል ያለው ድንበራቸው እስከ ጨው ባሕር እስከ ዮርዳኖስም ነበረ። በሰሜንም በኩል ያለው ድንበር በዮርዳኖስ መጨረሻ እስካለው እስከ ባሕሩ ልሳን ድረስ ነበረ፤'),
  ('cc29f2c1-d98f-5e73-a0c9-ac3a876ca4ba', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 6, 6, 'ከዚያም ድንበራቸው ወደ ቤተ ገለዓም ይወጣል፤ በቤትዓረባ በሰሜን በኩል ያልፋል፤ ድንበራቸውም ወደ ሮቤል ልጅ ወደ ሊቶን ቢዮን ይወጣል፤'),
  ('ffe33be2-a4cd-5697-aaaa-ff5569d63343', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 7, 7, 'ድንበሩም በአኮር ሸለቆ አራተኛ ክፍል ላይ ይወጣል፤ በአዱሚን ዐቀበት ፊት ለፊት፥ በደቡብ በኩል ወዳለችው ወደ ጌልገላ ይወርዳል፤ ድንበሩም ወደ ፀሐይ ምንጭ ውኃ ያልፋል፤ መውጫውም በሮጌል ምንጭ አጠገብ ነበረ፤'),
  ('a0fe929e-2c53-50ff-ad92-3fcd5fd5dff2', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 8, 8, 'ድንበሩም በሄኖም ልጅ ሸለቆ አጠገብ ኢየሩሳሌም ወደምትባለው ወደ ኢያቡስ ወደ ደቡብ ወገን ይወጣል፤ ድንበሩም በሰሜን በኩል በራፋይም ሸለቆ ዳር ባለው በሄኖም ሸለቆ ፊት ለፊት በባሕር በኩል ወዳለው ተራራ ራስ ላይ ይወጣል፤'),
  ('d629db83-42ab-53e5-aa88-2df7b1bdce4c', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 9, 9, 'ድንበሩም ከተራራው ራስ ወደ ኔፍቶ ውኃ ምንጭ ይሄዳል፤ ወደ ዔፍሮንም ተራራ ይደርሳል፤ ወደ ኢያሪም ከተማ ወደ በኣላ ይደርሳል።'),
  ('482f19fd-13ac-5170-a3cf-da92a68beb53', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 10, 10, 'ድንበሩም ከበኣላ በባሕር በኩል ያልፋል፤ ከዚያም በኢያሪም ከተማ ደቡብ በኩልና በኪስሎን ሰሜን በኩል ወደ አሥራቱስ ድንበር ያልፋል፤ በፀሐይ ከተማም ላይ ይወርዳል፤ በሊባም በኩል ያልፋል።'),
  ('146920e2-9425-53b5-a786-65e0cdc16321', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 11, 11, 'ድንበሩም ወደ አቃሮን ደቡብ ይወጣል፤ ወደ ሰሜን ወገን ይመለሳል፤ ድንበሩ ወደ ሰቆት ይወጣል፤ ወደ ደቡብም ያልፋል፤ በሌብና በኩልም ይወጣል፤ የድንበሩም መውጫ በባሕሩ አጠገብ ነበረ።'),
  ('811e7205-077a-5043-a542-6ef046ea3054', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'dbe45dba-b229-5202-a109-ec88fa44728b', 12, 12, 'በባሕር በኩል ያለው ድንበራቸውም እስከ ታላቁ ባሕርና እስከ ዳርቻው ድረስ ነበረ። ለይሁዳ ልጆች በየወገናቸው በዙሪያው ያለ ድንበራቸው ይህ ነው።'),
  ('083aa0d9-cc6b-5328-a248-8486970da510', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', '4f84f35f-9097-5607-acef-cdf3b13c083e', 1, 13, 'በእግዚአብሔርም ትእዛዝ ለዮፎኒ ልጅ ለካሌብ በይሁዳ ልጆች መካከል ድርሻውን ሰጠው፤ ኢያሱም የዔናቅ ዋና ከተማ የሆነችውን የአርቦቅን ከተማ ሰጠው። እርስዋም ኬብሮን ናት።'),
  ('97e8630b-e32f-5c7d-a830-bf20a7b78aeb', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', '4f84f35f-9097-5607-acef-cdf3b13c083e', 2, 14, 'የዮፎኒ ልጅ ካሌብም ሦስቱን የዔናቅን ልጆች ሱሲን፥ ተለሚንና አካሚን ከዚያ አጠፋቸው።'),
  ('ce6838e9-5f9b-5bee-a6a7-806bcaef6be0', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', '4f84f35f-9097-5607-acef-cdf3b13c083e', 3, 15, 'ከዚያም ካሌብ በዳቤር ሰዎች ላይ ዘመተ፤ የዳቤርም ስም አስቀድሞ “ሀገረ መጻሕፍት” ነበረ።'),
  ('f37c3bc7-3383-5e36-af0c-2f7a03e2057d', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', '4f84f35f-9097-5607-acef-cdf3b13c083e', 4, 16, 'ካሌብም፥ “ሀገረ መጻሕፍትን ለሚመታ፥ ለሚይዛትም ልጄን አክሳን ሚስት ትሆነው ዘንድ እሰጠዋለሁ” አለ።'),
  ('0a10e255-1db0-5abe-a0ff-9731be9435e9', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', '4f84f35f-9097-5607-acef-cdf3b13c083e', 5, 17, 'የካሌብ ወንድም የቄኔዝ ልጅ ጎቶንያል ያዛት፤ ልጁን አክሳንም ሚስት ትሆነው ዘንድ ሰጠው።'),
  ('1dce0163-b6ea-5156-a7ec-80f6401e0715', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', '4f84f35f-9097-5607-acef-cdf3b13c083e', 6, 18, 'እርስዋም ወደ እርሱ በመጣች ጊዜ “አባቴን እርሻ ልለምነው” ብላ አማከረችው፤ እርስዋም በአህያዋ ላይ ሆና ጮኸች፤ ካሌብም፥ “ምን ሆንሽ?” አላት።'),
  ('f8262965-bc02-5460-ad3b-f3fbb661893c', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', '4f84f35f-9097-5607-acef-cdf3b13c083e', 7, 19, 'እርስዋም፥ “በረከትን ስጠኝ፤ በደቡብ በኩል ያለውን ምድር ሰጥተኸኛልና አሁን ደግሞ የውኃውን ምንጭ ስጠኝ” አለችው። እርሱም የላይኛውንና የታችኛውን ምንጭ ሰጣት።'),
  ('cf0c9fac-a342-5dee-a36c-250a84cb59fe', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 1, 20, 'በየወገኖቻቸውም የይሁዳ ልጆች ነገድ ርስት ይህ ነው።'),
  ('eb0c65e9-aaea-534c-af91-da6cf0dca237', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 2, 21, 'በደቡብም በኩል በምድራቸው ዳርቻ እስከ ኤዶምያስ ድንበር ያሉት የይሁዳ ልጆች ነገድ ከተሞች እነዚህ ነበሩ፤ ቤሴሌኤል፥ አራ፥ አሦር፤'),
  ('bc98d1e9-d122-50c5-a39a-38d030b737c1', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 3, 22, 'ኤቃም፥ ሬግማ፥ አሩሔል፤'),
  ('ae4ba92e-975b-5d01-a8a7-c6dd731cf27a', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 4, 23, 'ቃዴስ፥ አሶርዮስም፤ ሚናን፤'),
  ('c4990367-ab21-59a8-a092-728bdb0075a5', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 5, 24, 'በልማንና መንደሮቻቸውም፤'),
  ('3f2f2b96-c41d-52ab-aa67-4aba8f02b44e', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 6, 25, 'የአሴሮም ከተሞች እርስዋም አሶር ናት።'),
  ('90258463-378d-5a3c-a56b-728a7dbc4f80', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 7, 26, 'ሲን፥ ሰላማዓ፥ ሞላዳ፤'),
  ('87e64e4c-a697-5407-afe2-32a6a50b5d23', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 8, 27, 'ሴሪ፥ ቤፋላድ፤'),
  ('3280f52b-41e9-5f4b-abae-932cbc21cf3d', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 9, 28, 'ኮላሴዎል፥ ቤርሳቤሕና መንደሮቻቸው።'),
  ('3792db3c-9197-5bcc-afe7-97024a10e564', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 10, 29, 'ባላ፥ ባቆብና አሶም፤'),
  ('60548624-c76b-5c6b-a4dc-053ad54846d5', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 11, 30, 'ኤለቦሂዳድ፥ ቤቴልና ኤርማም፤'),
  ('a5a84511-a49b-5ae0-adac-a6921772fd65', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 12, 31, 'ሴቄላቅ፥ ማኬሪምር፥ ሴቱናቅ፤'),
  ('488cd9cb-ab11-5cb8-a087-614eddf5fd18', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 13, 32, 'ላቦስ ሳሌ፥ ኤርሞትም ሃያ ዘጠኝ ከተሞችና መንደሮቻቸው።'),
  ('ded4396e-bc5b-5b9a-aae2-d1f0dab46c99', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 14, 33, 'በቆላው፥ አስጣል፥ ሳራዓ፥ አሳ፤'),
  ('df8a133b-7518-5e4a-ab48-adf5b716a51f', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 15, 34, 'ራሜ፥ ጣኖ፥ ኢዱቶት፥ መሐንስ፤'),
  ('fd22566f-4906-5aa1-a5d3-f891cb4de10e', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 16, 35, 'ኤርሙት፥ ኤዶላም፥ ሜምብራ፥ ሰአክ፥ አዚቃ፤'),
  ('54886ee9-1c8f-5aa5-a175-e00cc46f87ab', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 17, 36, 'ሴቃርም፥ ጋዴርና ሰፈሮችዋ፥ ዐሥራ አራት ከተሞችና መንደሮቻቸው።'),
  ('3a76ce17-6152-515a-af54-e2b22435a7d7', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 18, 37, 'ሴና፥ አዳሶን፥ ማጋዳልጋድ፤'),
  ('93d3da20-bb07-51de-a43e-9fc9524cbc91', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 19, 38, 'አዶላል፥ መሴፋ፥ ይቃሩል፥ ለኪስ፤'),
  ('68e31d13-6908-5f14-a072-80f77eb59b71', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 20, 39, 'በሴዶት ይዴሃ፥ ደልያም፤'),
  ('8ed0c6c8-0aa3-54cf-ad92-707f6b1d41d2', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 21, 40, 'ኮብራ፥ ማኬስ፥ መሐኮስም፤'),
  ('6d9fd435-107c-5569-afc7-43d122abe2c0', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 22, 41, 'ጌዶር፥ በጋድያል፥ ኖማን፥ መቄዶም፥ ዐሥራ ስድስት ከተሞችና መንደሮቻቸው።'),
  ('fe0cda06-e52e-5c2a-a66b-062971cf13bb', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 23, 42, 'ሌምና፥ ኤተቅ፥ አኖክ፥'),
  ('13cc0b6f-8430-506a-a821-9df13ed6f7ed', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 24, 43, 'ኢድና ናሲብም፤'),
  ('f470ecf0-457c-51f3-ac54-3948cbc0ccd0', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 25, 44, 'ኤላም፥ አቁዛም፥ ኬዜብ ቴርሳ፥ ኤሎምም፥ ዐሥር ከተሞችና መንደሮቻቸው።'),
  ('2a2f8c03-8460-52b4-aea1-2861255759e4', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 26, 45, 'አቃሮን ከመንደሮችዋና ከመሰማሪያዎችዋ ጋር።'),
  ('bd655817-a493-5e75-a99d-2df92da3ba96', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 27, 46, 'ከአቃሮንና ከጌምና ጀምሮ በአሴዶት አቅራቢያ ያሉ ሁሉና መንደሮቻቸው፤'),
  ('359ab088-4b92-5782-a267-26637b6271f6', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 28, 47, 'አሴያዶት መንደሮችዋና መሰማሪያዎችዋም፥ ጋዛም መንደሮችዋና መሰማሪያዎችዋም እስከ ግብፅ ወንዝ ድረስ፥ ታላቁ ባሕርም ወሰኑ ነው።'),
  ('ee5223b4-9d84-51c3-a26f-75ecfb0a06e3', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 29, 48, 'የሳምር ተራራዎች ፥ ኢዩቴር፥ ሦካ፤')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('99193b0d-7454-5f47-ae53-12db18ae289d', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 30, 49, 'ሬና፥ የመጽሐፍ ሀገር የሆነች ዳቤር፤'),
  ('72c3a657-349d-5b3b-a2ff-b53199698af5', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 31, 50, 'አኖን፥ ሴቄማ፥ ኤሳማም፤'),
  ('58d67339-9358-5564-a9a6-a31c181fc111', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 32, 51, 'ጎሶም ከሉም፥ ከናም፥ ዐሥራ አንድ ከተሞችና መንደሮቻቸው።'),
  ('64ca4b72-a959-581d-a589-3a1a72366c7c', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 33, 52, 'ኤሬም፥ ሬምና፥ ሶማ፤'),
  ('2690eac1-928a-523e-ae0b-667fb2202393', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 34, 53, 'ኢያማይን፥ ቤታቁም፥ ፋቁሕ፤'),
  ('033c818f-0d9e-5ded-a257-f2251debd7a3', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 35, 54, 'ኤውማ፥ የአርቦቅ ከተማ እርስዋም ኬብሮን ናት፥ ሶሬት፥ ዘጠኝ ከተሞችና መንደሮቻቸው።'),
  ('5ec38840-51c9-518b-a6c7-e00ef205d1db', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 36, 55, 'ማሖር፥ ኬርሜል፥ አዚብ፥ ኢጣን፤'),
  ('0a32dcfa-bb99-58a6-a2bd-d9be66081528', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 37, 56, 'ኢያሬዬል፥ ኢያሪቅም፥ ዘቃይንም፤'),
  ('acf745b9-7bc5-5099-adde-9ad0989bc517', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 38, 57, 'ጋባ፥ ተምና፥ ዘጠኝ ከተሞችና መንደሮቻቸው።'),
  ('861db3b4-6f0b-5a03-a362-75d8a5cd4d4e', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 39, 58, 'አሌዋ፥ ቤተሱር፥ ጌዶር፤'),
  ('81afbd27-c2ce-5d2c-a2a5-e90753dc27ad', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 40, 59, 'ማዕራት፥ ቤትአኖት፥ ኤልትቆን፥ ስድስት ከተሞችና መንደሮቻቸው።'),
  ('9e95d950-ed10-58ea-acc8-d1790ca90ad5', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 41, 60, 'ቴቆ፥ ኤፍራታ፥ ይኽችውም ቤተ ልሔም ናት፤ ፋጎርም፥ ኤጣንም፥ ቁሎን፥ ጠጦንም፥ ሶብሄም፥ ቃሬም፥ ጌሌም፥ ኤቴር፥ መነኮም፥ ዐሥራ አንድ ከተሞችና መንደሮቻቸው፥ ቅርያትበኣል፥ ይኽችውም የኢያርም ከተማ ናት፤ ሶቤታ፥ ሁለቱ ከተሞችና መንደሮቻቸው።'),
  ('181d6c5c-7b5e-5c82-a1f2-0cf13db2a327', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 42, 61, 'ባዳርጊስ፥ ተራብዐምም፥ ኤኖን፤ ሴኬዎዛን፥'),
  ('0eda4e56-e2bb-5c76-a1f2-3e9da795e175', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 43, 62, 'ናፍላዛንና ከተሞቻቸው፥ ሳዶን፥ አቃዴስ፥ ሰባት ከተሞችና መንደሮቻቸው።'),
  ('5f5f8d46-3108-5f5d-a49d-91de91144088', '960f42c4-ce8d-553c-aa9f-b8ddcfa44f60', 'e2a84abe-5de4-5d6f-a46e-1ffe944c0006', 44, 63, 'በኢየሩሳሌም የተቀመጡትን ኢያቡሴዎናውያንን ግን የይሁዳ ልጆች ሊያሳድዱአቸው አልተቻላቸውም፤ ኢያቡሴዎናውያንም እስከ ዛሬ ድረስ በይሁዳ ልጆች መካከል በኢየሩሳሌም ውስጥ ተቀምጠዋል።'),
  ('8170b00d-c52f-55fc-a45f-2b45e1a43fb4', '9eeb2df6-ae30-5e80-ae00-adeca04c5249', '5d311dab-5fca-5267-a66e-5ea25fdeebf2', 1, 1, 'የዮሴፍም ልጆች ድንበራቸው በኢያሪኮ አንጻር በምሥራቅ በኩል ካለው ከዮርዳኖስ አንሥቶ በምድረ በዳውና በተራራማው በኩል ከኢያሪኮ ሎዛ ትባል ወደ ነበረችው ቤቴል ይደርሳል፤'),
  ('5e530dd7-d816-5b60-a0f0-a15e886d9c07', '9eeb2df6-ae30-5e80-ae00-adeca04c5249', '5d311dab-5fca-5267-a66e-5ea25fdeebf2', 2, 2, 'ከቤቴል ሎዛም በከሮንቲ ዳርቻ በኩል ወደ አጣሮት አውራጃ ይደርሳል፤'),
  ('19303585-c3ca-5102-a683-56e306a1afe7', '9eeb2df6-ae30-5e80-ae00-adeca04c5249', '5d311dab-5fca-5267-a66e-5ea25fdeebf2', 3, 3, 'ወደ ምዕራብም እስከ የፍሌጣውያን ዳርቻ እስከ ታችኛው ቤቶሮን ዳርቻ ድረስ ይወርዳል፤ መውጫውም በባሕሩ አጠገብ ነበረ።'),
  ('206d2471-1588-56ed-a01e-9ae3cc4bef09', '9eeb2df6-ae30-5e80-ae00-adeca04c5249', '5d311dab-5fca-5267-a66e-5ea25fdeebf2', 4, 4, 'የዮሴፍም ልጆች ምናሴና ኤፍሬም ርስታቸውን ወረሱ።'),
  ('c7f8aa90-e5d6-5340-a21b-8ea310f23b94', '9eeb2df6-ae30-5e80-ae00-adeca04c5249', '7585be42-81ae-56cc-a964-c1c30816ecb2', 1, 5, 'የኤፍሬምም ልጆች ድንበር በየወገኖቻቸው እንደዚህ ነበረ፤ የርስታቸው ድንበር ከአጣሮትና፥ ከኤሮሕ ምሥራቅ ከጋዛራ እስከ ላይኛው ቤቶሮን ድረስ ነበረ፤'),
  ('8ef3d598-05b7-5c8a-a1ac-e02637740457', '9eeb2df6-ae30-5e80-ae00-adeca04c5249', '7585be42-81ae-56cc-a964-c1c30816ecb2', 2, 6, 'ድንበሩም ወደ ምዕራብ ወደ አካስሞን በቴርማ ሰሜን ያልፋል፤ ወደ ምሥራቅም ወደ ቲናስና ሴላስ ይዞራል፥ ከምሥራቅም ወደ ኢያኖክ ያልፋል።'),
  ('36e727d3-9a21-5690-a538-34f86fcee9c7', '9eeb2df6-ae30-5e80-ae00-adeca04c5249', '7585be42-81ae-56cc-a964-c1c30816ecb2', 3, 7, 'ከኢያኖክም ወደ መአኮና፥ ወደ አጣሮትም፥ ወደ መንደሮቻቸውም ያልፋል፤ ወደ ኢያሪኮም ይገባል፥ ወደ ዮርዳኖስም ይወጣል።'),
  ('f36e5e1e-9de8-5994-a4ad-cd1e156c1ed0', '9eeb2df6-ae30-5e80-ae00-adeca04c5249', '7585be42-81ae-56cc-a964-c1c30816ecb2', 4, 8, 'ድንበሩም ከጣፉ ወደ ባሕር እስከ ኬልቃን ወንዝ ድረስ ያልፋል፥ መውጫውም በባሕሩ አጠገብ ነበረ። የኤፍሬም ልጆች ነገድ ርስት በየወገኖቻቸው ይህ ነበረ።'),
  ('d04b8e2e-3425-5e10-af5f-a083e578d128', '9eeb2df6-ae30-5e80-ae00-adeca04c5249', '7585be42-81ae-56cc-a964-c1c30816ecb2', 5, 9, 'ይኸውም በምናሴ ልጆች ርስት መካከል ለኤፍሬም ልጆች ከተለዩ ከተሞች ጋር፥ ከተሞች ሁሉ ከመንደሮቻቸው ጋር ነው።'),
  ('53ce3c38-c435-5727-aff0-751caf0633ba', '9eeb2df6-ae30-5e80-ae00-adeca04c5249', '7585be42-81ae-56cc-a964-c1c30816ecb2', 6, 10, 'በጋዜርም የተቀመጡትን ከነዓናውያንን ኤፍሬም አላጠፋቸውም፤ እስከ ዛሬም ድረስ ከነዓናውያን በኤፍሬም መካከል ተቀምጠዋል፤ ገባርም ሆኑ።'),
  ('e1b367d1-0813-54a8-a7f2-42ed27b126ce', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 1, 1, 'የምናሴ ልጆች ነገድ ድንበር ይህ ነው፤ የዮሴፍ በኵር እርሱ ነውና። የምናሴም በኵር የገለዓድ አባት ማኪር ብርቱ ተዋጊ ስለ ነበረ ገለዓድንና ባሳንን ወረሰ።'),
  ('f20d3b3e-1e20-5cef-a7a5-5d6e02a165e6', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 2, 2, 'ዕጣውም ለቀሩት ለምናሴ ልጆች በየወገኖቻቸው፥ ለኢያዜር ልጆች፥ ለቄሌዝ ልጆች፥ ለኢየዚኤል ልጆች፥ ለሴኬም ልጆች፥ ለሱማሪም ልጆች፥ ለኦፌር ልጆች ሆነ፤ ወንዶቹ በየወገኖቻቸው እነዚህ ናቸው።'),
  ('e0546f6b-d61b-5fe3-ab6a-d5587c390a51', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 3, 3, 'ለኦፌር ልጅ፥ ለሰለጰዓድ ግን ሴቶች ልጆች እንጂ ወንዶች ልጆች አልነበሩትም፤ የሰለጰዐድም የሴቶች ልጆቹ ስሞች፦ መሐላ፥ ኑዓ፥ ሔግላ፥ ሚልካ፥ ቴርሳ ነበሩ።'),
  ('65ccaaf3-4dd6-502b-a96e-c029ec694cd0', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 4, 4, 'እነርሱም ወደ ካህኑ ወደ አልዓዛርና ወደ ነዌ ልጅ ወደ ኢያሱ ወደ አለቆችም ቀርበው፥ “እግዚአብሔር በወንድሞቻችን መካከል ርስት እንዲሰጠን በሙሴ እጅ አዘዘ” አሉ፤ በእግዚአብሔርም ትእዛዝ ከአባታቸው ወንድሞች ጋር ርስት ሰጣቸው።'),
  ('cfb6d9f9-f732-5794-afaf-42842b10584a', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 5, 5, 'ዕጣቸውም በዮርዳኖስ ማዶ ከአለው ከገለዓድና ከባሳን ሀገር በቀር ለምናሴ ዐሥር ዕጣ ሆነ፤'),
  ('74caad6e-2253-5cd3-a872-550a500a0f3e', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 6, 6, 'የምናሴ ሴቶች ልጆች በወንድሞቻቸው መካከል ርስት ተቀብለዋልና፤ የገለዓድም ምድር ለቀሩት ለምናሴ ልጆች ሆኖአልና።'),
  ('e36b7b71-4eb3-54ee-ad35-6bf73b9d77d7', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 7, 7, 'የምናሴም ልጆች ድንበር በሐነት ልጆች ፊት ያለው ዴላናታ ነው። በኢያሚንና በኢያሲብ ድንበር በተፍቶት ምንጭ ላይ ያልፋል።'),
  ('b2697d00-f94d-50d0-a41f-de09ce788215', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 8, 8, 'የጣፌት ምድር ለምናሴ ነበረ፤ ጣፌት ግን በኤፍሬም ልጆችና በምናሴ ልጆች አውራጃ ያለ ነው።'),
  ('0c934e96-6ed7-5feb-a0c7-256080c87c63', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 9, 9, 'ድንበራቸውም በደቡብ በኩል ወዳለው ወደ ቃራና ሸለቆና ወደ ኢያሪያል ሸለቆ ይወርዳል፤ የኤፍሬም ዕጣ የሆነው ጤሬሜንቶስ የሚባለው ዛፍም በምናሴ ከተሞች መካከል አለ፤ የምናሴም ድንበር በሰሜን በኩል ወደ ወንዙ ይወርዳል፤ መውጫውም በባሕሩ አጠገብ ነበረ።'),
  ('2568f3a7-61a7-5353-a704-382b04b6b8ed', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 10, 10, 'በደቡብ በኩል ያለው ለኤፍሬም ነበረ፤ በሰሜን በኩል ያለውም ለምናሴ ነበረ፤ ድንበሩም ባሕር ነበረ፤ በሰሜን በኩል ወደ አሴር፥ በምሥራቅም በኩል ወደ ይሳኮር ይደርሳል።'),
  ('8a0f0282-9707-5f94-a099-e5ceacb4fd97', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 11, 11, 'በይሳኮርና በአሴር መካከል ቤትሳንና መንደሮችዋ፥ ዶርና መንደሮችዋ፥ መጌዶና መንደሮችዋ፥ የመፌታ ሦስተኛ እጅና መንደሮችዋ ለምናሴ ነበሩ።'),
  ('d992f635-ff8b-5ab3-a157-bf69c90400e1', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 12, 12, 'የምናሴ ልጆችም የእነዚህን ከተሞች ሰዎች ማጥፋት ተሳናቸው፤ ነገር ግን ከነዓናውያን በዚያች ሀገር ለመቀመጥ መጡ።'),
  ('2abe5a8a-b2eb-5ed0-a5fc-eca665dff2fc', 'ef348849-dbe4-55da-a4d0-962bada49b7d', 'ed000659-d337-583d-adaa-a026b4a78da2', 13, 13, 'የእስራኤልም ልጆች በረቱባቸው፤ ከነዓናውያንንም ገዙአቸው፤ ነገር ግን ፈጽመው አላጠፉአቸውም።'),
  ('ae067dc2-4474-5c42-af44-76795ed817f5', 'ef348849-dbe4-55da-a4d0-962bada49b7d', '6624039a-38f8-5a02-aafa-8f99539bcd79', 1, 14, 'የዮሴፍም ልጆች ኢያሱን፥ “እኛ ብዙ ሕዝብ ስንሆን እስከ አሁንም እግዚአብሔር ስለ ባረከን ለምን አንድ ክፍል፥ አንድም ዕጣ ብቻ ርስት አድርገህ ሰጠኸን?” ብለው ወቀሱት።'),
  ('89de5f2b-f84f-5f17-a0dd-baf14319bd53', 'ef348849-dbe4-55da-a4d0-962bada49b7d', '6624039a-38f8-5a02-aafa-8f99539bcd79', 2, 15, 'ኢያሱም፥ “ብዙ ሕዝብ ከሆናችሁ፥ ተራራማው የኤፍሬም ሀገርም ከጠበባችሁ ወደ ዱር ወጥታችሁ መንጥራችሁ አቅኑአት” አላቸው።'),
  ('c0b50b91-0dca-5408-af20-c2a13b7f96f6', 'ef348849-dbe4-55da-a4d0-962bada49b7d', '6624039a-38f8-5a02-aafa-8f99539bcd79', 3, 16, 'እነርሱም፥ “ተራራማው የኤፍሬም ሀገር አይበቃንም፤ በሸለቆው ውስጥ ለሚኖሩት፥ በቤትሳንና በመንደሮችዋ፥ በኢይዝራኤልም ሸለቆ ለሚኖሩት ከነዓናውያን የተመረጡ ፈረሶችና ሰይፍ አሏቸው” አሉት።'),
  ('3bdc1ea0-fd82-59af-ad37-fec6d92e2539', 'ef348849-dbe4-55da-a4d0-962bada49b7d', '6624039a-38f8-5a02-aafa-8f99539bcd79', 4, 17, 'ኢያሱም ለዮሴፍ ልጆች፥ “እናንተ ብዙ ሕዝብ ከሆናችሁ፥ ጽኑ ኀይልም ከአላችሁ አንድ ዕጣ ብቻ አይሆንላችሁም፤'),
  ('c4babdc8-2954-5750-a8d1-2d8a39f8318a', 'ef348849-dbe4-55da-a4d0-962bada49b7d', '6624039a-38f8-5a02-aafa-8f99539bcd79', 5, 18, 'ነገር ግን ተራራማው ሀገር ለእናንተ ይሆናል፤ ዱር እንኳ ቢሆንም ትመነጥሩታላችሁ፤ ለእናንተም ይሆናል፤ ለከነዓናውያንም የተመረጡ ፈረሶችና የብረት ሰረገሎች ቢሆኑላቸው፥ የበረቱ ቢሆኑም እናንተ እስክታጠፉአቸው ድረስ ትበረቱባቸዋላችሁ” አላቸው።'),
  ('3e6d38db-9cc7-5123-a5b9-ef741ca3d295', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', 'b00d3d65-32b0-5aab-abed-4c5d7dec1d52', 1, 1, 'የእስራኤልም ልጆች ማኅበር ሁሉ በሴሎ ተሰበሰቡ፤ በዚያም የምስክሩን ድንኳን ተከሉ፤ ምድሩም ጸጥ ብሎ ተገዛላቸው።'),
  ('e5bf701d-4ca4-515f-a06e-17ac42909687', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', 'b00d3d65-32b0-5aab-abed-4c5d7dec1d52', 2, 2, 'ከእስራኤልም ልጆች ርስት ያልተካፈሉ ሰባት ነገድ ቀርተው ነበር።'),
  ('74fe315e-fa8a-596f-a96d-4feaf098387c', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', 'b00d3d65-32b0-5aab-abed-4c5d7dec1d52', 3, 3, 'ኢያሱም የእስራኤልን ልጆች አላቸው፥ “የአባቶቻችሁ አምላክ እግዚአብሔር የሰጣችሁን ምድር እንዳትወርሱአት እስከ መቼ ድረስ ታቈዩአታላችሁ?'),
  ('14e239b9-51eb-50c1-ab0b-104dbf540acc', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', 'b00d3d65-32b0-5aab-abed-4c5d7dec1d52', 4, 4, 'ከየነገዳችሁ ሁሉ ሦስት ሦስት ሰዎችን አምጡ፥ ተነሥተውም ሀገሪቱን ይዙሩአት፤ ለመክፈልም እንዲያመች ገልጠው ይጻፉአት፤ ወደ እኔም ይመለሳሉ።'),
  ('5df4ec9d-7026-57a7-a35e-2f6fe0e3c1f8', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', 'b00d3d65-32b0-5aab-abed-4c5d7dec1d52', 5, 5, 'በሰባትም ክፍል ይከፍሉታል፤ ይሁዳ በደቡብ በኩል በዳርቻው ውስጥ ይቀመጣል፤ የዮሴፍም ልጆች በሰሜን በኩል በዳርቻው ውስጥ ይቀመጣሉ።'),
  ('d0ee0140-23aa-5eed-ae25-d18f66bdb629', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', 'b00d3d65-32b0-5aab-abed-4c5d7dec1d52', 6, 6, 'እናንተም ምድሪቱን በሰባት ክፍል ክፈሏት፤ ወደ እኔም ወዲህ አምጡልኝ፤ በአምላካችንም በእግዚአብሔር ፊት በዚህ ዕጣ አጣጥላችኋለሁ።'),
  ('44006234-a493-58eb-a974-f3e9b8fe389d', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', 'b00d3d65-32b0-5aab-abed-4c5d7dec1d52', 7, 7, 'ነገር ግን የእግዚአብሔር ክህነት ርስታቸው ነውና ለሌዊ ልጆች በመካከላችሁ እድል ፋንታ የላቸውም፤ ጋድም፥ ሮቤልም፥ የምናሴም ነገድ እኩሌታ በዮርዳኖስ ማዶ በምሥራቅ በኩል የእግዚአብሔር አገልጋይ ሙሴ የሰጣቸውን ርስታቸውን ተቀብለዋል።”'),
  ('56be0d23-bece-5c11-aa18-ed3e6761747f', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', 'b00d3d65-32b0-5aab-abed-4c5d7dec1d52', 8, 8, 'ሰዎችም ተነሥተው ሄዱ፤ ኢያሱም ምድሩን ሊጽፉ የሄዱትን፥ “ሂዱ፤ ምድሩንም ዞራችሁ ጻፉት፤ ወደ እኔም ተመለሱ፤ በዚህም በሴሎ በእግዚአብሔር ፊት ዕጣ አጣጥላችኋለሁ” ብሎ አዘዛቸው።'),
  ('8d038198-3f37-5799-ac02-5ba7bd4cf2c2', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', 'b00d3d65-32b0-5aab-abed-4c5d7dec1d52', 9, 9, 'ሰዎቹም ሄደው ምድሩን ዞሩ፥ አዩትም፤ እንደ ከተሞችም በሰባት ክፍል ከፈሉት፤ በመጽሐፍም ጻፉት፤ ወደ ኢያሱም አመጡ።'),
  ('c3e4a819-3ca9-5f31-a8b5-ac731e5d971a', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', 'b00d3d65-32b0-5aab-abed-4c5d7dec1d52', 10, 10, 'ኢያሱም በእግዚአብሔር ፊት በሴሎ ዕጣ አጣጣላቸው።'),
  ('d3ea49a0-70cc-5254-a014-81461db2ddd0', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 1, 11, 'የብንያምም ነገድ ዕጣ በየወገኖቻቸው በቅድሚያ ወጣ፤ የዕጣቸውም ዳርቻ በይሁዳ ልጆችና በዮሴፍ ልጆች መካከል ወጣ።'),
  ('ae8b02ab-2ef9-5be2-aae5-6d6014afa3ce', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 2, 12, 'በሰሜን በኩል ድንበራቸው ከዮርዳኖስ ጀመረ፤ ድንበሩም ከኢያሪኮ አዜብ ወደ ሰሜን ወገን ወጣ፥ ከዚያም በተራራማው ሀገር ወደ ባሕር ወጣ፤ መውጫውም የቤቶን ምድብራይጣስ ነበረ።'),
  ('fd0badf8-f813-587e-af31-748908bfe7a1', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 3, 13, 'ድንበሩም ከዚያ በደቡብ በኩል ቤቴል ወደምትባል ወደ ሎዛ ዐለፈ፤ ድንበሩም በታችኛው ቤቶሮን ደቡብ በኩል ባለው ተራራ ወደ ማአጣሮቶሬክ ወረደ።'),
  ('da8f7f5a-8dda-5165-a930-4a9c32584d88', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 4, 14, 'ድንበሩም ወደ ባሕር ሄደ፤ በቤቶሮንም ፊት ለፊት ካለው ተራራ ወደ አዜብ ዞረ፤ መውጫውም ቂርያታርም በምትባል በይሁዳ ልጆች ከተማ በቂርያትበኣል ነበረ፤ ይህ በባሕር በኩል ነበረ።'),
  ('0265a4ce-f570-5f64-a59a-e9bc179956e7', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 5, 15, 'የደቡብም ዳርቻ ከቅርያታርም መጨረሻ ነበረ፤ ድንበሩም በጋሲን ላይ ወደ ነፍቶ ውኃ ምንጭ ወጣ።'),
  ('2c4b8225-2d14-5249-a7b8-9adc33624f2b', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 6, 16, 'ድንበሩም በሄኖም ሸለቆ ፊት ለፊት ወዳለው ተራራ መጨረሻ ወረደ፤ እርሱም በራፋይም ሸለቆ በሰሜን በኩል ነው፤ ወደ ሄኖም ሸለቆ ወደ ኢያቡስ ዳር በደቡብ በኩል ወረደ፥ ወደ ሮጌል ምንጭም ወረደ።'),
  ('4a0929ff-072c-5960-a172-8d65874a263b', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 7, 17, 'ወደ ቤተሳሚስም ምንጭ ያልፋል፤ በኢታሚም አቀበት ፊት ለፊት ወዳለው ወደ ኬልዩት ይገባል፤ ወደ ሮቤልም ልጅ ወደ ቤዎን ድንጋይ ይወርዳል፤'),
  ('446800f6-839a-5f1a-a994-2e35704e3465', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 8, 18, 'በሰሜንም በኩል ወደ ቤተ ራባ ጀርባ ያልፋል። በመስዕም ወደ ባሕር መንገድ ይወርዳል፤'),
  ('e6fd8d08-e99d-5e96-a0ba-d0b0e0a958d6', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 9, 19, 'የድንበራቸውም ፍጻሜ በሰሜን በኩል ወደ ጨው ባሕር ልሳን ይደርሳል፤ በደቡብም በኩል ድንበራቸው ዮርዳኖስ ነው። ይህም በደቡብ በኩል ያለው ድንበር ነው።'),
  ('512c3b0a-85f2-553b-ab20-c5340231c494', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 10, 20, 'በምሥራቅም በኩል ድንበሩ ዮርዳኖስ ነበረ። ይህ በዙሪያቸው ዳርቻ በየወገኖቻቸው የብንያም ልጆች ርስት ነበረ።'),
  ('2ed8578a-46ce-5d5f-a961-9f2ebc644cd2', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 11, 21, 'የብንያምም ልጆች ነገድ ከተሞች በየወገኖቻቸው እነዚህ ነበሩ፤ ኢያሪኮ፥ ቤትሖግሊ፥ ዐመቀስስ፤'),
  ('63a1af31-0748-5877-a844-e15d2d5128e0', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 12, 22, 'ቤተ ባራ፥ ሰራ፥ ቤስና፤'),
  ('dd738120-4918-550f-acab-10b3b1ad5d91', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 13, 23, 'አኢን፥ ፋራ፥ ኤፍራታም፥'),
  ('4a6bf7bf-6629-5c04-a290-de0bb87f2bfe', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 14, 24, 'ቃራፋ፥ ቄፍራ፥ ሞኒ፥ ጋባህ፤ ዐሥራ ሁለቱ ከተሞችና መንደሮቻቸው።'),
  ('608f9ccd-b6fd-5668-a149-768562de6581', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 15, 25, 'ገባዖን፥ ራማ፥ ብኤሮት፤'),
  ('9b37bf47-f91b-502b-ab9d-b56ea1fb95bb', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 16, 26, 'ማሴማ፥ ቤሮን፥ አሞቂ፥'),
  ('ad9c9ffa-0109-5fe5-a4ac-75769de39fc3', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 17, 27, 'ቤራ፥ ቃፋን፥ ናቃና፥ ሴሌቃን፥ ታራኤላ፤'),
  ('c0704fa5-0b97-5c6b-af1b-148c09a6cd18', '360f0e5b-a296-58e7-a0e8-76f8c3eee345', '2557c3e1-e38d-5733-a2bf-d6d11d4bd596', 18, 28, 'ኢየሩሳሌም የምትባል የኢያቡሴዎን ከተማና የኢያሪሞን ከተማ ገባዖን፤ ዐሥራ ሦስት ከተሞችና መንደሮቻቸው። የብንያም ልጆች ርስት በየወገኖቻቸው ይህ ነበረ።'),
  ('a448ed8a-a261-50ac-a371-63e9621f73cc', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '7f756774-4cf4-538e-a823-6bf5e0b2ceba', 1, 1, 'ሁለተኛውም ዕጣ ለስምዖን ልጆች ነገድ በየወገኖቻቸው ወጣ፤ ርስታቸውም በይሁዳ ልጆች ርስት መካከል ነበረ።'),
  ('eacd7e5e-6c3a-586c-a0ff-a0f6d3f792bc', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '7f756774-4cf4-538e-a823-6bf5e0b2ceba', 2, 2, 'ዕጣቸውም እነዚህ ነበሩ፤ ቤርሳቤህ፥ ሰማህ፥ ቆሎዶን፤'),
  ('83fea8db-fdd9-5a4f-a6ce-01e0693a10fa', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '7f756774-4cf4-538e-a823-6bf5e0b2ceba', 3, 3, 'አርሳላ፥ ባላ፥ ኢያሶንም፤'),
  ('80f72f69-1065-54ec-ab94-60387711c0f6', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '7f756774-4cf4-538e-a823-6bf5e0b2ceba', 4, 4, 'ኤርቱላ፥ ቡላ፥ ሔርማም፤'),
  ('bec4a865-4045-5fbb-a287-a81df045c2fe', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '7f756774-4cf4-538e-a823-6bf5e0b2ceba', 5, 5, 'ሴቄላቅ፥ ቤተማኮሬብ፥ ሰርሱሲን፤'),
  ('4879ab73-f011-554b-a441-c1798104a1f5', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '7f756774-4cf4-538e-a823-6bf5e0b2ceba', 6, 6, 'ቦታሩትና ሜዳዎቻቸው፥ ዐሥራ ሦስት ከተሞችና መንደሮቻቸው፤'),
  ('4f1893ed-5f5e-5731-a1ca-a5e7cbfd8107', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '7f756774-4cf4-538e-a823-6bf5e0b2ceba', 7, 7, 'ሬሞን፥ ቴልካ፥ ኢያቴር፥ አሳንም፥ አራት ከተሞችና መንደሮቻቸው፤'),
  ('1bbcf827-bc59-5654-a1a0-e659db9d6b95', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '7f756774-4cf4-538e-a823-6bf5e0b2ceba', 8, 8, 'እስከ ባሌቅ ድረስ በእነዚህ ከተሞች ዙሪያ ያሉ መንደሮቻቸው ሁሉ ናቸው። ይህም በባሜት ላይ ወደ ደቡብ ያልፋል። የስምዖን ልጆች ነገድ ርስት በየወገኖቻቸው ይህ ነበረ።'),
  ('564062d2-8e71-5acf-a321-c0087a1eac69', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '7f756774-4cf4-538e-a823-6bf5e0b2ceba', 9, 9, 'ከይሁዳ ልጆች ክፍል የስምዖን ልጆች ርስት ሆነ፤ የይሁዳም ልጆች ዕድል ፋንታ ስለ በዛባቸው የስምዖን ልጆች በርስታቸው መካከል ወረሱ።'),
  ('f3673182-e059-54ac-aa55-2ea4176dcf8a', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'd61efa2b-96e2-53d3-ae12-bbcef952cac5', 1, 10, 'ሦስተኛውም ዕጣ ለዛብሎን ልጆች በየወገኖቻቸው ወጣ፤ የርስታቸውም ድንበር እስከ ኤሴዴቅ ጎላ ነበረ፤'),
  ('715b0624-1b60-54d9-a163-b43aa7173ee8', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'd61efa2b-96e2-53d3-ae12-bbcef952cac5', 2, 11, 'ድንበራቸውም በምዕራብ በኩል ወደ ማራጌላ ይወጣል፤ እስከ ቤተ ራባም ይደርሳል፤ በኢያቃንም ፊት ለፊት ወዳለው ሸለቆም ይደርሳል፤'),
  ('475f3616-a8b8-5857-ab2a-8402342d6b55', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'd61efa2b-96e2-53d3-ae12-bbcef952cac5', 3, 12, 'ከሴዱቅም ወደ ቤተ ሳሚስ ምሥራቅ ወደ ካሲሎቴት ዳርቻ ይዞራል፤ ወደ ዳቤሮትም ይወጣል፤ ወደ ፋንጊም ይደርሳል፤'),
  ('a9c0eae3-ca63-530c-a870-a87988e72eb8', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'd61efa2b-96e2-53d3-ae12-bbcef952cac5', 4, 13, 'ከዚያም ወደ ጌቤሮ ምሥራቅ ወደ ከታሤም ከተማ ያልፋል፤ ወደ ሪናሞን ወደ ማታርዮዛ ይወጣል።'),
  ('0e0caffd-1197-5980-ad04-a1e937acdd1d', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'd61efa2b-96e2-53d3-ae12-bbcef952cac5', 5, 14, 'ድንበሩም በሰሜን በኩል ወደ አሞት ይዞራል፥ መውጫውም በሐናት በኩል በጌፋሄል ሸለቆ ነበረ።'),
  ('6c82a5be-ba14-5724-aca2-d327b4484ba3', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'd61efa2b-96e2-53d3-ae12-bbcef952cac5', 6, 15, 'ቃጠናት፥ ናባሐል፥ ሲምዖን፥ ኢያሪሆ፥ ቤቴሜንም፤ ዐሥራ ሁለት ከተሞችና መንደሮቻቸው።'),
  ('766c7f14-1c68-5221-a5e5-78000e0395e1', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'd61efa2b-96e2-53d3-ae12-bbcef952cac5', 7, 16, 'የዛብሎን ልጆች ነገድ ርስት በየወገኖቻቸው እነዚህ ከተሞችና መንደሮቻቸው ናቸው።'),
  ('3d77ff7e-da40-57d3-a4a9-4b5932615b7b', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6001e905-91f3-5089-af5f-271b192c4d00', 1, 17, 'አራተኛውም ዕጣ ለይሳኮር ልጆች ወጣ።'),
