  ('f385e8f3-ef5e-5153-abe2-95220cec573e', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6001e905-91f3-5089-af5f-271b192c4d00', 3, 19, 'አጊን፥ ሴዎንና፥ ርሄቱ፥'),
  ('9a4e42bf-5368-5d97-aeef-24bd733dfc27', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6001e905-91f3-5089-af5f-271b192c4d00', 4, 20, 'አንከሬት፥ ዳቤሮት፥ ቂሶን፥ ሮቤስ፤'),
  ('b23a6b66-bcc1-57ae-a1d0-fa4723ce1e9a', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6001e905-91f3-5089-af5f-271b192c4d00', 5, 21, 'ሬማስ፥ ያዖን፥ ቶማን፥ ኤሜሬቅ፥ ቤርሳፌስ ነበረ።'),
  ('9b29023a-973f-51f4-a30f-921d3c2fcd26', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6001e905-91f3-5089-af5f-271b192c4d00', 6, 22, 'ድንበራቸውም ወደ ታቦርና ወደ ሰሌም፥ በምዕራብ በኩል ወደ ቤተሳሚስ ይደርሳል፤ የድንበራቸው መውጫም ዮርዳኖስ ነበረ፤ ዐሥራ ስድስት ከተሞችና መንደሮቻቸውም።'),
  ('da5348f2-3a4b-5625-ab33-bf0dc942ccdf', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6001e905-91f3-5089-af5f-271b192c4d00', 7, 23, 'የይሳኮር ልጆች ነገድ ርስት በየወገኖቻቸው እነዚህ ከተሞችና መንደሮቻቸው ናቸው።'),
  ('dbb70f08-493a-5cac-a077-6b46244ec8b2', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '66374023-c4b1-5bb8-a847-a7158fad9070', 1, 24, 'አምስተኛው ዕጣ ለአሴር ልጆች ነገድ በየወገኖቻቸው ወጣ።'),
  ('7f6fb80e-d9ac-527e-a8cb-39ff83f670dc', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '66374023-c4b1-5bb8-a847-a7158fad9070', 2, 25, 'ድንበራቸውም ኤልኬት፥ ኤሌፍ፥ ቤቶቅ፥ ቂያፍ፤'),
  ('02f8d5ef-c1c2-5ec6-ac76-b745c266775f', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '66374023-c4b1-5bb8-a847-a7158fad9070', 3, 26, 'አሊሜሌክ፥ አሜሕል፥ ማሕሳ ነበር፤ በባሕርም በኩል ወደ ቀርሜሎስ፥ ወደ ሴዎንና ሊበናት ይደርሳል፤'),
  ('1eb51dac-56ec-51dd-a017-1007f0a74554', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '66374023-c4b1-5bb8-a847-a7158fad9070', 4, 27, 'ወደ ፀሐይ መውጫ ወደ ቤቴጌነት ይዞራል፤ በመስዕም በኩል ከዛብሎንና ከጋይ ከይፍታሕኤል ይያያዛል ወደ ሳፍቱ ቤታሜሕና ወደ ኢንሂል ይደርሳል፤ ወደ ኮባ ማሾሜልም ያልፋል፤'),
  ('c4a80962-f864-57a0-a730-039750335541', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '66374023-c4b1-5bb8-a847-a7158fad9070', 5, 28, 'ከዚያም ወደ ኤብሮን፥ ወደ ረዓብ፥ ወደ አሜማህን፥ ወደ ቀንታን እስከ ታላቁ ሲዶና ይደርሳል።'),
  ('6d821e74-336f-5e71-ac2a-5bbed9888d2a', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '66374023-c4b1-5bb8-a847-a7158fad9070', 6, 29, 'ድንበሩም ወደ ራማ፥ ወደ መስፋጥ ምንጭ ወደ ጢሮስ ይዞራል፤ ድንበሩም ወደ ኢያሴፍ ይዞራል፤ መውጫውም በሌብና በኮዛብ በኩል ወደ ባሕሩ ነበረ፤'),
  ('0d422af9-b154-5507-a77d-666aafac7d8b', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '66374023-c4b1-5bb8-a847-a7158fad9070', 7, 30, 'አርኮብ፥ አፌቅ፥ ረአውም ደግሞ ነበሩ፤ ሃያ ሁለት ከተሞችና መንደሮቻቸውም።'),
  ('d47ebdab-dc65-5423-a781-ad7947cf62ee', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '66374023-c4b1-5bb8-a847-a7158fad9070', 8, 31, 'የአሴር ልጆች ነገድ ርስት በየወገኖቻቸው እነዚህ ከተሞችና መንደሮቻቸው ናቸው።'),
  ('53de86a6-5266-510c-a97e-46088b1876e8', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6573b074-76e2-50f2-a3e0-89bc2be92009', 1, 32, 'ስድስተኛውም ዕጣ ለንፍታሌም ልጆች ነገድ በየወገኖቻቸው ወጣ።'),
  ('5b05302a-8661-585c-a5e7-e2dda3d15811', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6573b074-76e2-50f2-a3e0-89bc2be92009', 2, 33, 'ድንበራቸውም ከመሐላም፥ ከሞላም፥ ከቤሴሜይን፥ ከአርሜ፥ ከናቦቅና፥ ከኢያፍታሜን እስከ ይዳም ድረስ ነበረ፤ መውጫውም በዮርዳኖስ ነበረ።'),
  ('44b860ac-d854-53bf-a02b-34df83d7d5c3', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6573b074-76e2-50f2-a3e0-89bc2be92009', 3, 34, 'ድንበሩም ወደ ምዕራብ ወደ አዝኖትታቦር ይዞራል፤ ከዚያም ወደ ያቃና ይወጣል፤ ከዚያም በደቡብ በኩል ወደ ዛብሎን፤ በምዕራብ በኩል ወደ አሴር፥ በዮርዳኖስም በፀሐይ መውጫ ወደ ይሁዳ ይደርሳል።'),
  ('222a9ea4-b823-568b-ae96-aacfdc6f27fe', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6573b074-76e2-50f2-a3e0-89bc2be92009', 4, 35, 'የተመሸጉትም የሲዶና ከተሞች እነዚህ ነበሩ፤ ጤሮስ፥ አማታዳቄት፥ ቄሬት፥'),
  ('3a3ff49f-a4f6-5ce8-af0b-410015cc2b98', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6573b074-76e2-50f2-a3e0-89bc2be92009', 5, 36, 'አርሜት፥ አራሂን፥ አሦር፥'),
  ('e9bcdb77-2e5e-51bc-a65b-e7aa32a12b6a', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6573b074-76e2-50f2-a3e0-89bc2be92009', 6, 37, 'ቃዴስ፥ አስራይስ፥ የአሦር ምንጭ፥'),
  ('8f80154f-de4c-5ade-aba1-35a2e144d479', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6573b074-76e2-50f2-a3e0-89bc2be92009', 7, 38, 'ቄሮህ፥ ሚጋላህሪም፥ ቤታሚና፥ ቴስሚስ፤ ዐሥራ ዘጠኝ መንደሮችና ከተሞቻቸው።'),
  ('a0e302f1-e9ae-568e-a0a0-c34faca00d23', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '6573b074-76e2-50f2-a3e0-89bc2be92009', 8, 39, 'የንፍታሌም ልጆች ነገድ ርስት እነዚህ ከተሞችና መንደሮቻቸው ናቸው።'),
  ('c4c42cdf-89e4-5871-a558-52eb375a2d60', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'c26f901f-8988-547b-ab0d-b67c220c6f0d', 1, 40, 'ሰባተኛውም ዕጣ ለዳን ልጆች ወጣ።'),
  ('4b2d84ed-49c2-5200-a217-c53ea8a37aee', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'c26f901f-8988-547b-ab0d-b67c220c6f0d', 2, 41, 'የርስታቸውም ዳርቻ ይህ ነበረ፤ ሠራሕት፥ አሳ፥ የሰመውስ ከተማ፥'),
  ('e436383f-45d9-5151-a49b-45891dfc12ee', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'c26f901f-8988-547b-ab0d-b67c220c6f0d', 3, 42, 'ሰሊባን፥ አሞን፥ ሴላታ፥'),
  ('488b12f9-82fd-5002-af9d-61f6f8b0bbbd', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'c26f901f-8988-547b-ab0d-b67c220c6f0d', 4, 43, 'ኤሎን፥ ቴምናታ፥ አቃሮን፥'),
  ('cbcc4ba6-8cbf-5055-a910-d544bc62092d', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'c26f901f-8988-547b-ab0d-b67c220c6f0d', 5, 44, 'አልቃታ፥ ቤጌቶን፥ ጌቤላን፥'),
  ('a6fdf6ee-a36f-5978-ac7b-18a5ad32e626', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'c26f901f-8988-547b-ab0d-b67c220c6f0d', 6, 45, 'አዞር፥ ቤኔቤቃት፥ ጌትሬሞን፤'),
  ('c0cc3cd9-b571-56bf-a873-c3d0696e4398', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'c26f901f-8988-547b-ab0d-b67c220c6f0d', 7, 46, 'በባሕር በኩል በኢዮጴ ፊት ለፊት ካለው ዳርቻ ጋር ኢያራቆን።'),
  ('cb0c07db-e44b-5917-a272-2c307a994960', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'c26f901f-8988-547b-ab0d-b67c220c6f0d', 8, 47, 'የዳን ልጆች ነገድ ርስት በየወገኖቻቸው እነዚህ ከተሞችና መንደሮቻቸው ናቸው። የዳን ልጆችም በተራራው ላይ የሚያስጨንቋቸው አሞሬዎናውያንን አላስጨነቁአቸውም። አሞሬዎናውያንም ወደ ሸለቆዎች ይወርዱ ዘንድ አልፈቀዱላቸውም። ከእነርሱም ከርስታቸው ዳርቻ አንድ ክፍልን ወሰዱ።'),
  ('aadc9915-a23a-50cf-a642-04c769afb992', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', 'c26f901f-8988-547b-ab0d-b67c220c6f0d', 9, 48, 'የዳን ልጆችም ሄደው ለኪስን መቱአት፤ ከተማቸውንም ያዟት፤ በሰይፍም መቱአት። በውስጥዋም ተቀመጡ። ስሟንም በአባታቸው በዳን ስም ዳን ብለው ጠሩአት። አሞሬዎናውያንም በኤዶምና በሰላሚን ለመኖር ቀጠሉ። የኤፍሬማውያንም እጅ በእነርሱ ላይ በረታች። ገባሪዎችም ሆኑላቸው።'),
  ('ba0a513a-c446-59f2-abf3-2c5787337a68', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '4e40c36d-f570-5f16-a48e-5811b3a9cc52', 1, 49, 'ምድሩንም ሁሉ በየድንበሩ ርስት እንዲሆን ከፍለው ከጨረሱ በኋላ፥ የእስራኤል ልጆች ለነዌ ልጅ ለኢያሱ በእግዚአብሔር ትእዛዝ በመካከላቸው ርስት ሰጡት።'),
  ('ea5f34e5-f8f6-5d3b-a18b-3c74ffae72cd', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '4e40c36d-f570-5f16-a48e-5811b3a9cc52', 2, 50, 'በኤፍሬም ተራራማ ሀገር ያለችውን ተምናሴራ የምትባለውን የፈለጋትን ከተማ ሰጡት፤ ከተማም ሠርቶ ተቀመጠባት።'),
  ('4f0a66e2-895a-5cba-a57f-79974211358c', 'a5a78b99-78bd-57e0-a002-4ff17d3aec63', '4e40c36d-f570-5f16-a48e-5811b3a9cc52', 3, 51, 'ካህኑ አልዓዛር፥ የነዌም ልጅ ኢያሱ፥ የእስራኤልም ልጆች ነገዶች የአባቶች አለቆች በእግዚአብሔር ፊት በሴሎ በምስክሩ ድንኳን ደጃፍ አጠገብ በዕጣ የተካፈሉት ርስት ይህ ነው። ምድሪቱንም መካፈል ፈጸሙ።'),
  ('6c872f91-1570-5f5a-a68a-0da4bbf620e2', 'ab802b95-4f2c-5a63-a1ed-cd16416aa8c3', '3f5f6587-3d06-5766-ac30-5e4372f372ad', 1, 1, 'እግዚአብሔርም ኢያሱን እንዲህ ብሎ ተናገረው፦'),
  ('c2a85227-0f33-5440-a49b-3e0594bce719', 'ab802b95-4f2c-5a63-a1ed-cd16416aa8c3', '3f5f6587-3d06-5766-ac30-5e4372f372ad', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብለህ ተናገራቸው፦ በሙሴ ቃል የነገርኋችሁን የመማፀኛ ከተሞችን ስጡ።'),
  ('8cf71c1d-fc56-5305-ad44-1cb3b4d9b07d', 'ab802b95-4f2c-5a63-a1ed-cd16416aa8c3', '3f5f6587-3d06-5766-ac30-5e4372f372ad', 3, 3, 'ባለማወቅ ሳይወድድ ሰውን የገደለ በዚያ ይማፀን ዘንድ፥ ለእናንተ የመማፀኛ ከተሞችን ሥሩ፤ ነፍስ የገደለ ሰውም በአደባባይ ለፍርድ እስኪቀርብ ድረስ በደም ተበቃዩ አይገደል።'),
  ('5b08b7e1-73e1-5e41-a4cf-e4528906de66', 'ab802b95-4f2c-5a63-a1ed-cd16416aa8c3', '3f5f6587-3d06-5766-ac30-5e4372f372ad', 4, 4, 'ከእነዚህም ከተሞች በአንዲቱ ይማፀናል፤ በከተማዪቱም በር አደባባይ ቆሞ ለከተማዪቱ ሽማግሌዎች ነገሩን ይናገራል፤ እነርሱም ወደ ከተማዪቱ ያገቡታል። የሚቀመጥበትም ስፍራ ይሰጡታል።'),
  ('fd37ea47-13c3-5d3d-ab60-986b82bb22ad', 'ab802b95-4f2c-5a63-a1ed-cd16416aa8c3', '3f5f6587-3d06-5766-ac30-5e4372f372ad', 5, 5, 'ባለ ደሙ ቢያሳድደው፥ አስቀድሞ ሳይጠላው ባልንጀራውን በስሕተት ስለ ገደለው ነፍሰ ገዳዩን በእጁ አሳልፈው አይስጡት።'),
  ('95f5a467-6215-5028-ae9b-b82f860be47f', 'ab802b95-4f2c-5a63-a1ed-cd16416aa8c3', '3f5f6587-3d06-5766-ac30-5e4372f372ad', 6, 6, 'በማኅበሩ ፊት ለፍርድ እስኪቆም ድረስ ፥ በዚያም ወራት ያለው ታላቁ ካህን እስኪሞት ድረስ በዚያች ከተማ ይቀመጥ፤ ከዚያም ወዲያ ነፍሰ ገዳዩ ይመለሳል፤ ወደ ከተማውም፥ ወደ ቤቱም ሸሽቶ ወደ ወጣበትም ከተማ ይገባል።”'),
  ('19a8c80f-fe37-535f-af96-a73c74e10f1e', 'ab802b95-4f2c-5a63-a1ed-cd16416aa8c3', '3f5f6587-3d06-5766-ac30-5e4372f372ad', 7, 7, 'በንፍታሌም ባለው በተራራማው ሀገር በገሊላ ቃዴስን፥ በኤፍሬምም ባለው በተራራማው ሀገር ሴኬምን፥ በይሁዳም ባለው በተራራማው ሀገር ኬብሮን የምትባለውን የአርቦቅን ከተማ ለዩ።'),
  ('7a6bb91e-30b1-5369-a6bf-7cf4bbd5228c', 'ab802b95-4f2c-5a63-a1ed-cd16416aa8c3', '3f5f6587-3d06-5766-ac30-5e4372f372ad', 8, 8, 'በዮርዳኖስም ማዶ ከኢያሪኮ ወደ ምሥራቅ ከሮቤል ነገድ በምድረ በዳው በደልዳላው ስፍራ ቦሶርን፥ ከጋድም ነገድ በገለዓድ ኤርሞትን፥ ከምናሴም ነገድ በባሳን ጎላንን ለዩ።'),
  ('a7d8c721-3418-58e2-ad16-84c7d5461375', 'ab802b95-4f2c-5a63-a1ed-cd16416aa8c3', '3f5f6587-3d06-5766-ac30-5e4372f372ad', 9, 9, 'በማኅበሩ ፊት እስኪቆምና እስኪመረመር ድረስ ባለደሙ እንዳይገድለው ሳያውቅ ሰውን የገደለ ወደዚያ እንዲማፀን፥ ለእስራኤል ልጆች ሁሉ፥ በመካካላቸውም ለሚቀመጥ መጻተኛ የተመረጡ ከተሞች እነዚህ ናቸው።'),
  ('f7064e40-1de1-5b3a-a400-53ead7d15035', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 1, 1, 'የሌዊ ልጆች አለቆች ወደ ካህኑ ወደ አልዓዛር፥ ወደ ነዌም ልጅ ወደ ኢያሱ ወደ እስራኤልም ሕዝብ አባቶች ነገዶች አለቆች መጡ፤'),
  ('b6549af1-9fa3-5104-a6d0-bede82cb31ca', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 2, 2, 'በከነዓን ምድር ባለችው በሴሎ፥ “እግዚአብሔር በሙሴ እጅ የምንቀመጥባቸውን ከተሞች፥ ለከብቶቻችንም መሰማሪያዎች ትሰጡን ዘንድ አዝዞአል” ብለው ተናገሩአቸው።'),
  ('32b4bf0b-91ff-5937-a94d-617ab1403490', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 3, 3, 'የእስራኤልም ልጆች እንደ እግዚአብሔር ትእዛዝ ከርስታቸው እነዚህን ከተሞችና መሰማርያቸውን ለሌዋውያን ሰጡአቸው።'),
  ('6af70400-2e66-5f48-a2e7-14bf80989a17', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 4, 4, 'ለቀዓትም ወገኖች ልጆች ዕጣ ወጣ፤ ሌዋውያንም ለነበሩ ለካህኑ ለአሮን ልጆች ከይሁዳ ነገድ፥ ከስምዖንም ነገድ፥ ከብንያምም ነገድ ዐሥራ ሦስት ከተሞች በዕጣ ተሰጡአቸው።'),
  ('a3465db6-d72a-526a-a7ec-4a9f869c89bf', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 5, 5, 'ለቀሩትም ለቀዓት ልጆች ከኤፍሬም ነገድ፥ ከዳንም ነገድ፥ ከምናሴም ነገድ እኩሌታ ዐሥር ከተሞች በዕጣ ተሰጡአቸው።'),
  ('839087ec-5b05-551c-a4b9-ef7f8850944c', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 6, 6, 'ለጌድሶንም ልጆች ከይሳኮር ነገድ፥ ከአሴርም ነገድ፥ ከንፍታሌምም ነገድ፥ በባሳንም ካለው ከምናሴ ነገድ እኩሌታ ዐሥራ ሦስት ከተሞች በዕጣ ተሰጡአቸው።'),
  ('bdaaa0a8-2167-53e9-a2c3-27a0198d6f7b', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 7, 7, 'ለሜራሪም ልጆች በየወገኖቻቸው ከሮቤል ነገድ፥ ከጋድም ነገድ፥ ከዛብሎንም ነገድ ዐሥራ ሁለት ከተሞች ተሰጡአቸው።'),
  ('79c624b8-6d4b-512c-a956-a6abd81b7fb2', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 8, 8, 'እግዚአብሔርም ሙሴን እንዳዘዘው የእስራኤል ልጆች እነዚህን ከተሞችና መሰማሪያቸውን ለሌዋውያን በዕጣ ሰጡ።'),
  ('ec9e2954-617a-548f-a298-33b22fc2b811', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 9, 9, 'የይሁዳም ልጆች ነገድ፥ የስምዖንም ልጆች ነገድ፥ የብንያምም ልጆች ነገድ በስማቸው የተጠሩትን እነዚህን ከተሞች ሰጡአቸው።'),
  ('d0a1b209-88f5-577d-a992-7ee573684755', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 10, 10, 'የፊተኛው ዕጣ ለእነርሱ ስለወጣ የሌዊ ልጆች የቀዓት ወገን ለሆኑ ለአሮን ልጆች ሆኑ።'),
  ('98ca5395-a956-539b-ab1a-f4d263c5fe8e', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 11, 11, 'የኤናቅ ልጆች ከተማ ቅርያትያርቦቅንና በዙሪያዋ ያሉ መሰማሪያዎችን ሰጡአቸው፤ ይህችውም በይሁዳ ተራራ ያለች ኬብሮን ናት።'),
  ('b45a7dc4-076a-5c0d-a514-c84c5192e0ed', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 12, 12, 'ኢያሱም የከተማዪቱን እርሻ መንደሮችዋንም ለዮፎኒ ልጅ ለካሌብ ልጆች ርስት አድርጎ ሰጣቸው።'),
  ('ec161769-2b1d-50e0-ace8-808e58fdb55d', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 13, 13, 'ለካህኑም ለአሮን ልጆች እነዚህን ሰጡ፤ ለነፍሰ ገዳይ መማፀኛ ከተማ የሆነችውን ኬብሮንንና መሰማርያዋን፤ ሌምናንና መሰማርያዋን፥'),
  ('8af1cb71-1020-5f7a-a602-c75578511ddd', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 14, 14, 'ኤቴርንና መሰማርያዋን፥ ኤታምንንና መሰማርያዋን፤'),
  ('a52dbe16-60f7-522d-adae-8d10720c8951', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 15, 15, 'ሄሎንንና መሰማርያዋን፥ ዳቤርንና መሰማርያዋን፥'),
  ('25379d0f-0738-553e-a18a-697eb902f34e', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 16, 16, 'አሳንና መሰማርያዋን፥ ዮጣንንና መሰማርያዋን፥ ቤትሳሚስንና መሰማርያዋን፤ ከእነዚህ ከሁለቱ ነገዶች ዘጠኝ ከተሞችን ሰጡ።'),
  ('c8a9141e-fd41-50a7-a706-a6f05323abd0', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 17, 17, 'ከብንያምም ነገድ ገባዖንንና መሰማርያዋን፥ ጋቲትንና መሰማርያዋን፤'),
  ('4e4e37c5-f14e-5fee-ac6b-92a8881c1e41', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 18, 18, 'ዓናቶትንና መሰማርያዋን፥ አልሞንንና መሰማርያዋን፤ አራት ከተሞችን ሰጡ።'),
  ('b067b34d-162f-50db-a485-bafeef5e1393', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 19, 19, 'የካህናቱ የአሮን ልጆች ከተሞች ከመሰማሪያዎቻቸው ጋር ዐሥራ ሦስት ናቸው፤'),
  ('e650765c-f339-587b-af6b-5dc6de48f95f', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 20, 20, 'ለቀሩትም ለሌዋውያኑ ለቀዓት ልጆች የዕጣቸው ከተሞች ከኤፍሬም ነገድ ደረሱአቸው።'),
  ('d83c3dc6-d024-5a6e-a9a4-4cd2ced58413', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 21, 21, 'ለነፍሰ ገዳይ መማፀኛ ከተማ የሆነችውን ሴኬምንና መሰማርያዋን፥ ጌዜርንና መሰማርያዋን፤'),
  ('e53fbac8-0df7-58bb-a740-f17807f12276', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 22, 22, 'ቄብጻይምንና መሰማርያዋን፥ ቤቶሮንና መሰማርያዋን፤ አራቱን ከተሞች ሰጡአቸው።'),
  ('dc542ede-e992-52fd-a1fa-b201a07294b6', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 23, 23, 'ከዳንም ነገድ ኤልቆታይምንና መሰማርያዋን፥ ገባቶንንና መሰማርያዋን፤'),
  ('16749968-ccce-507a-a16d-b48bb30a11e6', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 24, 24, 'ኤሎንንና መሰማርያዋን፥ ጌቴራሞንንና መሰማርያዋን፤ አራቱን ከተሞች ሰጡአቸው።'),
  ('a5cf54f4-6b5b-56e2-afb6-b64a86bd3337', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 25, 25, 'ከምናሴም ነገድ እኩሌታ ጠናሕንና መሰማርያዋን፥ ዬባታንና መሰማርያዋን፤ ሁለቱን ከተሞች ሰጡአቸው።'),
  ('42b5230c-1562-5fd7-a7c2-163042274ea1', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 26, 26, 'የቀሩት የቀዓት ልጆች ወገኖች ከተሞች ሁሉ ከመሰማርያቸው ጋር ዐሥር ናቸው።'),
  ('c4077b5d-0c66-58f5-a18d-11fff508ff39', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 27, 27, 'ለሌዋውያንም ወገኖች ለጌድሶን ልጆች ከምናሴ ነገድ እኩሌታ ለነፍሰ ገዳይ መማፀኛ ከተማ በባሳን ውስጥ የሆነችውን ጎላንንና መሰማርያዋን፥ ቦሶርንና መሰማርያዋን፤ ሁለቱን ከተሞች ሰጡአቸው።'),
  ('7879f6c3-d2e5-5f43-a570-11dd73870ffd', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 28, 28, 'ከይሳኮርም ነገድ ቂሶንንና መሰማርያዋን፥ ዳብራትንና መሰማርያዋን፤'),
  ('c892f61a-4481-5945-a922-06c7fbbcd0ba', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 29, 29, 'ሬማትንና መሰማርያዋን፥ ዓይንጋኒምንና መሰማርያዋን፤ አራቱን ከተሞች ሰጡአቸው።'),
  ('07195adc-6af9-5a54-ae98-ecead6d91381', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 30, 30, 'ከአሴርም ነገድ መሴላንና መሰማርያዋን፥ አቤዶንንና መሰማርያዋን፥'),
  ('7e01a6f4-6a96-58d2-a704-88f0ff6ea56d', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 31, 31, 'ሔልቃትንንና መሰማርያዋን፥ ረዓብንና መሰማርያዋን፤ አራቱንም ከተሞች ሰጡአቸው።'),
  ('450bb858-3ba5-5a59-a3f3-42234d731648', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 32, 32, 'ከንፍታሌምም ነገድ ለነፍሰ ገዳይ መማፀኛ ከተማ የሆነችውን በገሊላ ውስጥ ቃዴስንና መሰማርያዋን፥ ኤማትንና መሰማርያዋን፥ ቃርቴንንና መሰማሪያዋን፤ ሦስቱን ከተሞች ሰጡአቸው።'),
  ('386897d4-a1fe-5b1a-ad41-414b2d503045', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 33, 33, 'የጌድሶን ልጆች ከተሞች ሁሉ በየወገኖቻቸው ዐሥራ ሦስት ከተሞች ከመሰማርያቸው ጋር ናቸው።'),
  ('eb03e75b-c2ad-5187-aabe-37b1103210e6', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 34, 34, 'ከሌዋውያን ለቀሩት ለሜራሪ ልጆች ወገን ከዛብሎን ነገድ ዮቅናምንና መሰማርያዋን፥ ቃዴስንና መሰማርያዋን፥'),
  ('f17ddd7f-fcf9-57f0-a761-8cce5141f681', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 35, 35, 'ዲምናንና መሰማርያዋን፥ ሴላንና መሰማርያዋን፤ አራቱን ከተሞች ሰጡ።'),
  ('ad1b6b33-ade9-5e34-ad4f-9b595e25e0dc', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 36, 36, 'በዮርዳኖስ ማዶ በኢያሪኮ በኩል ከሮቤል ነገድ ለነፍሰ ገዳይ መማፀኛ በሚሶን ምድረ በዳ ቦሶርንና መሰማርያዋን፥ ኢያዜርንና መሰማርያዋን፤'),
  ('b432e1cd-1dff-53b2-a941-5653d32e4e95', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 37, 37, 'ቄዴሞትንና መሰማርያዋን፥ ሜፍዐትንና መሰማርያዋን፤ አራቱን ከተሞች ሰጡ።'),
  ('b386a20d-5f30-5098-a7c0-e8fcd270d372', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 38, 38, 'ከጋድም ነገድ ለነፍሰ ገዳይ መማፀኛ ከተማ የሆነችውን በገለዓድ ውስጥ ራሞትንና መሰማርያዋን፥ ቃሚንንና መሰማርያዋን፤'),
  ('6c00f591-b17d-5268-a210-19916f6762aa', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 39, 39, 'ሐሴቦንንና መሰማርያዋን፥ ኢያዜርንና መሰማርያዋን፤ አራቱን ከተሞች ሰጡ።'),
  ('80e062f1-8536-5476-ae25-9ba7fcb6a787', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 40, 40, 'ከሌዊ ወገኖች የቀሩት የሜራሪ ልጆች ከተሞች ሁሉ በየወገኖቻቸው እነዚህ ነበሩ፤ ዕጣቸውም ዐሥራ ሁለት ከተማ ነበረ።'),
  ('8432e8a9-22d7-5001-a4a3-2312ff504a52', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 41, 41, 'በእስራኤል ልጆች ርስት መካከል የነበሩት የሌዋውያን ከተሞች ሁሉ በእነዚህ ከተሞች ዙሪያ ካሉ ከመሰማርያዎቻቸው ጋር አርባ ስምንት ከተሞች ነበሩ።'),
  ('a474691a-3f85-593b-a79e-bb9ea9f927fd', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', 'f31d1e7f-849b-51e0-a262-2807d726be4d', 42, 42, 'እነዚህም ከተሞች እያንዳንዳቸው ከመሰማርያቸው ጋር ነበሩ፤ እነዚህም ከተሞች ሁሉ እንዲሁ ነበሩ። [ኢያሱም በየድንበሮቻቸው ምድርን ማካፈልን ጨረሰ። የእስራኤል ልጆችም ለኢያሱ በእግዚአብሔር ትእዛዝ ድርሻውን ሰጡት፤ እርሱ የሚፈልጋትን ከተማ በኤፍሬም ተራራ የምትገኘውን ቴምናሴራን ሰጡት፤ ከተማም ሠራባት፤ በውስጧም ተቀመጠ። ኢያሱም በምደረ በዳ በመንገድ የተወለዱትን የገረዘባቸውን የድንጋይ ባልጩቶች ወስዶ በቴምናሴራ አኖራቸው።]'),
  ('d224113d-e34e-51b2-ad75-92f5c1c53332', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', '13131851-2f69-5494-a50f-d87dde94a087', 1, 43, 'እግዚአብሔርም ይሰጣቸው ዘንድ ለአባቶቻቸው የማለላቸውን ምድር ሁሉ ለእስራኤል ሰጠ፤ ወረሱአትም፥ ተቀመጡባትም።'),
  ('f518c8cc-5d8b-5bb0-a0fb-4a1d703e881f', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', '13131851-2f69-5494-a50f-d87dde94a087', 2, 44, 'እግዚአብሔርም ለአባቶቻቸው እንደ ማለላቸው በዙሪያቸው ካሉት አሳረፋቸው፤ ከጠላቶቻቸውም ሁሉ ይቋቋማቸው ዘንድ ማንም ሰው አልቻለም፤ እግዚአብሔርም ጠላቶቻቸውን ሁሉ በእጃቸው አሳልፎ ሰጣቸው።'),
  ('56444686-8b3a-554c-a8d1-8a5f7a7e9ac4', 'b8605504-c2b8-5ad8-aee3-95c42e6b19af', '13131851-2f69-5494-a50f-d87dde94a087', 3, 45, 'እግዚአብሔር ለእስራኤል ቤት ከተናገረው መልካም ነገር ሁሉ ተፈጸመ እንጂ ምንም አልቀረም።'),
  ('7dcfedd1-b5f1-505f-a549-d1b6e22a2885', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', '6f6e6ba3-a023-51de-ada9-1ee020ad21ce', 1, 1, 'በዚያን ጊዜም ኢያሱ የሮቤልን ልጆችና የጋድን ልጆች የምናሴንም ነገድ እኩሌታ ጠርቶ እንዲህ አላቸው፦'),
  ('1ce740ae-50db-5b90-acfe-adc7089a8d17', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', '6f6e6ba3-a023-51de-ada9-1ee020ad21ce', 2, 2, '“የእግዚአብሔር አገልጋይ ሙሴ ያዘዛችሁን ሁሉ ሰምታችኋል፤ እኔም ላዘዝኋችሁ ነገር ሁሉ ታዝዛችኋል፤'),
  ('2a58e3f0-46d3-52d6-a29a-51b88645c78a', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', '6f6e6ba3-a023-51de-ada9-1ee020ad21ce', 3, 3, 'ይህንም ያህል ብዙ ጊዜ እስከ ዛሬ ድረስ ወንድሞቻችሁን አልተዋችሁም፤ የአምላካችሁንም የእግዚአብሔርን ትእዛዝ ጠብቃችኋል።'),
  ('92f0665a-efea-52ec-a9e7-8bdc376044f9', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', '6f6e6ba3-a023-51de-ada9-1ee020ad21ce', 4, 4, 'አሁንም አምላካችሁ እግዚአብሔር እንደ ተናገራቸው ወንድሞቻችሁን አሳርፎአቸዋል፤ አሁን እንግዲህ ተመለሱ፤ ወደ ቤታችሁና የእግዚአብሔር አገልጋይ ሙሴ በዮርዳኖስ ማዶ ወደ ሰጣችሁ ወደ ርስታችሁ ምድር ሂዱ።'),
  ('8b77bf76-1832-5c41-a794-168a0e4c1032', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', '6f6e6ba3-a023-51de-ada9-1ee020ad21ce', 5, 5, 'ብቻ የእግዚአብሔር አገልጋይ ሙሴ ያዘዛችሁን ትእዛዙንና ሕጉን ታደርጉ ዘንድ፥ አምላካችሁን እግዚአብሔርንም ትወድዱ ዘንድ፥ መንገዱንም ሁሉ ትሄዱ ዘንድ፥ ትእዛዙንም ትጠብቁ ዘንድ፥ እርሱንም ትከተሉ ዘንድ፥ በፍጹምም ልባችሁ በፍጹምም ነፍሳችሁ ታመልኩት ዘንድ እጅግ ተጠንቀቁ።”'),
  ('5d7b1f83-3149-502b-ab15-aa912fe03867', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', '6f6e6ba3-a023-51de-ada9-1ee020ad21ce', 6, 6, 'ኢያሱም መረቃቸው፤ አሰናበታቸውም፤ ወደ ቤታቸውም ሄዱ።'),
  ('0277057d-a15e-5296-a5dd-238f76ce8106', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', '6f6e6ba3-a023-51de-ada9-1ee020ad21ce', 7, 7, 'ለምናሴም ነገድ እኩሌታ ሙሴ በባሳን ውስጥ ርስት ሰጥቶአቸው ነበር፤ ለቀረው ለእኩሌታው ግን ኢያሱ በዮርዳኖስ ማዶ በባሕር በኩል በወንድሞቻቸው መካከል ርስት ሰጣቸው። ኢያሱም ወደ ቤታቸው በአሰናበታቸው ጊዜ እንዲህ ብሎ መረቃቸው፦'),
  ('77d04e9a-c474-5723-a38a-a525ddcb3573', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', '6f6e6ba3-a023-51de-ada9-1ee020ad21ce', 8, 8, '“በብዙ ብልጥግና፥ በእጅግም ብዙ ከብት፥ በብርም፥ በወርቅም፥ በናስም፥ በብረትም፥ በእጅግም ብዙ ልብስ ወደ ቤታችሁ ተመለሱ፤ የጠላቶቻችሁንም ምርኮ ከወንድሞቻችሁ ጋር ተካፈሉ።”'),
  ('33b5a598-c477-503b-a5eb-a16abbbfe91e', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', '6f6e6ba3-a023-51de-ada9-1ee020ad21ce', 9, 9, 'የሮቤልም ልጆች የጋድም ልጆች የምናሴም ነገድ እኩሌታ ሄዱ፤ በሙሴም እጅ በተሰጠ በእግዚአብሔር ትእዛዝ ወደ ተቀበሉት ወደ ርስታቸው ወደ ገለዓድ ምድር ይገቡ ዘንድ በከነዓን ምድር ካለችው ከሴሎ ከእስራኤል ልጆች ዘንድ ተመለሱ።'),
  ('c0a74f47-eb99-59e8-aaa5-8c3bdb04784a', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 1, 10, 'በከነዓን ምድር ወዳለው ወደ ዮርዳኖስ አቅራቢያም ወደ ገለዓድ በመጡ ጊዜ የሮቤል ልጆችና የጋድ ልጆች፥ የምናሴም ነገድ እኩሌታ በዚያ በዮርዳኖስ አጠገብ የሚታይ ታላቅ መሠዊያ ሠሩ።'),
  ('0e6ff66c-5ebe-5e6b-a220-2bc278e3cb88', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 2, 11, 'የእስራኤልም ልጆች በከነዓን ምድር ዳርቻ በዮርዳኖስ አጠገብ ባለው በገለዓድ፥ የእስራኤል ልጆች ባሉበት ወገን፥ የሮቤል ልጆችና የጋድ ልጆች የምናሴም ነገድ እኩሌታ መሠዊያ እንደ ሠሩ ሰሙ።'),
  ('c1f77de4-1eb2-5004-a672-4d7b61922b41', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 3, 12, 'የእስራኤልም ልጆች ይህን በሰሙ ጊዜ የእስራኤል ልጆች ማኅበር ሁሉ ወጥተው እነርሱን ሊዋጉ በሴሎ ተሰበሰቡ።'),
  ('af6bf4f1-67c2-5431-a2c9-c527059d71ac', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 4, 13, 'የእስራኤልም ልጆች በገለዓድ ምድር ወዳሉት ወደ ሮቤል ልጆችና ወደ ጋድ ልጆች ወደ ምናሴም ነገድ እኩሌታ የካህኑ የአሮንን ልጅ የአልዓዛርን ልጅ ፊንሐስን ላኩ።'),
  ('e673258e-d5f3-5aa6-a7a6-8fc8ee246a72', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 5, 14, 'ዐሥር አለቆችም ከእርሱ ጋር ነበሩ፤ ከእስራኤል ነገድ ሁሉ አንድ አንድ የእየአባቶቻቸው ቤት አለቃ፤ እያንዳንዱም በእስራኤል አእላፋት መካከል የአባቶቻቸው ቤት አለቃ ነበረ።'),
  ('7a2c5727-a975-5b42-a122-6e1be3155255', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 6, 15, 'በገለዓድም ምድር ወዳሉት ወደ ሮቤል ልጆችና ወደ ጋድ ልጆች፥ ወደ ምናሴም ነገድ እኩሌታ ደረሱ፤ እንዲህም ብለው ነገሩአቸው'),
  ('0cef06aa-d499-59d7-a69e-8cfafb3c337c', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 7, 16, 'የእግዚአብሔር ማኅበር ሁሉ የሚለው ይህ ነው፥ “ዛሬ እግዚአብሔርን መከተልን ትተዉ ዘንድ፥ መሠዊያም ትሠሩ ዘንድ፥ እግዚአብሔርንም ዛሬ ትክዱት ዘንድ ይህ በእስራኤል አምላክ ፊት ያደረጋችሁት ኀጢአት ምንድን ነው?'),
  ('5da407fe-1be4-53df-af28-91421abff51d', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 8, 17, 'እኛ እስከ ዛሬ ድረስ ከእርሱ ያልነጻንበት የፌጎር ኀጢአት ጥቂት ነውን? በእግዚአብሔር ማኅበር ላይ መቅሠፍት ወረደ።'),
  ('853f280f-8c72-5992-a2c0-6a86a1294669', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 9, 18, 'እናንተ ዛሬ እግዚአብሔርን መከተልን ትታችኋል፤ ዛሬ በእግዚአብሔር ላይ ብታምፁ ነገ በእስራኤል ማኅበር ሁሉ ላይ መቅሠፍት ይሆናል።'),
  ('7df94fe4-32ff-5821-a1af-a0053d03b551', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 10, 19, 'ነገር ግን የርስታችሁ ምድር ቢያንሳችሁ የእግዚአብሔር ማደሪያ ወደሚቀመጥበት ወደ እግዚአብሔር ርስት ምድር አልፋችሁ ከእኛ ጋር ውረሱ፤ ከአምላካችንም ከእግዚአብሔር መሠዊያ ውጭ ለእናንተ መሠዊያ ሠርታችኋልና እግዚአብሔርን አትካዱ፤ እግዚአብሔርንም አትተዉት።'),
  ('597661ea-2e87-5f74-aaf1-ef8e9a5d100b', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 11, 20, 'የዛራ ልጅ አካን እርም ነገር በመውሰድ ኀጢአትን ስለ ሠራ በእስራኤል ማኅበር ሁሉ ላይ ቍጣ አልወረደምን? እርሱም ብቻውን ቢበድል በኀጢአቱ ብቻውን ሞተን?”'),
  ('3319b73d-a9fc-520f-a64e-9d687cd8e5b6', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 12, 21, 'የሮቤል ልጆችና የጋድ ልጆች፥ የምናሴም ነገድ እኩሌታ ለእስራኤል አእላፋት አለቆች እንዲህ ብለው መለሱላቸው፦'),
  ('c1bc71e2-5f14-58f9-a66b-3eaeb92e457b', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 13, 22, '“እግዚአብሔር አምላክ ነው፤ ጌታም ነው፤ እግዚአብሔር የአማልክት አምላክ ነው፤ እርሱ ያውቃል። እስራኤልም ያውቀዋል። በእግዚአብሔር ፊት ያደረግነው ለበደልና ለመካድ ከሆነ ዛሬ አያድነን፤'),
  ('b4d0ead3-e43a-5455-a52a-279840ea4633', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 14, 23, 'አምላካችንን እግዚአብሔርን እንድንክደው፥ የሚቃጠለውን መሥዋዕትና የእህልን ቍርባን እንድናሳርግበት፥ የደኅንነትንም መሥዋዕት እንድናቀርብበት መሠዊያ ሠርተን እንደ ሆነ እግዚአብሔር እርሱ ራሱ ይመራመረን፤'),
  ('2dc9e894-84ef-5eb6-a8ae-bd4d6a2ea43b', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 15, 24, 'ይልቁንም ከልባችን ፍርሀት የተነሣ፦ ነገ ልጆቻችሁ ልጆቻችንን፦ ከእስራኤል ልጆች አምላክ ከእግዚአብሔር ጋር ምን አላችሁ? እንዳይሉአቸው ስለፈራን ይህን የሠራነው ካልሆነ፥ እናንተ የሮቤልና የጋድ ልጆች፥ የምናሴም ነገድ እኩሌታ፥'),
  ('4f0779e6-983e-542e-a627-eaae5704efec', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 16, 25, 'እግዚአብሔር በእኛና በእናንተ መካከል ዮርዳኖስን ድንበር አድርጎአልና በእግዚአብሔር ዘንድ ዕድል ፋንታ የላችሁም ይሉአቸዋል፤ በዚሁም ልጆቻችሁ ልጆቻችንን እግዚአብሔርን ከማምለክ እንዳያወጡአቸው ብለን ይህን አደረግን።'),
  ('6b45cff6-7c38-5161-a66d-da6871552d2d', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 17, 26, 'ስለዚህም መሠዊያ እንሥራ አልን፤ ነገር ግን ለሚቃጠል መሥዋዕት ወይም ለቍርባን አይደለም፤'),
  ('df61c0f5-4347-5e5e-a0b0-ef48ca0c3187', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 18, 27, 'ነገር ግን በእኛና በእናንተ መካከል፥ ከእኛም በኋላ በትውልዳችንና በትውልዳችሁ መካከል በሚቃጠል መሥዋዕትና በቍርባን፥ በደኅንነትም መሥዋዕታችን እግዚአብሔርን እናመልክ ዘንድ፥ ነገ ልጆቻችሁ ልጆቻችንን፦ በእግዚአብሔር ዘንድ ዕድል ፋንታ የላችሁም እንዳይሉ ምስክር ይሆናል።'),
  ('141cabb9-7cf3-50b2-a696-f3bcfda99ce6', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 19, 28, 'ኋላ ይህ በተደረገ ጊዜ ነገ ለእኛ ወይም ለትውልዳችን ይህን ሲሉ፥ እኛ፦ እነሆ፥ አባቶቻችን ያደረጉትን የእግዚአብሔርን መሠዊያ ምሳሌ እዩ፤ በእኛና በእናንተ መካከል ምስክር ነው እንጂ ስለሚቃጠል መሥዋዕትና ስለ ቍርባን አይደለም እንላለን።'),
  ('e6633466-ffa8-5675-a976-15b3f3d3e01d', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 20, 29, 'በድንኳኑ ፊት ካለው ከአምላካችን ከእግዚአብሔር መሠዊያ ሌላ ለሚቃጠል መሥዋዕትና ለሰላም መሥዋዕት፥ ለደኅንነት መሥዋዕትም የሚሆን መሠዊያን የሠራነው በእግዚአብሔር ላይ በማመፅ እግዚአብሔርንም ዛሬ መከተልን ለመተው በማለት እንደ ሆነ ይህ ከእኛ ይራቅ።”'),
  ('1a26b742-5939-556d-a132-dea2d0f5cdb2', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 21, 30, 'ካህኑ ፊንሐስና የማኅበሩ አለቆች፥ ከእርሱም ጋር የነበሩት የእስራኤል መሳፍንት ሁሉ ፥ የሮቤል ልጆችና የጋድ ልጆች፥ የምናሴም ነገድ እኩሌታ የተናገሩትን ቃል በሰሙ ጊዜ ዝም አሉ፤ ደስም አሰኛቸው።'),
  ('29f46cf3-bc8a-5c80-a666-d57dd2520bc1', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 22, 31, 'የካህኑም የአልዓዛር ልጅ ፊንሐስ ለሮቤል ልጆችና ለጋድ ልጆች ለምናሴም ነገድ እኩሌታ፥ “ይህን መተላለፍ በእግዚአብሔር ላይ አላደረጋችሁምና እግዚአብሔር በመካከላችን እንዳለ ዛሬ እናውቃለን፤ አሁን የእስራኤልን ልጆች ከእግዚአብሔር እጅ አድናችኋል” አላቸው።'),
  ('16f451e6-4eb2-5861-aa6c-ba584c4f942f', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 23, 32, 'የካህኑም የአልዓዛር ልጅ ፊንሐስ ከእርሱም ጋር የማኅበሩ አለቆች ከሮቤል ልጆችና ከጋድ ልጆች፥ ከምናሴም ነገድ እኩሌታ ዘንድ ከገለዓድ ሀገር ወደ ከነዓን ሀገር ወደ እስራኤል ልጆች ተመለሱ፤ ወሬም አመጡላቸው።'),
  ('6215e754-fc8e-5130-a407-2fc0399244b6', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 24, 33, 'ነገሩም የእስራኤልን ልጆች ደስ አሰኘ፤ ለእስራኤልም ልጆች በነገሩአቸው ጊዜ የእስራኤልን ልጆች አምላክ እግዚአብሔርን አመሰገኑ፤ ከዚያም ወዲያ የሮቤል ልጆችና የጋድ ልጆች፥ የምናሴም ነገድ እኩሌታ የተቀመጡባትን ምድር ያጠፉ ዘንድ ለመውጋት አንወጣም ተባባሉ።'),
  ('bb3b5b2a-ec7d-5951-ab5a-fa2fe8fca7fa', '5f4c9b52-b182-5052-a70a-cb52e10ed2a8', 'fe79f86f-1daf-52a4-a749-bb2a18473b41', 25, 34, 'ኢያሱም መሠዊያውን “የሮቤል ልጆችና የጋድ ልጆች፥ የምናሴም ነገድ እኩሌታ ምስክር” ብሎ ጠራው። እግዚአብሔር አምላካቸው እንደ ሆነ ይህ በመካከላቸው ምስክር ነውና።'),
  ('e761d9b2-3008-5882-a6e1-5b154268d41f', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 1, 1, 'እንዲህም ሆነ፤ ከብዙ ዘመን በኋላ፥ እግዚአብሔርም እስራኤልን በዙሪያቸው ካሉት ጠላቶቻቸው ሁሉ ካሳረፈ በኋላ፥ ኢያሱ ሸመገለ፤ ዘመኑም ዐለፈ፤'),
  ('6ab1f8db-be06-5883-ab11-960a04f0ede8', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 2, 2, 'ኢያሱ የእስራኤልን ልጆች ሁሉ፥ ሽማግሌዎቻቸውንም፥ አለቆቻቸውንም፥ ፈራጆቻቸውንም፥ ሹሞቻቸውንም ጠርቶ እንዲህ አላቸው፥ “እኔ እነሆ ሸምግያለሁ፤ ዘመኔም አልፎአል፤'),
  ('8f366131-52ef-5402-a3f3-d2a8f772a342', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 3, 3, 'እናንተም አምላካችን እግዚአብሔር በፊታችሁ ባሉ በእነዚህ አሕዛብ ሁሉ ስለ እናንተ ያደረገውን ሁሉ አይታችኋል፤ ስለ እናንተ የተዋጋ እርሱ አምላካችን እግዚአብሔር ነው።'),
  ('f84aaa6e-7b4e-545c-a888-823fae34e57c', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 4, 4, 'እነሆ እኔ ካጠፋኋቸው አሕዛብ ሁሉ ጋር ከዮርዳኖስ ጀምሮ በፀሐይ መግቢያ እስካለው እስከ ታላቁ ባሕር ድረስ ለነገዶቻችሁ ርስት እንዲሆኑ የቀሩትን እነዚህን አሕዛብ በዕጣ ከፈልሁላችሁ።'),
  ('36e808ca-7c6c-5595-af28-1ccfe0dc8021', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 5, 5, 'አምላካችሁም እግዚአብሔር እርሱ ከፊታችሁ እስኪደመሰሱ ድረስ ያጠፋላችኋል፤ ከፊታችሁም እነርሱንና ንጉሦቻቸውን እስኪያጠፋቸው ድረስ የዱር አራዊትን ይሰድድባቸዋል፤ አምላካችን እግዚአብሔር እንደ ተናገረ ምድራቸውን ትወርሳላችሁ።'),
  ('eaa4eb56-192b-5575-afbe-e60765cec30e', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 6, 6, 'በሙሴ ሕግ መጽሐፍ የተጻፈውን ሁሉ ትጠብቁና ታደርጉ ዘንድ በጣም በርቱ፥ ከእርሱም ወደ ቀኝም ወደ ግራም ፈቀቅ አትበሉ።'),
  ('e554cddf-0b9f-57fa-aa62-bcedf456ef46', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 7, 7, 'በእናንተም መካከል ወደ ቀሩት ወደ እነዚህ አሕዛብ አትግቡ፤ የአማልክቶቻቸውም ስሞች በእናንተ መካከል አይጠሩ፤ አትማሉባቸውም፤ አታምልኳቸውም፤ አትስገዱላቸውም፤'),
  ('eaef0a48-eff2-57d5-a1c3-1f1e8dc648d3', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 8, 8, 'ነገር ግን እስከ ዛሬ ድረስ እንዳደረጋችሁት አምላካችሁ እግዚአብሔርን ተከተሉ።'),
  ('03bc363e-8e41-53c3-a2af-90ec04cfa0fa', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 9, 9, 'እርሱ እግዚአብሔር ታላላቆችንና ኀይለኞችን አሕዛብ ከፊታችሁ ያጠፋቸዋል፤ እስከ ዛሬም ድረስ የተቋቋማችሁ በፊታችሁ ማንም የለም።'),
  ('dca4eb32-e94a-5ff1-a96d-a7e0e32ed1d4', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 10, 10, 'አምላካችን እግዚአብሔር እንደ ነገረን ስለ እናንተ የሚዋጋ እርሱ ነውና ከእናንተ አንዱ ሰው ሺህ ሰውን ያሳድዳል።'),
  ('30171585-4acf-5309-a0e5-2b4fe3c8f401', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 11, 11, 'አምላካችን እግዚአብሔርን ትወድዱት ዘንድ ለራሳችሁ እጅግ ተጠንቀቁ።'),
  ('2a3c7b15-adfb-583c-abcb-e02ef2fa3a73', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 12, 12, 'እናንተ ግን ተመልሳችሁ በመካከላችሁ ወደ ቀሩት ወደ እነዚህ አሕዛብ ብትጠጉ፥ ከእነርሱም ጋር ብትጋቡ፥ እናንተም ወደ እነርሱ፥ እነርሱም ወደ እናንተ ብትደራረሱ፥'),
  ('ba5939b9-a70c-560e-a692-38ea08a49ae1', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 13, 13, 'አምላካችሁ እግዚአብሔር ከሰጣችሁ ከዚህች ከመልካሚቱ ምድር እስክትጠፉ ድረስ መውደቂያና ወጥመድ፥ በእግራችሁም ችንካር፥ በዐይናችሁም እሾህ ይሆኑባችኋል እንጂ አምላካችሁ እግዚአብሔር ከእንግዲህ ወዲያ እነዚህን አሕዛብ ከፊታችሁ እንዳያጠፋቸው ራሳችሁ ዕወቁ።'),
  ('7f4337a0-8d52-515c-a0cb-e00aac43d45d', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 14, 14, '“እኔም በምድር እንዳሉት ሰዎች ሁሉ ዛሬ ወደ መንገድ እሄዳለሁ፤ እናንተም አምላካችን እግዚአብሔር ስለ እኛ ከተናገረው ከመልካም ነገር ሁሉ አንድ ነገር እንዳልቀረ በልባችሁ ሁሉ፥ በነፍሳችሁም ሁሉ ዕወቁ፤ ሁሉ ደርሶናል፤ ከእርሱም ያላገኘነው የለም።'),
  ('03d71c03-0e9f-5632-abaa-fb13278f3a6b', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 15, 15, 'አምላካችሁ እግዚአብሔር የተናገረው መልካም ነገር ሁሉ እንደ ደረሰላችሁ፥ አምላካችሁ እግዚአብሔር ከሰጣችሁ ከዚህች ከመልካሚቱ ምድር እናንተን እስኪያጠፋችሁ ድረስ እግዚአብሔር እንዲሁ ክፉን ነገር ሁሉ ያመጣባችኋል።'),
  ('427512f0-7321-5220-a08b-aa4c7810d560', '93f6c396-e043-56a2-a256-08fab0f58843', '8f92eab3-83cd-5168-a65d-f0a6acd4c48e', 16, 16, 'አምላካችሁ እግዚአብሔር ያዘዛችሁን ቃል ኪዳን ብታፈርሱ፥ ሄዳችሁም ሌሎችን አማልክት ብታመልኩ፥ ብትሰግዱላቸውም፥ በዚያ ጊዜ የእግዚአብሔር ቍጣ ይነድድባችኋል፥ ከሰጣችሁም ከመልካሚቱ ምድር ፈጥናችሁ ትጠፋላችሁ።”'),
  ('3fcf8a18-33a8-519d-adf1-6d8e56259069', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 1, 1, 'ኢያሱም የእስራኤልን ነገድ ሁሉ ወደ ሴሎ ሰበሰበ፤ የእስራኤልንም ሽማግሌዎች፥ አለቆቻቸውንም፥ ጸሓፊዎቻቸውንም፥ ፈራጆቻቸውንም ጠራቸው። በእግዚአብሔርም ፊት አቆማቸው።'),
  ('de997fed-61ea-5d8a-a79e-2283ea198073', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 2, 2, 'ኢያሱም ለሕዝቡ ሁሉ እንዲህ አለ፥ “የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ‘አባቶቻችሁ፥ የአብርሃምና የናኮር አባት ታራ፥ አስቀድመው በወንዝ ማዶ ተቀመጡ፤ ሌሎችንም አማልክት አመለኩ።'),
  ('77f75189-ff03-52eb-aaad-0970a906ff17', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 3, 3, 'አባታችሁንም አብርሃምን ከወንዝ ማዶ ወስጄ በከነዓን ምድር ሁሉ መራሁት፤ ዘሩንም አበዛሁ፤ ይስሐቅንም ሰጠሁት።'),
  ('1387b576-096e-562f-a945-c80d1c817c3a', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 4, 4, 'ለይስሐቅም ያዕቆብንና ዔሳውን ሰጠሁት፤ ለዔሳውም የሴይርን ተራራ ርስት አድርጌ ሰጠሁት፤ የያዕቆብም ልጆች ወደ ግብፅ ወረዱ፤ በዚያም ታላቅ ሕዝብ ሆኑ፤ በዙም፤ በረቱም፤ ግብፃውያንም መከራ አጸኑባቸው።'),
  ('141fd95f-6b1a-5c92-ad52-1e8c2c3f7d22', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 5, 5, 'ሙሴንና አሮንንም ላክሁ፤ በእነርሱም ላይ ስላደረጉት ነገር ግብፃውያንን ቀሠፍኋቸው፤'),
  ('648abd77-ea61-5837-abbe-81134bcc9d0f', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 6, 6, 'ከዚያም በኋላ አባቶቻችሁን ከግብፅ አወጣኋቸው፤ ወደ ባሕሩም ገባችሁ፤ ግብፃውያንም አባቶቻችሁን በሰረገሎችና በፈረሶች እስከ ኤርትራ ባሕር ድረስ ተከተሉአቸው።'),
  ('996f2b9c-40e7-57ee-adbb-a6746971a080', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 7, 7, 'ወደ እግዚአብሔርም በጮሃችሁ ጊዜ በእናንተና በግብፃውያን መካከል ደመናንና ጭጋግን አደረግሁ፤ ባሕሩንም መለስሁባቸው፤ አሰጠማቸውም፤ ዐይኖቻችሁም በግብፅ ያደረግሁትን አዩ፤ በምድረ በዳም ብዙ ጊዜ ተቀመጣችሁ።'),
  ('4f28f6da-400f-5856-a391-596c93e56010', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 8, 8, 'በዮርዳኖስ ማዶ ወደ ተቀመጡት ወደ አሞሬዎናውያን ምድርም ወሰድኋችሁ፤ ከእናንተም ጋር ተዋጉ፤ ሙሴም ተዋጋቸው፤ አሳልፌም በእጃችሁ ሰጠኋችሁ፤ ምድራቸውንም ወረሳችሁ፤ ከፊታችሁም አጠፋኋቸው።'),
  ('a4a1f79b-06e6-5146-acdd-a63ffc8f7655', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 9, 9, 'የሞዓብም ንጉሥ የሴፎር ልጅ ባላቅ ተነሥቶ ከእስራኤል ጋር ተዋጋ፤ እንዲረግማችሁም የቢዖርን ልጅ በለዓምን ልኮ አስጠራው።'),
  ('ca3b9ac5-587b-5e40-a02b-acc3e6fc34ce', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 10, 10, 'እኔ ግን ላጠፋችሁ አልወደድሁም፤ መባረክንም ባረክኋችሁ፤ ከእጁም አዳንኋችሁ፤'),
  ('de4413e8-7f9f-58d6-ae8e-7de31b9eb90d', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 11, 11, 'ዮርዳኖስንም ተሻገራችሁ፤ ወደ ኢያሪኮም መጣችሁ፤ የኢያሪኮም ሰዎች፥ አሞሬዎናዊው፥ ፌርዜዎናዊው፥ ከነዓናዊው፥ ኬጤዎናዊው፥ ጌርጌሴዎናዊው፥ ኤዌዎናዊው፥ ኢያቡሴዎናዊው ተዋጉአችሁ፥ አሳልፌም በእጃችሁ ሰጠኋቸው።'),
  ('748d9d06-62c7-5eee-a605-9a4838c4b95a', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 12, 12, 'በፊታችሁም ተርብ ሰደድሁ፤ በሰይፍህም፥ በቀስትህም ሳይሆን ዐሥራ ሁለቱን የአሞሬዎናውያንን ነገሥታት ከፊታችሁ አሳደድኋቸው።'),
  ('7753b8a8-41ae-52ce-affe-2dfaaaddfd77', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 13, 13, 'ያልደከማችሁበትንም ምድር፥ ያልሠራችኋቸውንም ከተሞች ሰጠኋችሁ፤ ተቀመጣችሁባቸውም፤ ካልተከላችኋቸውም ከወይንና ከወይራ በላችሁ።’'),
  ('26db14af-c50a-5a2d-af2d-18a6150508a4', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 14, 14, '“አሁንም እግዚአብሔርን ፍሩት፤ በእውነትና በቅንነትም አምልኩት፤ አባቶቻችሁም በወንዝ ማዶ፥ በግብፅም ውስጥ ያመለኩአቸውን ሌሎች አማልክት ከእናንተ አርቁ፤ እግዚአብሔርንም አምልኩ።'),
  ('4287a2f1-34e0-530c-a560-8c4fdbd29034', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 15, 15, 'እግዚአብሔርን ታመልኩ ዘንድ ባትወድዱ ግን፥ አባቶቻችሁ በወንዝ ማዶ ሳሉ ያመለኩአቸውን አማልክት፥ ወይም በምድራቸው ያላችሁባቸውን የአሞሬዎናውያንን አማልክት ታመልኩ እንደ ሆነ፥ የምታመልኩትን ዛሬ ምረጡ። እኔና ቤቴ ግን እግዚአብሔርን እናመልካለን፤ እርሱ ቅዱስ ነውና።”'),
  ('5a8da3af-de02-5455-ab62-8ee30dd5a420', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 16, 16, 'ሕዝቡም መልሰው እንዲህ አሉ፥ “እግዚአብሔርን ትተን ሌሎች አማልክትን ማምለክ ከእኛ ይራቅ፤'),
  ('47151268-473c-59c3-a576-13a342b86e99', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 17, 17, 'እኛንና አባቶቻችንን ከባርነት ቤት ከግብፅ ምድር ያወጣን፥ በዐይናችንም ፊት እነዚያን ታላላቅ ተአምራት ያደረገ፥ በሄድንባትም መንገድ ሁሉ፥ ባለፍንባቸውም አሕዛብ ሁሉ መካከል የጠበቀን፥ እርሱ አምላካችን እግዚአብሔር ነውና።'),
  ('d320acdc-3e8c-5237-ae12-4f661a2a771d', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 18, 18, 'እግዚአብሔር አሕዛብን ሁሉ፥ በምድሪቱም የተቀመጡትን አሞሬዎናውያንን ከፊታችን አሳደደ፤ ስለዚህ እርሱ አምላካችን ነውና እኛ እግዚአብሔርን እናመልካለን።”'),
  ('111c44e9-0e0e-5faf-a562-a4d6f282ebac', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 19, 19, 'ኢያሱም ሕዝቡን፥ “እርሱ ቅዱስ አምላክ ነውና፥ እርሱም ቀናተኛ አምላክ ነውና እግዚአብሔርን ማምለክ አትችሉም፤ ብታስቀኑት መተላለፋችሁንና ኀጢአታችሁን ይቅር አይልም።'),
  ('2b9bd2e8-d617-5f52-a654-7aafe75cabe1', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 20, 20, 'እግዚአብሔርን ትታችሁ ሌሎችን አማልክት ብታመልኩ፥ መልካምን ባደረገላችሁ ፋንታ ተመልሶ ክፉ ነገር ያደርግባችኋል፤ ያጠፋችሁማል” አላቸው።'),
  ('11849b7b-2237-540f-a8d5-0d375e2cff57', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 21, 21, 'ሕዝቡም ኢያሱን፥ “እንዲህ አይሁን፤ ነገር ግን እግዚአብሔርን እናመልካለን” አሉት።'),
  ('485da4d3-99a1-5870-a7df-5ff360cc9c59', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 22, 22, 'ኢያሱም ሕዝቡን፥ “እንድታመልኩት እናንተ እግዚአብሔርን እንደ መረጣችሁ በራሳችሁ ላይ ምስክሮች ናችሁ” አላቸው፤ እነርሱም፥ “ምስክሮች ነን” አሉ።'),
  ('a4291544-8d33-5029-a07a-e0a583875ad3', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 23, 23, 'እርሱም፥ “አሁን እንግዲህ በእናንተ ዘንድ ያሉትን ሌሎች አማልክት አርቁ፤ ልባችሁንም ወደ እስራኤል አምላክ ወደ እግዚአብሔር አቅኑ” አላቸው።'),
  ('af3bad54-2811-5459-aaf6-271782cf65db', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 24, 24, 'ሕዝቡም ኢያሱን፥ “አምላካችንን እግዚአብሔርን እናመልካለን፤ ቃሉንም እንሰማለን” አሉት።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('5d1b1233-d3e0-5c4f-a0ec-5d76619c50bd', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 25, 25, 'በዚያም ቀን ኢያሱ ከሕዝቡ ጋር ቃል ኪዳን አደረገ፤ በሴሎም በእስራኤል አምላክ ድንኳን ፊት ሕግንና ፍርድን ሰጣቸው።'),
  ('4cf32298-5cde-5f97-a93d-62415724f264', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 26, 26, 'ኢያሱም ይህን ቃል ሁሉ በእግዚአብሔር ሕግ መጽሐፍ ጻፈው፤ ኢያሱም ታላቁን ድንጋይ ወስዶ በእግዚአብሔር ፊት በነበረችው በአሆማ ዛፍ በታች አቆማት።'),
  ('768a479a-497e-54f5-aa29-bf0c87433b11', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 27, 27, 'ኢያሱም ለሕዝቡ ሁሉ፥ “ይህች ድንጋይ በእናንተ ላይ ምስክር ናት፤ እርስዋ፥ ዛሬ እንደ ነገራችሁ በእግዚአብሔር ዘንድ የተባለውን ሁሉ ሰምታለችና በኋላ ዘመን አምላኬን እግዚአብሔርን ብትክዱት ይህች ድንጋይ ምስክር ትሆንባችኋለች” አላቸው።'),
  ('e2a0833b-f122-5350-a3be-0e3e226c180c', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'c61f5aa6-f7d7-5df6-aa44-6ee156e9ffb6', 28, 28, 'ኢያሱም ሕዝቡን አሰናበተ፤ ሁሉም ወደየቦታቸው ገቡ።'),
  ('f87c4e24-d3ed-56aa-a3a4-8b62310daa6b', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'ff6949a3-9031-5f7f-a743-94080f4ba703', 1, 29, 'እንዲህም ሆነ፤ ከዚህ ነገር በኋላ የእግዚአብሔር አገልጋይ የነዌ ልጅ ኢያሱ ዕድሜው መቶ ዐሥር ዓመት ሲሆነው ሞተ።'),
  ('31c6ddbe-679c-5d04-a813-b290d4cbf830', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'ff6949a3-9031-5f7f-a743-94080f4ba703', 2, 30, 'በተራራማውም በኤፍሬም ሀገር በገዓስ ተራራ በሰሜን ባለችው በርስቱ ዳርቻ በተምናሴራ ቀበሩት። በዚያም ከግብፅ በወጡ ጊዜ እግዚአብሔር እንዳዘዘው የእስራኤልን ልጆች በገልገላ የገረዘባቸውን የድንጋይ ባልጩቶችን እርሱን በቀበሩበት መቃብር ከእርሱ ጋር ቀበሩ፤ እስከ ዛሬም ድረስ በዚያ አሉ።'),
  ('de6bd2df-c221-5dc8-a292-39fe54702472', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'ff6949a3-9031-5f7f-a743-94080f4ba703', 3, 31, 'ኢያሱ ባለበት ዘመን ሁሉ፥ ከኢያሱም በኋላ በነበሩት ለእስራኤልም ያደረገውን የእግዚአብሔርን ሥራ ሁሉ ባወቁት በሽማግሌዎች ዘመን ሁሉ፥ እስራኤል እግዚአብሔርን አመለኩ።'),
  ('f124a0ad-cbb6-56c9-add6-1286126aad4c', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'ff6949a3-9031-5f7f-a743-94080f4ba703', 4, 32, 'የእስራኤልም ልጆች ከግብፅ ያወጡትን የዮሴፍን አፅም ያዕቆብ በሰቂማ ከሚኖሩ ከአሞራውያን በመቶ በጎች በገዛው ለዮሴፍ ድርሻ አድርጎ በሰጠው እርሻ በአንዱ ክፍል በሰቂማ ቀበሩት።'),
  ('ee1a99db-0144-56dd-a3ce-b5423b6d1a87', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'ff6949a3-9031-5f7f-a743-94080f4ba703', 5, 33, 'የአሮንም ልጅ ሊቀ ካህናቱ አልዓዛር ሞተ፤ በተራራማውም በኤፍሬም ሀገር ለልጁ ለፊንሐስ በተሰጠችው በጊብዓት መሬት ቀበሩት።'),
  ('1f7eb3ea-140e-5d5c-a8d8-d40f3053a159', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'ff6949a3-9031-5f7f-a743-94080f4ba703', 6, 34, 'የዚያን ጊዜ የእስራኤል ልጆች የእግዚአብሔርን ታቦት ከእነርሱ ጋር ይዘዋት ሄዱ። ፊንሐስም እስከ ሞተና በቦታቸው በጊብዓት እስከ ቀበሩት ድረስ በአባቱ በአልዓዛር ፋንታ ሊቀ ካህናት ሆነ።'),
  ('4a71e0c7-9b7b-5275-a894-f312acb92e0a', '2eab02e9-aa8b-50a9-a85a-1d1c15cce32d', 'ff6949a3-9031-5f7f-a743-94080f4ba703', 7, 35, 'የእስራኤልም ልጆች ሁሉ ወደ ከተሞቻቸውና ወደ ቤታቸው ገቡ። ከዚህ በኋላ የእስራኤል ልጆች አስጠራጢንንና አስጣሮትን፥ በዙሪያቸውም የነበሩትን የአሕዛብን አማልክት አመለኩ። እግዚአብሔርም በሞዓብ ንጉሥ በኤግሎም እጅ ጣላቸው፤ ዐሥራ ስምንት ዓመትም ገዛቸው።'),
  ('c6809127-fc01-5e2d-ab1a-93cd2d854ff4', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'bfbdce54-d5ae-55f8-a501-2c5e68b5171f', 1, 1, 'እንዲህም ሆነ፤ ኢያሱ ከሞተ በኋላ የእስራኤል ልጆች፥ “ከነዓናውያንን የሚወጋልን ማን አለቃ ይወጣልናል?” ብለው ወደ እግዚአብሔር ጠየቁ።'),
  ('5ddeff4c-b716-5eab-a49e-7538d169ae35', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'bfbdce54-d5ae-55f8-a501-2c5e68b5171f', 2, 2, 'እግዚአብሔርም፥ “ይሁዳ ይውጣ፤ እነሆ፥ ምድሪቱን በእጁ አሳልፌ ሰጥቼአታለሁ” አለ።'),
  ('ee47f540-7eae-5519-ad16-4a92a34974df', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'bfbdce54-d5ae-55f8-a501-2c5e68b5171f', 3, 3, 'ይሁዳም ወንድሙን ስምዖንን፥ “ከእኔ ጋር ወደ ዕጣዬ ውጣ፤ ከነዓናውያንንም እንውጋቸው፤ እኔም ደግሞ ከአንተ ጋር ወደ ዕጣህ እሄዳለሁ” አለው። ስምዖንም ከእርሱ ጋር ሄደ።'),
  ('a18411c4-0366-5966-aead-bcaf848a1cc3', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'bfbdce54-d5ae-55f8-a501-2c5e68b5171f', 4, 4, 'ይሁዳም ወጣ፤ እግዚአብሔርም ከነዓናውያንንና ፌርዜዎናውያንን በእጁ አሳልፎ ሰጣቸው፤ ከእነርሱም በቤዜቅ ውስጥ ዐሥር ሺህ ሰዎችን ገደለባቸው።'),
  ('b5380f34-fae9-5553-a048-047d49f8e25f', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'bfbdce54-d5ae-55f8-a501-2c5e68b5171f', 5, 5, 'አዶኒቤዜቅንም በቤዜቅ አገኙትና ተዋጉት፤ ከነዓናውያንንና ፌርዜዎናውያንንም ገደሉአቸው።'),
  ('43d0ebbf-2680-5fac-a2f5-055e719b9eaa', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'bfbdce54-d5ae-55f8-a501-2c5e68b5171f', 6, 6, 'አዶኒቤዜቅም ሸሸ፤ ተከታትለውም ያዙት፤ የእጁንና የእግሩንም አውራ ጣቶች ቈረጡ።'),
  ('24885a92-7a91-5310-aaa7-b76880f6c399', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'bfbdce54-d5ae-55f8-a501-2c5e68b5171f', 7, 7, 'አዶኒቤዜቅም፥ “የእጆቻቸውና የእግሮቻቸው አውራ ጣቶች የተቈረጡ ሰባ ነገሥታት ከገበታዬ በታች ፍርፋሪ ይለቅሙ ነበሩ፤ እኔ እንዳደረግሁ እግዚአብሔር እንዲሁ መለሰልኝ” አለ። ወደ ኢየሩሳሌምም ወሰዱት፥ በዚያም ሞተ።'),
  ('619307f8-4cbe-5b33-abdb-45d7efa5a0a5', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '985259f0-d211-5744-aa4e-37aad007dca0', 1, 8, 'የይሁዳም ልጆች ኢየሩሳሌምን ተዋግተው ያዙአት፤ በሰይፍ ስለትም መቱአት፤ ከተማዪቱንም በእሳት አቃጠሉአት።'),
  ('5a7bb726-d1d9-574e-ae2d-52741ddd6bd9', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '985259f0-d211-5744-aa4e-37aad007dca0', 2, 9, 'ከዚያም በኋላ የይሁዳ ልጆች በተራራማው ሀገርና በደቡብ በኩል በቈላው ውስጥ የሚኖሩትን ከነዓናውያንን ሊወጉ ወረዱ።'),
  ('185aceeb-5a0f-5ad6-ae14-c09dc8180f62', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '985259f0-d211-5744-aa4e-37aad007dca0', 3, 10, 'ይሁዳም በኬብሮን ወደሚኖሩ ከነዓናውያን ሄደ። የኬብሮንም ሰዎች ወጥተው ተቀበሉት፤ የኬብሮንም ስም አስቀድሞ ቂርያታርቦቅሴፌር ነበረ። የኤናቅንም ትውልድ ሴሲንና አኪማምን፥ ተለሜንንም ገደሉአቸው።'),
  ('81553a86-924a-575d-abc8-204ab6d51a96', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'f71165cc-0452-564b-ac3c-2c3dfcdfe428', 1, 11, 'ከዚያም ወደ ዳቤር ሰዎች ሄዱ፤ አስቀድሞም የዳቤር ስም ሀገረ መጻሕፍት ነበረ።'),
  ('12996c83-1456-5786-afed-708aaf88bab3', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'f71165cc-0452-564b-ac3c-2c3dfcdfe428', 2, 12, 'ካሌብም፥ “ሀገረ መጻሕፍትን ለሚመታና ለሚይዝ ልጄን ዓስካን ሚስት ትሆነው ዘንድ እሰጠዋለሁ” አለ።'),
  ('5ddffbdf-d5d6-5604-a967-a6c5e393bf82', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'f71165cc-0452-564b-ac3c-2c3dfcdfe428', 3, 13, 'የካሌብም ትንሽ ወንድም የቄኔዝ ልጅ ጎቶንያል ያዛት፤ ሚስትም ትሆነው ዘንድ ልጁን ዓስካን ሰጠው።'),
  ('ac865669-6401-5e33-acbe-b4e8296ae358', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'f71165cc-0452-564b-ac3c-2c3dfcdfe428', 4, 14, 'እርስዋም ወደ እርሱ በመጣች ጊዜ የእርሻ ቦታ ይሰጣት ዘንድ አባቷን እንድትለምነው ጎቶንያል መከራት። እርስዋም በአህያዋ ላይ ሆና አንጐራጐረች፤ “ወደ ደቡብ ሰድደኸኛል” ብላም ጮኸች። ካሌብም፥ “ምን ሆነሻል?” አላት።'),
  ('e8b79119-42e8-59cb-aa66-8cbc12e508ea', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', 'f71165cc-0452-564b-ac3c-2c3dfcdfe428', 5, 15, 'ዓስካም፥ “በረከትን ስጠኝ፤ ወደ ደቡብ በረሃ ሰድደኸኛልና ውኃ የማጣቴን ዋጋ ደግሞ ስጠኝ” አለችው። ካሌብም በልብዋ እንደ ተመኘችው የመከራዋንና የኀዘኗን ዋጋ ሰጣት።'),
  ('a48b5440-a7d1-58f7-a47c-19f01b3ed457', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '2f86d75c-e1d4-53c9-a43b-89d67b71f329', 1, 16, 'የቄናዊው የሙሴ አማት የዮባብ ልጆችም ከዘንባባ ከተማ ተነሥተው ከዓራድ በአዜብ በኩል ወዳለው ወደ ይሁዳ ምድረ በዳ ወደ ይሁዳ ልጆች ሄደው ከሕዝቡ ጋር ተቀመጡ።'),
  ('fa83613b-3932-5d54-a00b-14fc2e53dca7', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '2f86d75c-e1d4-53c9-a43b-89d67b71f329', 2, 17, 'ይሁዳም ከወንድሙ ከስምዖን ጋር ሄደ፤ በሴፌት የተቀመጡትንም ከነዓናውያንን መቱ፤ ፈጽመውም አጠፉአት፤ የከተማዪቱንም ስም ሕርም ብለው ጠሩአት።'),
  ('6390df9d-fcab-53c1-adfa-54bd6ee2cba1', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '2f86d75c-e1d4-53c9-a43b-89d67b71f329', 3, 18, 'ይሁዳም ጋዛንና አውራጃዋን፥ አስቀሎናንና አውራጃዋን፥ አቃሮንንና አውራጃዋን፥ አዛጦንንና አውራጃዋን አልወረሳትም።'),
  ('5606eeda-8587-528a-a6f5-d242807b6ba5', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '2f86d75c-e1d4-53c9-a43b-89d67b71f329', 4, 19, 'እግዚአብሔርም ከይሁዳ ጋር ነበረ፤ ይሁዳም ተራራማውን ሀገር ወረሰ፤ በሸለቆው የሚኖሩትን ግን የብረት ሰረገሎች ነበሩአቸውና ሊወርሳቸው አልቻለም።'),
  ('ab20d74a-bbf5-59d2-a042-04907659e1c5', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '2f86d75c-e1d4-53c9-a43b-89d67b71f329', 5, 20, 'ሙሴም እንደ ተናገረ ለካሌብ ኬብሮንን ሰጡት፤ ከዚያም ሠላሳ ከተሞችን ወረሰ፤ ከዚያም ሦስቱን የዔናቅ ልጆች አስወገዳቸው።'),
  ('753ae7f0-dd58-5f12-aa9a-543793370e5d', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '2f86d75c-e1d4-53c9-a43b-89d67b71f329', 6, 21, 'ነገር ግን በኢየሩሳሌም የሚኖሩትን ኢያቡሴዎናውያንን የብንያም ልጆች አላወጡአቸውም፤ ኢያቡሴዎናውያንም ከብንያም ልጆች ጋር እስከ ዛሬ ድረስ በኢየሩሳሌም ተቀምጠዋል።'),
  ('d7485c91-934a-5c7f-aef6-d0daa2c786fd', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '83584b50-5a92-51a6-a40c-d3e949f1d387', 1, 22, 'የዮሴፍም ልጆች ደግሞ ወደ ቤቴል ወጡ፤ እግዚአብሔርም ከእነርሱ ጋር ነበረ።'),
  ('c8544a42-b5f4-505c-a970-2745997ffeb5', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '83584b50-5a92-51a6-a40c-d3e949f1d387', 2, 23, 'እነርሱም ሰፍረው ቤቴልን ሰለሉአት። አስቀድሞም የዚያች ከተማ ስም ሎዛ ይባል ነበር።'),
  ('0d3ff9b1-50bc-5cb7-aa22-86d8e650e0b2', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '83584b50-5a92-51a6-a40c-d3e949f1d387', 3, 24, 'ጠባቂዎቹም አንድ ሰው ከከተማ ሲወጣ አይተው ያዙትና፥ “የከተማዪቱን መግቢያ አሳየን፤ እኛም ምሕረት እናደርግልሃለን” አሉት።'),
  ('a476c023-7c41-53f0-a9a1-c9a1cf60a074', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '83584b50-5a92-51a6-a40c-d3e949f1d387', 4, 25, 'የከተማዪቱንም መግቢያ አሳያቸው፤ ከተማዪቱንም በሰይፍ ስለት መቱአት፤ ያን ሰውና ዘመዶቹን ግን ለቀቁአቸው።'),
  ('52e63a0f-e526-5ffd-a4a6-f80a9f25ae09', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '83584b50-5a92-51a6-a40c-d3e949f1d387', 5, 26, 'ሰውየውም ወደ ኬጤዎናውያን ምድር ሄደ፤ በዚያም ከተማን ሠራ፤ ስምዋንም ሎዛ ብሎ ጠራት። እስከ ዛሬም ድረስ ስምዋ ያው ነው።'),
  ('4d07a3d8-1e6b-5a64-a63d-6c165036c66b', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '49227683-795e-5276-aaa7-8a96a23f916f', 1, 27, 'ምናሴም የሰቂቶን ከተማ ቤትሶንንና መንደሮችዋን መሰማሪያዎችዋንም፥ ኢቀጸአድንና መንደሮችዋን፥ የዶርን ነዋሪዎችና መንደሮችዋን፥ የዮበለዓምን ነዋሪዎች፥ መሰማሪያዎችዋንና መንደሮችዋን፥ የመጊዶን ነዋሪዎች መሰማሪያዎችዋንና መንደሮችዋን አልወረሳቸውም፤ ነገር ግን ከነዓናውያን በዚያች ሀገር ይቀመጡ ዘንድ ጸኑ።'),
  ('636dd8f4-d0e3-527e-a4f9-52d5954170e7', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '49227683-795e-5276-aaa7-8a96a23f916f', 2, 28, 'እስራኤልም በበረቱ ጊዜ ከነዓናውያንን ገባሮች አደረጉአቸው፤ ነገር ግን ፈጽመው አላጠፏቸውም።'),
  ('575614f9-d18f-53de-ab42-d39178d4d000', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '49227683-795e-5276-aaa7-8a96a23f916f', 3, 29, 'ኤፍሬምም በጋዜር የተቀመጡትን ከነዓናውያንን አላጠፋቸውም፤ ነገር ግን ከነዓናውያን በመካከላቸው በጋዜር ተቀመጡ፤ ገባሮችም ሆኑላቸው።'),
  ('642bf8c2-d9b8-5660-a530-5e524aa8030c', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '49227683-795e-5276-aaa7-8a96a23f916f', 4, 30, 'ዛብሎንም በቄድሮንና በአማን የሚኖሩትን ሰዎች አላጠፋቸውም፤ ነገር ግን ከነዓናውያን በመካከላቸው ተቀመጡ፤ ግብርም የሚገብሩላቸው ሆኑ።'),
  ('a9449e95-9f3a-5be3-aba3-696c44062172', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '49227683-795e-5276-aaa7-8a96a23f916f', 5, 31, 'አሴርም የዓኮ ነዋሪዎችን አላጠፋቸውም፤ ነገር ግን ገባሮች ሆኑላቸው፤ የዶር ነዋሪዎችንና የሲዶን ነዋሪዎችን፥ የደላፍንም ነዋሪዎች፥ የአክሶዚብንና የሄልባን፥ የአፌቅንና የረዓብንም ሰዎች አላጠፉአቸውም።'),
  ('b701729d-854c-5b5e-aa0f-cc4c165a86e1', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '49227683-795e-5276-aaa7-8a96a23f916f', 6, 32, 'አሴርም በዚያች ምድር በተቀመጡት ከነዓናውያን መካከል ተቀመጠ፤ ሊያጠፋቸው አልቻለምና።'),
  ('3e6e6d9b-403b-599b-a4e9-67f549756afd', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '49227683-795e-5276-aaa7-8a96a23f916f', 7, 33, 'ንፍታሌምም የቤትሳሚስንና የቤቴኔስን ሰዎች አላጠፋቸውም፤ በምድሩም በተቀመጡት በከነዓናውያን መካከል ተቀመጡ፤ ነገር ግን በቤትሳሚስና በቤቴኔስ የሚኖሩ ሰዎች ገባሮች ሁኑላቸው።'),
  ('3f031edc-b6ee-505f-ab69-e55c329fd7f8', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '49227683-795e-5276-aaa7-8a96a23f916f', 8, 34, 'አሞሬዎናውያንም የዳንን ልጆች በተራራማው ሀገር አስጨነቁአቸው፤ ወደ ሸለቆው እንዲወርዱ አይፈቅዱላቸውም ነበርና።'),
  ('09fc3eef-9081-5192-aff3-c9fb6c973eac', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '49227683-795e-5276-aaa7-8a96a23f916f', 9, 35, 'አሞሬዎናውያንም ድብና ቀበሮዎች በሚኖሩበት በመርስኖኖስ ተራራ መቀመጥ ጀመሩ፤ ነገር ግን የዮሴፍ ወገን እጅ በአሞሬዎናውያን ላይ ጸናች፤ ገባርም አደረጉአቸው።'),
  ('d953380c-7057-5b19-a74a-34130d80f43d', 'a4eecbfd-1563-5c74-a67e-d4807dab3e57', '49227683-795e-5276-aaa7-8a96a23f916f', 10, 36, 'የአሞናውያንም ድንበር ከአቅራቢም ዐቀበት ከጭንጫው ጀምሮ እስከ ላይኛው ድረስ ነበረ።'),
  ('06cba01b-bc2e-5f27-a9f3-4b4b5bb39475', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '9052f420-d113-5aff-a2d1-b1593cbd7ae7', 1, 1, 'የእግዚአብሔርም መልአክ ከገልገላ ወደ ቀላውትምኖስ ወደ ቤቴል ወደ እስራኤል ቤት ወጥቶ እንዲህ አላቸው፥ “እግዚአብሔር እኔ ከግብፅ አውጥቼአችኋለሁ፤ እሰጣችሁም ዘንድ ለአባቶቻችሁ ወደ ማልሁላቸው ምድር አግብቻችኋለሁ፤ እኔም፦ ከእናንተ ጋር ያደረግሁትን ቃል ኪዳን ለዘለዓለም አላፈርስም፤'),
  ('869f8a04-cc84-5da4-a127-03e38f0d5c00', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '9052f420-d113-5aff-a2d1-b1593cbd7ae7', 2, 2, 'እናንተም በዚች ምድር ከሚኖሩ ሰዎች ጋር ቃል ኪዳን አታድርጉ፤ ለአማልክቶቻቸውም አትስገዱላቸው፤ ምስሎቻቸውንም ስበሩ፤ መሠዊያቸውንም አፍርሱ አልሁ። እናንተ ግን ቃሌን አልሰማችሁም፤ ይህንስ ለምን አደረጋችሁ?'),
  ('e6b23389-dcea-518e-a47d-911291c942fb', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '9052f420-d113-5aff-a2d1-b1593cbd7ae7', 3, 3, 'ስለዚህም እኔ አሕዛብን ከፊታችሁ አላወጣቸውም፤ ነገር ግን ያስጨንቋችኋል፤ አማልክቶቻቸውም ወጥመድ ይሆኑባችኋል” አልሁ።'),
  ('5557bbf5-d690-5634-a1a9-2a1489c98582', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '9052f420-d113-5aff-a2d1-b1593cbd7ae7', 4, 4, 'የእግዚአብሔርም መልአክ ይህን ቃል ለእስራኤል ልጆች ሁሉ በተናገረ ጊዜ ሕዝቡ ሁሉ ድምፃቸውን አንሥተው አለቀሱ።'),
  ('15417378-603a-58e5-a002-f86e61e03fd8', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '9052f420-d113-5aff-a2d1-b1593cbd7ae7', 5, 5, 'የዚያም ስፍራ ስም “መካነ ብካይ” ተብሎ ተጠራ፤ በዚያም ለእግዚአብሔር ሠዉ።'),
  ('4666b20b-e3a3-55e8-a573-9ea7c695ce13', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '0191f920-c756-5279-ac0d-c92d6cee2e27', 1, 6, 'ኢያሱም ሕዝቡን ባሰናበተ ጊዜ የእስራኤል ልጆች ምድሪቱን ሊወርሱ ወደየርስታቸው ገቡ።'),
  ('27892e4f-c8af-5edc-addc-bdc1fa0c0676', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '0191f920-c756-5279-ac0d-c92d6cee2e27', 2, 7, 'ኢያሱም በነበረበት ዘመን ሁሉ፥ ለእስራኤልም ያደረገውን ታላቁን የእግዚአብሔርን ሥራ ሁሉ ባወቁት፥ ከኢያሱ በኋላ በነበሩ ሽማግሌዎች ዘመን ሁሉ ሕዝቡ ለእግዚአብሔር ተገዙ።'),
  ('b4707e65-19e1-5b4e-a544-89a8287d2024', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '0191f920-c756-5279-ac0d-c92d6cee2e27', 3, 8, 'የእግዚአብሔርም አገልጋይ የነዌ ልጅ ኢያሱ ዕድሜው መቶ ዐሥር ዓመት ሲሆነው ሞተ።'),
  ('82a85b37-8c4b-5496-a80c-f8855282f7af', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '0191f920-c756-5279-ac0d-c92d6cee2e27', 4, 9, 'በተራራማዉ በኤፍሬም ሀገር በገዓስ ተራራ በሰሜን ባለችው በርስቱ ዳርቻ በተምናሴራ ቀበሩት።'),
  ('1e173509-cef0-51c5-a6eb-469cbb696850', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '0191f920-c756-5279-ac0d-c92d6cee2e27', 5, 10, 'ትውልድ ሁሉ ደግሞ ወደ አባቶቻቸው ተጨመሩ፤ ከእነዚያም በኋላ እግዚአብሔርንና ለእስራኤልም ያደረገውን ሥራ ያላወቀ ሌላ ትውልድ ተነሣ።'),
  ('8bbb84f1-12da-5ed9-a30f-83bda0a26def', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6fd696cf-d9e2-5500-a789-fe820b8c2de5', 1, 11, 'የእስራኤልም ልጆች በእግዚአብሔር ፊት ክፉ አደረጉ፤ በዓሊምንም አመለኩ።'),
  ('c1ac12ed-981f-5575-a437-f69d11156d29', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6fd696cf-d9e2-5500-a789-fe820b8c2de5', 2, 12, 'ከግብፅ ምድርም ያወጣቸውን የአባቶቻቸውን አምላክ እግዚአብሔርን ተዉ፤ ሌሎችንም በዙሪያቸው ያሉ የአሕዛብን አማልክት ተከተሉ፤ ሰገዱላቸውም፤ እግዚአብሔርንም አስቈጡት።'),
  ('42850ff2-7b54-54d1-ac6f-2425683209bb', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6fd696cf-d9e2-5500-a789-fe820b8c2de5', 3, 13, 'እግዚአብሔርንም ትተው በዓልንና አስታሮትን አመለኩ።'),
  ('a1dd39c7-6490-5065-a349-f5758d2c655c', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6fd696cf-d9e2-5500-a789-fe820b8c2de5', 4, 14, 'እግዚአብሔርም በእስራኤል ላይ ተቈጣ፤ ወደ ማረኳቸውም ማራኪዎች እጅ አሳልፎ ሰጣቸው፤ ማረኩአቸውም፤ በዙሪያቸውም ባሉት በጠላቶቻቸው እጅ አሳልፎ ሰጣቸው፤ ከዚያም ወዲያ ጠላቶቻቸውን ሊቋቋሙ አልቻሉም።'),
  ('93e96d74-a7c2-5ebd-ab96-1fea45e5cd9b', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6fd696cf-d9e2-5500-a789-fe820b8c2de5', 5, 15, 'እግዚአብሔርም እንደ ተናገረ፥ እግዚአብሔርም በእነርሱ ላይ እንደ ማለ፥ ወደ ወጡበት ሁሉ የእግዚአብሔር እጅ ትከፋባቸው ነበረች፤ እጅግም ተጨነቁ።'),
  ('9a02f05a-95f7-55c4-ac43-220ff97f80a8', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6054e3ab-04c9-5ebd-a3b6-d7ea73ce6993', 1, 16, 'እግዚአብሔርም መሳፍንትን አስነሣላቸው፤ ከሚማርኳቸውም እጅ አዳኗቸው።'),
  ('a2492c5f-593a-5bb8-a991-5dd660ca49ad', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6054e3ab-04c9-5ebd-a3b6-d7ea73ce6993', 2, 17, 'ሌሎች አማልክትን ተከትለው አመነዘሩ፤ ሰገዱላቸውም እንጂ፥ መሳፍንቶቻቸውን አልሰሙም፤ እግዚአብሔርንም አስቈጡት፤ የእግዚአብሔርንም ቃል እንዳይሰሙ አባቶቻቸው ይሄዱባት የነበረችውን መንገድ ፈጥነው ተዉአት፤ እንዲሁም አላደረጉም።'),
  ('8bdc417c-b2c3-5a4b-a0d6-8f760b6d2d65', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6054e3ab-04c9-5ebd-a3b6-d7ea73ce6993', 3, 18, 'እግዚአብሔርም መሳፍንትን ባስነሣላቸው ጊዜ እግዚአብሔር ከመስፍኑ ጋር ነበረ፤ እግዚአብሔርም በሚዋጉአቸው ሰዎች ፊት ከመከራቸው የተነሣ ይቅር ብሏቸዋልና በመስፍኑ ዘመን ሁሉ ከጠላቶቻቸው እጅ አዳናቸው።'),
  ('0c6d211b-7a8f-596e-a849-26702762c30c', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6054e3ab-04c9-5ebd-a3b6-d7ea73ce6993', 4, 19, 'መስፍኑ ግን ከሞተ በኋላ ዳግመኛ ተመልሰው ከአባቶቻቸው ይልቅ እጅግ ይበድሉ፤ ነበር፤ ሂደውም ሌሎች አማልክትን ተከትለው ያመልኳቸው ነበር፤ ይሰግዱላቸውም ነበር፤ ክፋታቸውንም አይተዉም ነበር፤ ከክፉ መንገዳቸውም አይመለሱም ነበር።'),
  ('331cdd71-1412-5f2c-a8b7-4931cc5a2fb7', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6054e3ab-04c9-5ebd-a3b6-d7ea73ce6993', 5, 20, 'እግዚአብሔርም በእስራኤል ላይ ፈጽሞ ተቈጣ፤ እንዲህም አለ፥ “ይህ ሕዝብ ለአባቶቻቸው ያዘዝሁትን ቃል ኪዳን ስለ ተላለፉ፥ ቃሌንም ስላልሰሙ፥'),
  ('477bb11f-ea7d-571e-aeee-8b5d61a22cff', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6054e3ab-04c9-5ebd-a3b6-d7ea73ce6993', 6, 21, 'እኔም የነዌ ልጅ ኢያሱ ትቶአቸው ከአለፈ አሕዛብ አንዱን ሰው እንኳን ከእንግዲህ ወዲህ ከፊታቸው አላወጣም።'),
  ('d9f12b8f-c872-59e0-a06a-80d57f0a8a6b', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6054e3ab-04c9-5ebd-a3b6-d7ea73ce6993', 7, 22, 'አባቶቻቸው እንደ ጠበቁ፥ ይሄዱባት ዘንድ የእግዚአብሔርን መንገድ ይጠብቁ ወይም አይጠብቁ እንደ ሆነ እስራኤልን እፈትንባቸው ዘንድ፤”'),
  ('a0811e76-c748-5159-a5f3-8b1988df67f3', 'ec538d07-19e7-50a2-a678-85694ecc8c76', '6054e3ab-04c9-5ebd-a3b6-d7ea73ce6993', 8, 23, 'እግዚአብሔርም እነዚህን አሕዛብ አስቀረ፤ ፈጥኖም አላወጣቸውም፤ በኢያሱም እጅ አሳልፎ አልሰጣቸውም።'),
  ('be611262-7e7a-5702-a221-1724f236db90', '90aa691d-bb64-5a15-a484-177bd78e964d', '116b92df-3b92-5d07-a2b1-bd734ed086ba', 1, 1, 'የከነዓናውያንንም ጦርነት ሁሉ ያላወቁትን እስራኤልን በእነርሱ ይፈትናቸው ዘንድ እግዚአብሔር እነዚህን አሕዛብ ተዋቸው።'),
  ('ef10dc0b-5097-5ea1-a577-9277c99e46de', '90aa691d-bb64-5a15-a484-177bd78e964d', '116b92df-3b92-5d07-a2b1-bd734ed086ba', 2, 2, 'ይህም ጦርነትን ያስተምሩአቸው ዘንድ ስለ እስራኤል ልጆች ትውልድ ብቻ ነው፤ ነገር ግን ከእነርሱ በፊት የነበሩት እነዚህን አላወቋቸውም ነበር፤'),
  ('a639cd61-7dad-5559-a6fb-c8778e6c4827', '90aa691d-bb64-5a15-a484-177bd78e964d', '116b92df-3b92-5d07-a2b1-bd734ed086ba', 3, 3, 'እነርሱም አምስቱ የፍልስጥኤማውያን መኳንንት፥ ከነዓናውያንም ሁሉ ፥ ሲዶናውያንም፥ ከበዓልሄርሞን ተራራ ጀምሮ እስከ ኤማት መግቢያ ድረስ በሊባኖስ ተራራ የሚኖሩትም ኤዌዎናውያን፤'),
  ('bde43e60-1963-59b9-a0b0-cbde5147b3f5', '90aa691d-bb64-5a15-a484-177bd78e964d', '116b92df-3b92-5d07-a2b1-bd734ed086ba', 4, 4, 'እግዚአብሔር በሙሴ እጅ ለአባቶቻቸው ያዘዘውን ትእዛዝ መስማታቸው እንዲታወቅ እስራኤል ይፈተኑባቸው ዘንድ እነዚህ ቀሩ።'),
  ('0e3f011c-d67a-535c-ae1e-4bcc077de1f5', '90aa691d-bb64-5a15-a484-177bd78e964d', '116b92df-3b92-5d07-a2b1-bd734ed086ba', 5, 5, 'የእስራኤልም ልጆች በከነዓናውያን፥ በኬጤዎናውያን፥ በአሞሬዎናውያን፥ በፌርዜዎናውያን፥ በኤዌዎናውያን፥ በኢያቡሴዎናውያንም መካከል ተቀመጡ።'),
  ('a955993d-3d77-5ee9-a1e3-98eeca636c0e', '90aa691d-bb64-5a15-a484-177bd78e964d', '116b92df-3b92-5d07-a2b1-bd734ed086ba', 6, 6, 'ሴቶች ልጆቻቸውንም አገቡአቸው፤ እነርሱም ሴቶች ልጆቻቸውን ለወንዶች ልጆቻቸው ሰጡ፤ አማልክቶቻቸውንም አመለኩ።'),
  ('07facfee-7249-5335-a222-d3011c53b2c8', '90aa691d-bb64-5a15-a484-177bd78e964d', '38499795-df32-55c4-a20f-2abc03734972', 1, 7, 'የእስራኤልም ልጆች በእግዚአብሔር ፊት ክፉ አደረጉ፤ አምላካቸውንም እግዚአብሔርን ረስተው በዓሊምንና አስታሮትን አመለኩ።'),
  ('df8646cf-0b6c-5422-a422-ff35f893f9e7', '90aa691d-bb64-5a15-a484-177bd78e964d', '38499795-df32-55c4-a20f-2abc03734972', 2, 8, 'ስለዚህ እግዚአብሔር በእስራኤል ላይ ፈጽሞ ተቈጣ፤ በወንዞችም መካከል ባለች በሶርያ ንጉሥ በኩሳርሳቴም እጅ አሳልፎ ሰጣቸው፤ የእስራኤልም ልጆች ለኩሳርሳቴም ስምንት ዓመት ተገዙለት።'),
  ('397c73b9-7337-53b1-aadd-215eb171364e', '90aa691d-bb64-5a15-a484-177bd78e964d', '38499795-df32-55c4-a20f-2abc03734972', 3, 9, 'የእስራኤልም ልጆች ወደ እግዚአብሔር ጮኹ። እግዚአብሔርም ለእስራኤል መድኀኒትን አስነሣላቸው። የካሌብ የታናሽ ወንድሙ የቄኔዝ ልጅ ጎቶንያልም አዳናቸው፤ ለእርሱም ታዘዙለት።'),
  ('fe527a71-93df-5cc8-a964-95f3293c3cb7', '90aa691d-bb64-5a15-a484-177bd78e964d', '38499795-df32-55c4-a20f-2abc03734972', 4, 10, 'የእግዚአብሔርም መንፈስ በእርሱ ላይ አደረ፤ በእስራኤልም ላይ ይፈርድ ነበር፤ ለጦርነትም ወጣ፤ እግዚአብሔርም በወንዞች መካከል ያለች የሶርያ ንጉሥ ኩሳርሳቴምን በእጁ አሳልፎ ሰጠው፤ እጁም በኩሳርሳቴም ላይ በረታች።'),
  ('eab97162-5274-59dd-a0fb-c2fd1db2647f', '90aa691d-bb64-5a15-a484-177bd78e964d', '38499795-df32-55c4-a20f-2abc03734972', 5, 11, 'ምድሪቱም አርባ ዓመት ዐረፈች፤ የቄኔዝም ልጅ ጎቶንያል ሞተ።'),
  ('c61ebf26-b57b-5bf0-ad76-72b13497dcef', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 1, 12, 'የእስራኤልም ልጆች በእግዚአብሔር ፊት እንደ ገና ክፉ ሥራ ሠሩ፤ በእግዚአብሔርም ፊት ክፉ ስለ ሠሩ እግዚአብሔር የሞዓብን ንጉሥ ዔግሎምን በእስራኤል ላይ አበረታባቸው።'),
  ('d718fc3a-7f40-5dc0-a2e7-9a76f5fbd59b', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 2, 13, 'የአሞንን ልጆችና አማሌቅን ወደ እርሱ ሰበሰበ፤ ሄዶም እስራኤልን መታ፤ ዘንባባ ያለባትንም ከተማ ያዘ።'),
  ('c5ffe398-5f15-50dc-a7e7-7bc8bd383a1e', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 3, 14, 'የእስራኤልም ልጆች ለሞዓብ ንጉሥ ለዔግሎም ዐሥራ ስምንት ዓመት ተገዙ።'),
  ('a52a5624-73dc-5870-abc4-ed52529fc898', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 4, 15, 'የእስራኤልም ልጆች ወደ እግዚአብሔር ጮኹ፤ እግዚአብሔርም ብንያማዊውን የጌራን ልጅ ናዖድን ሁለቱ እጆቹ ቀኝ የሆኑለትን ሰው አዳኝ አስነሣላቸው፤ የእስራኤልም ልጆች በእርሱ እጅ ወደ ሞዓብ ንጉሥ ወደ ዔግሎም እጅ መንሻ ላኩ።'),
  ('7e69bd12-ae47-590f-a045-819de04af949', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 5, 16, 'ናዖድም ሁለት አፍ ያላት ርዝመቷ አንድ ስንዝር የሆነች ሰይፍ አበጀ፤ ከልብሱም በታች በቀኝ በኩል በወገቡ ታጠቃት።'),
  ('35057a3f-584d-5639-aec0-fb0afdfb7dac', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 6, 17, 'ለሞዓብም ንጉሥ ለዔግሎም እጅ መንሻውን አቀረበ፤ ዔግሎምም እጅግ ወፍራም ሰው ነበረ።'),
  ('de985d0c-eb40-52e5-ac65-9187d4a3bfdb', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 7, 18, 'እጅ መንሻውንም ማቅረብ በጨረሰ ጊዜ፥ እጅ መንሻ የተሸከሙትን ሰዎች አሰናበታቸው።'),
  ('7eb6c671-9a5d-5548-a2d9-575e76a8d4a8', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 8, 19, 'ዔግሎምም ከገልገል ከጣዖታቱ ቤት ተመለሰ። ናዖድም፥ “ንጉሥ ሆይ፥ ለብቻህ የምነግርህ የምሥጢር ነገር አለኝ” አለ፤ ዔግሎምም ሁሉ ከእርሱ ዘንድ እንዲወጣ አዘዘ፤ በእርሱም ዘንድ የቆሙት ሁሉ ወጡ ።'),
  ('9ff6121b-b7f0-5c1c-a63f-646232d10b02', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 9, 20, 'ናዖድም ወደ እርሱ ገባ፤ እርሱም በበጋ ቤቱ ሰገነት ለብቻው ተቀምጦ ነበር። ናዖድም፥ “ንጉሥ ሆይ! የእግዚአብሔር መልእክት ለአንተ አለኝ” አለው። ዔግሎምም ከዙፋኑ ተነሣ፥ ቀረበውም።'),
  ('ac62e199-091b-5f29-a303-3b14aacf240f', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 10, 21, 'ናዖድም በተነሣ ጊዜ ግራ እጁን ዘርግቶ ከቀኝ ጎኑ ሰይፉን መዘዘ፤ ዔግሎምንም ሆዱን ወጋው፤'),
  ('28a93dbb-cc9f-5f9c-ae40-f530c50f7788', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 11, 22, 'እስከ ውላጋዋም አስገባት፤ እስከ ጀርባውም በረበረው፥ ሰይፉንም ከሆዱ መልሶ አላወጣትም።'),
  ('ade2136e-c9fb-5985-a46f-5caa54c1bf81', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 12, 23, 'ናዖድም የእልፍኙን ደጅ ዘግቶና ቈልፎ ወደ ውጭ ወጣ።'),
  ('47a8391e-5092-52e6-acf3-90befec3bfdd', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 13, 24, 'ናዖድም ከሄደ በኋላ አገልጋዮቹ መጡ፤ የሰገነቱም ደጅ ተቈልፎ ባዩ ጊዜ፥ “ምናልባት በበጋ ሰገነቱ ውስጥ ወገቡን ይሞክር ይሆናል” አሉ።'),
  ('c8003667-58af-58e8-a329-569bf285751f', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 14, 25, 'እስኪያፍሩም ድረስ ቈዩ፤ የሰገነቱንም ደጅ እንዳልከፈተ ባዩ ጊዜ መክፈቻውን ወስደው ከፈቱ፤ እነሆም፥ ጌታቸው በምድር ላይ ወድቆ ሞቶም አገኙት።'),
  ('0aaa188f-18cd-5044-a108-454f888a35e2', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 15, 26, 'እስከሚታወኩም ድረስ ናዖድ አመለጠ፤ ያወቀውም የለም፤ ከጣዖቶቻቸውም አልፎ ወደ ሴይሮታ አመለጠ።'),
  ('ac8534b3-446d-5e3f-a3a9-8b3ac5e79178', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 16, 27, 'ከዚህም በኋላ ወደ እስራኤል ምድር በደረሰ ጊዜ በተራራማው በኤፍራም ሀገር ቀንደ መለከት ነፋ፤ የእስራኤልም ልጆች ከእርሱ ጋር ከተራራማው ሀገር ወረዱ፤ እርሱም በፊታቸው ሄደ።'),
  ('ff144975-7124-53d7-a025-42ba6f9aa3d3', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 17, 28, 'እርሱም፥ “እግዚአብሔር አምላክ ጠላቶቻችንን ሞዓባውያንን በእጃችን አሳልፎ ሰጥቶናልና ተከተሉኝ” አላቸው። ተከትለውትም ወረዱ፤ ወደ ሞዓብም የሚያሻግረውን የዮርዳኖስን መሻገርያ ያዙ፤ ማንም ሰው እንዲያልፍ አልፈቀዱም።'),
  ('038c23a1-3991-53fb-a268-4ecd56f6a7e9', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 18, 29, 'በዚያም ወራት ከሞዓብ ዐሥር ሺህ የሚያህሉትን፥ ጐልማሶችና ጽኑዓን ሁሉ ገደሉ፤ ከእነርሱም አንድ ሰው እንኳ አላመለጠም።'),
  ('cb0e835e-814f-5028-abc6-6a3c4a3d63a1', '90aa691d-bb64-5a15-a484-177bd78e964d', '3980f4ae-5e44-5e0f-a7ff-8f0a55fa1781', 19, 30, 'በዚያም ወራት ሞዓባውያን በእስራኤል እጅ ገቡ፤ ምድሪቱም ሰማንያ ዓመት ዐረፈች። ናዖድም እስኪሞት ድረስ ገዛቸው።'),
  ('a92463ac-f596-52c4-af1e-78e8f374aa8f', '90aa691d-bb64-5a15-a484-177bd78e964d', '537f40e9-4943-508f-af0c-d8b697f6285a', 1, 31, 'ከእርሱም በኋላ የሐናት ልጅ ሴሜጋር ተነሣ፤ ከፍልስጥኤማውያንም ስድስት መቶ ሰው በበሬ መውጊያ ገደለ፤ እርሱም ደግሞ እስራኤልን አዳነ።'),
  ('64fa452e-315a-5d84-accb-a04e723af546', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 1, 1, 'የእስራኤል ልጆችም በእግዚአብሔር ፊት እንደ ገና ክፉ ሥራ ሠሩ፤ ናዖድ ግን ሞቶ ነበር።'),
  ('afa8ec6a-2d43-5064-a2e6-1c906fc4027a', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 2, 2, 'እግዚአብሔርም በአሦር በነገሠው በከነዓን ንጉሥ በኢያቢን እጅ አሳልፎ ሰጣቸው፤ የሠራዊቱም አለቃ ሲሣራ ነበረ፤ እርሱም በአሕዛብ አሪሶት ይቀመጥ ነበረ።'),
  ('fac08a8d-b8be-54d6-ad97-ed036c527658', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 3, 3, 'የእስራኤልም ልጆች ወደ እግዚአብሔር ጮኹ፤ ዘጠኝ መቶ የብረት ሰረገሎች ነበሩትና፥ የእስራኤልንም ልጆች ሃያ ዓመት እጅግ ያስጨንቃቸው ነበር።'),
  ('d40cb6b7-2c6b-5118-afc6-fd5f5d9d4d24', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 4, 4, 'በዚያም ወራት ነቢይቱ የለፊዶት ሚስት ዲቦራ እስራኤልን ትገዛቸው ነበረች።'),
  ('0b33c88f-7486-5e74-ac0f-4073c4076560', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 5, 5, 'እርስዋም በኤፍሬም ተራራ በቤቴልና በኢያማ መካከል “የዲቦራ ዘንባባ” ተብሎ በሚጠራው ዛፍ ሥር ተቀምጣ ነበር፤ የእስራኤልም ልጆች ወደ እርስዋ ለፍርድ ይወጡ ነበር።'),
  ('4b8c5997-8093-5eda-aca2-df6362db5446', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 6, 6, 'ዲቦራም ልካ ከቃዴስ ንፍታሌም የአቢኒሔምን ልጅ ባርቅን ጠርታ እንዲህ አለችው፥ “የእስራኤል አምላክ እግዚአብሔር እንዲህ ብሎ ያዘዘህ አይደለምን? ሄደህ ወደ ታቦር ተራራ ውጣ፤ ከአንተም ጋር ከንፍታሌምና ከዛብሎን ልጆች ዐሥር ሺህ ሰዎች ውሰድ፤'),
  ('c28461b6-35b6-5e3c-adb8-bc4e73776e14', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 7, 7, 'እኔም የኢያቢንን ሠራዊት አለቃ ሲሣራን፥ ሰረገሎቹንም፥ ሕዝቡንም ሁሉ ወደ አንተ ወደ ቂሶን ወንዝ እስባለሁ፤ በእጅህም አሳልፌ እሰጠዋለሁ።”'),
  ('d782c307-d714-5060-a850-4aaabb385a7e', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 8, 8, 'ባርቅም፥ “አንቺ ከእኔ ጋር ብትሄጂ እኔ እሄዳለሁ፤ አንቺ ግን ከእኔ ጋር ባትሄጂ እኔ አልሄድም፤ እግዚአብሔር መልአኩን ከእኔ ጋር የሚልክበትን ዕለት አላውቃትምና” አላት።'),
  ('fa38926f-0a34-542f-afa1-b30357d82dde', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 9, 9, 'ዲቦራም፥ “በእውነት ከአንተ ጋር እሄዳለሁ፤ ነገር ግን እግዚአብሔር ሲሣራን በሴት እጅ አሳልፎ ይሰጣልና በዚህ በምትሄድበት መንገድ ለአንተ ክብር አይሆንም” አለችው። ዲቦራም ተነሥታ ከባርቅ ጋር ወደ ቃዴስ ሄደች።'),
  ('acfe998e-d3ef-58fc-a275-eece8835399c', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 10, 10, 'ባርቅም ዛብሎንንና ንፍታሌምን ወደ ቃዴስ ጠራቸው፤ ዐሥር ሺህም ሰዎች ተከትለውት ወጡ፤ ዲቦራም ከእርሱ ጋር ወጣች።'),
  ('220e6761-e1c2-510c-afe5-93637f23fb60', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 11, 11, 'ቄናዊውም ሔቤር ከሙሴ አማት ከኢዮባብ ልጆች ከቄናውያን ተለይቶ ድንኳኑን በቃዴስ አጠገብ እስከ ነበረው ታላቅ ዛፍ ድረስ ተከለ።'),
  ('7d7dea38-a8b3-57a5-aa2e-9adc51c5f30c', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 12, 12, 'የአቢኒሔምም ልጅ ባርቅ ወደ ታቦር ተራራ እንደ ወጣ ለሲሣራ ነገሩት።'),
  ('3dc119a2-3cd2-59f3-ac86-27d72e423789', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 13, 13, 'ሲሣራም ሰረገሎቹን ሁሉ፥ ዘጠኝ መቶ የብረት ሰረገሎች፥ ከእርሱም ጋር የነበሩትን ሕዝቡን ሁሉ ከአሕዛብ አሪሶት ወደ ቂሶን ወንዝ ሰበሰባቸው።'),
  ('80ce188c-3b7a-54f7-a0db-5542ea905bf2', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 14, 14, 'ዲቦራም ባርቅን፥ “እግዚአብሔር ሲሣራን በእጅህ አሳልፎ የሚሰጥበት ቀን ዛሬ ነውና ተነሣ፤ እነሆ፥ እግዚአብሔር በፊትህ ይሄዳል” አለችው። ባርቅም ዐሥር ሺህ ሰዎች ተከትለውት ከታቦር ተራራ ወረደ።'),
  ('4360d13a-c4ad-55d4-af2d-20e12ad218ce', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 15, 15, 'እግዚአብሔርም ሲሣራን፥ ሰረገሎቹንም ሁሉ፥ ሠራዊቱንም ሁሉ ከባርቅ ፊት በሰይፍ ስለት አስደነገጣቸው፤ ሲሣራም ከሰረገላው ወርዶ በእግሩ ሸሸ።'),
  ('dff30d27-6131-5fff-a71b-cd57d63fe7eb', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 16, 16, 'ባርቅም ሰረገሎችንና ሠራዊቱን እስከ አሕዛብ አሪሶት ድረስ አባረረ፤ የሲሣራም ሠራዊት ሁሉ በሰይፍ ስለት ወደቀ፤ አንድ እንኳ አልቀረም።'),
  ('8bcd8414-eec0-5b7f-a0f7-1451a338bfb8', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 17, 17, 'ሲሣራም ወደ ጓደኛው ወደ ቄናዊው ወደ ሔቤር ሚስት ወደ ኢያዔል ድንኳን በእግሩ ሸሸ፤ በአሶር ንጉሥ በኢያቢንና በቄናዊው በሔቤር ቤት መካከል ሰላም ነበርና።'),
  ('ba0e55cd-89d4-5cff-a8d0-a2b06297a865', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 18, 18, 'ኢያዔልም ሲሣራን ለመቀበል ወጥታ፥ “ግባ፥ ጌታዬ ሆይ፥ ወደ እኔ ግባ፤ አትፍራም” አለችው። ወደ እርስዋም ወደ ድንኳንዋ ገባ፤ በምንጣፍም ሸፈነችው።'),
  ('c33ec3e7-1143-5d76-a234-40e94d364033', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 19, 19, 'ሲሣራም፥ “ጠምቶኛልና እባክሽ የምጠጣው ጥቂት ውኃ ስጪኝ” አላት፤ እርስዋም የወተቱን ዕቃ ፈትታ አጠጣችው፤ ፊቱንም ሸፈነችው።'),
  ('e7918537-e229-5761-a5c4-6da43114de8a', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 20, 20, 'እርሱም፥ “ከድንኳኑ ደጃፍ ቁሚ፤ ሰውም መጥቶ፦ ‘በዚህ ሰው አለን?’ ብሎ ቢጠይቅሽ አንቺ፦ ‘የለም’ ትዪዋለሽ” አላት።'),
  ('bdf3a1ce-a66f-5d07-a61a-54ac22382f20', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 21, 21, 'የሔቤርም ሚስት ኢያዔል የድንኳኑን ካስማ ወሰደች፤ በሁለተኛ እጅዋም መዶሻ ያዘች፤ ቀስ ብላም ወደ እርሱ ቀረበች፤ በጆሮ ግንዱም ካስማውን ቸነከረችበት፤ እርሱም ደክሞ አንቀላፍቶ ነበርና ካስማው ወደ መሬት ጠለቀ፤ እርሱም ከእግርዋ በታች ተንፈራፈረ፤ ተዘርሮም ሞተ።'),
  ('82195a19-ebf9-5b0e-abb6-ae1b45648403', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 22, 22, 'እነሆም፥ ባርቅ ሲሣራን ሲያባርር ኢያዔል ልትገናኘው ወጥታ፥ “ና፤ የምትሻውን ሰው አሳይሃለሁ” አለችው። ወደ እርስዋም ገባ፤ እነሆም፥ ሲሣራን ወድቆ፥ ሞቶም አገኘው፤ ካስማውም በጆሮ ግንዱ ውስጥ ነበረ።'),
  ('038bf2d5-c6d4-5472-a320-b6b1b0c4b6f5', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 23, 23, 'በዚያም ቀን እግዚአብሔር የከነዓንን ንጉሥ ኢያቢንን በእስራኤል ልጆች ፊት አዋረደው።'),
  ('a9498842-19e5-53b6-a698-67e7ea4a2d59', '7d96c227-c7c8-5fb4-a8e4-1f39cff631ed', '9f240ec9-3919-5a94-afaa-709ff9525597', 24, 24, 'የከነዓንን ንጉሥ ኢያቢንንም እስኪያጠፉ ድረስ በከነዓን ንጉሥ በኢያቢን ላይ የእስራኤል ልጆች እጅ እየበረታች ሄደች።'),
  ('93114211-a8eb-5935-a064-6afa459ed89e', '25803b78-d0e9-5beb-a9cc-fe7646258439', 'bcbcdbcd-7d7f-595a-ae1c-c0c36738cfb8', 1, 1, 'በዚያችም ቀን ዲቦራና የአቢኒሔም ልጅ ባርቅ እንዲህ ብለው ዘመሩ፦'),
  ('55c21d62-cddf-5c03-add1-18d714713827', '499078b9-0f93-5762-a4c8-2d6142eceace', 'cd760cfb-191f-5df4-a1b8-aeb12688d5e5', 1, 1, 'የእስራኤልም ልጆች በእግዚአብሔር ፊት ክፉ ሥራ ሠሩ፤ እግዚአብሔርም በምድያም እጅ ሰባት ዓመት አሳልፎ ሰጣቸው።'),
  ('4f323959-cdab-53be-a851-8e987946fe84', '499078b9-0f93-5762-a4c8-2d6142eceace', 'cd760cfb-191f-5df4-a1b8-aeb12688d5e5', 2, 2, 'የምድያምም እጅ በእስራኤል ላይ ጠነከረች፤ ከምድያምም ፊት የተነሣ የእስራኤል ልጆች በተራሮችና በገደሎች ላይ ጕድጓድና ዋሻ፥ ምሽግም አበጁ።'),
  ('254913b7-db95-5f37-accf-91a277c32bf9', '499078b9-0f93-5762-a4c8-2d6142eceace', 'cd760cfb-191f-5df4-a1b8-aeb12688d5e5', 3, 3, 'የእስራኤልም ልጆች ዘር በዘሩ ጊዜ ምድያማውያንና አማሌቃውያን ይዘምቱባቸው ነበር፥ በምሥራቅም የሚኖሩ ልጆች አብረው ይዘምቱባቸው ነበር፤'),
  ('beca9f5f-6566-5c69-a14b-999380533b6b', '499078b9-0f93-5762-a4c8-2d6142eceace', 'cd760cfb-191f-5df4-a1b8-aeb12688d5e5', 4, 4, 'በእነርሱም ላይ ይሰፍሩ ነበር፤ ወደ ጋዛም እስከሚደርሱ የእርሻቸውን ፍሬ ያጠፉ ነበር፤ በእስራኤልም ምድር ለሕይወት የሚሆን ምንም አይተዉም ነበር፤ ከመንጋዎችም በሬ ወይም አህያ ቢሆን አይተዉም ነበር።'),
  ('1055a05a-0e2c-5a27-ac63-1e2736496261', '499078b9-0f93-5762-a4c8-2d6142eceace', 'cd760cfb-191f-5df4-a1b8-aeb12688d5e5', 5, 5, 'እንስሶቻቸውንና ድንኳኖቻቸውን ይዘው በብዛት እንደ አንበጣ ሆነው ይመጡባቸው ነበር፤ ለእነርሱና ለግመሎቻቸው ቍጥር አልነበራቸውም፤ ምድሪቱንም ያጠፏት ዘንድ ይመጡ ነበር።'),
  ('94c2c51a-7a3c-552b-ab07-040433bc5993', '499078b9-0f93-5762-a4c8-2d6142eceace', 'cd760cfb-191f-5df4-a1b8-aeb12688d5e5', 6, 6, 'ከምድያምም ፊት የተነሣ እስራኤል እጅግ ተቸገሩ፤ የእስራኤልም ልጆች ወደ እግዚአብሔር ጮኹ።'),
  ('605ce3d8-5d98-50d2-a04f-c22659a99571', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 1, 7, 'እንዲህም ሆነ፤ የእስራኤል ልጆች በምድያም ምክንያት ወደ እግዚአብሔር በጮኹ ጊዜ፥'),
  ('7b8663ac-2f6d-5cd5-ab1a-b39dac394e60', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 2, 8, 'እግዚአብሔር ወደ እስራኤል ልጆች ነቢይ ላከ፤ እርሱም አለ፥ “የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ እኔ ከግብፅ ምድር አወጣኋችሁ፤ ከባርነትም ቤት አስለቀቅኋችሁ፤'),
  ('0f06176c-04d0-5927-aabe-da3e831203a4', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 3, 9, 'ከግብፃውያንም እጅ ከሚጋፉአችሁም ሁሉ እጅ አዳንኋችሁ፤ ከፊታችሁም አሳደድኋቸው፤ ሀገራቸውንም ሰጠኋችሁ፤'),
  ('5da71533-5167-54b4-a74d-b0124a52635d', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 4, 10, 'እናንተንም፦ እኔ አምላካችሁ እግዚአብሔር ነኝ፤ በምድራቸው የተቀመጣችሁባቸውን የአሞሬዎናውያንን አማልክት አትፍሩ አልኋችሁ። እናንተ ግን ቃሌን አልሰማችሁም።”'),
  ('6b2baa56-10c4-5662-a1f9-72c59e2704c3', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 5, 11, 'የእግዚአብሔርም መልአክ መጥቶ በኤፍራታ ባለችው ለኤዝሪ አባት ለኢዮአስ በነበረችው ዛፍ በታች ተቀመጠ፤ ልጁም ጌዴዎን ከምድያማውያን ለማሸሽ በወይን መጭመቂያው ውስጥ ስንዴ ይወቃ ነበር።'),
  ('10aa5a02-5e0c-59e4-a84c-e8dae5d9494b', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 6, 12, 'የእግዚአብሔርም መልአክ ለእርሱ ተገልጦ፥ “አንተ ጽኑዕ ኀያል ሰው! እግዚአብሔር ከአንተ ጋር ነው” አለው።'),
  ('740675e1-291a-51b0-a306-4cd617e57fbc', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 7, 13, 'ጌዴዎንም፥ “ጌታዬ ሆይ! እሺ፥ እግዚአብሔር ከእኛ ጋር ከሆነ ይህ ነገር ሁሉ ለምን ደረሰብን? አባቶቻችንስ፦ እግዚአብሔር ከግብፅ አውጥቶናል ብለው ይነግሩን የነበረ ተአምራት ወዴት አለ? አሁን ግን እግዚአብሔር ትቶናል፤ በምድያም እጅም አሳልፎ ሰጥቶናል” አለው።'),
  ('a0e31d15-ed34-596d-a013-40bd1d2d2d24', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 8, 14, 'የእግዚአብሔርም መልአክ ወደ እርሱ ተመለከተና፥ “በዚህ በጕልበትህ ሂድ፤ እስራኤልንም ከምድያም እጅ ታድናቸዋለህ፤ እነሆ፥ ልኬሃለሁ” አለው።'),
  ('de47186e-699a-5eb0-a210-c597cdaa4420', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 9, 15, 'እርሱም፥ “ጌታ ሆይ! እሺ፥ እስራኤልን በምን አድናለሁ? ወገኔ በምናሴ ነገድ ዘንድ ጥቂቶች ናቸው፤ እኔም በአባቴ ቤት የሁሉ ታናሽ ነኝ” አለው።'),
  ('163eadf6-3582-545d-a941-7af49fd6cad3', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 10, 16, 'የእግዚአብሔርም መልአክ፥ “እግዚአብሔር ከአንተ ጋር ነው፤ ምድያምንም እንደ አንድ ሰው አድርገህ ታጠፋለህ” አለው።'),
  ('53256ba8-4829-5213-a06c-ab4e1399db1d', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 11, 17, 'ጌዴዎንም፥ “በፊትህ ሞገስን ካገኘሁ፥ የምትናገረኝም አንተ እንደ ሆንህ ምልክት አድርግልኝ፤'),
  ('a1681266-baf8-578e-a9eb-7a9d104e2270', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 12, 18, 'ወደ አንተም እስክመለስ ድረስ፥ መሥዋዕቴንም አምጥቼ እስካቀርብልህ ድረስ፥ እባክህ፥ ከዚህ አትሂድ” አለው። እርሱም፥ “እስክትመለስ ድረስ እቈያለሁ” አለው።'),
  ('d3026570-120f-585a-a5c3-cf2f1a034136', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 13, 19, 'ጌዴዎንም ሄደ፤ የፍየሉንም ጠቦት፥ የኢፍ መስፈሪያም ዱቄት የቂጣ እንጎቻ አዘጋጀ፤ ሥጋውንም በሌማት አኖረ፤ መረቁንም በምንቸት ውስጥ አደረገ፤ ሁሉንም ይዞ በዛፍ በታች አቀረበለት። ሰገደለትም።'),
  ('dfe5fc35-24bc-58f1-ac26-1e760ae1ce20', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 14, 20, 'የእግዚአብሔርም መልአክ፥ “ሥጋውንና የቂጣውን እንጎቻ ወስደህ በዚህ ድንጋይ ላይ አኑር፤ መረቁንም አፍስስ” አለው። እንዲሁም አደረገ።'),
  ('a0c424dd-7a04-52ab-a5b6-5b2e03740ce6', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 15, 21, 'የእግዚአብሔርም መልአክ በእጁ ያለውን በትሩን ዘርግቶ ሥጋዉንና የቂጣዉን እንጎቻ አስነካ፤ እሳትም ከድንጋዩ ውስጥ ወጥታ ሥጋዉንና የቂጣዉን እንጎቻ በላች። የእግዚአብሔርም መልአክ ከዐይኖቹ ተሰወረ።'),
  ('756b54ab-2a12-5953-a601-3c998f7e4f66', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 16, 22, 'ጌዴዎንም የእግዚአብሔር መልአክ እንደ ሆነ ዐወቀ። ጌዴዎንም፥ “አቤቱ! አምላኬ ሆይ! ወዮልኝ፤ የእግዚአብሔርን መልአክ ፊት ለፊት አይቻለሁና” አለ።'),
  ('56a60758-0fc2-5084-a4a1-fed4bb209a80', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 17, 23, 'እግዚአብሔርም፥ “ሰላም ለአንተ ይሁን፤ አትፍራ፤ አትሞትም” አለው።'),
  ('5f5e2446-b759-57b6-a343-7dc1dbd5c5a6', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 18, 24, 'ጌዴዎንም በዚያ ለእግዚአብሔር መሠዊያ ሠራ፤ ስሙንም እስከ ዛሬ ድረስ “የእግዚአብሔር ሰላም” ብሎ ጠራው። እርሱም እስከ ዛሬ ድረስ ለኤዝሪ አባት በሆነችው በኤፍራታ አለ።'),
  ('3331c3d6-3261-5c76-af57-9a22a499be40', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 19, 25, 'እንዲህም ሆነ፤ በዚያች ሌሊት እግዚአብሔር፥ “የአባትህን በሬ፥ ሰባት ዓመት የሆነውን ሁለተኛውን በሬ ውሰድ፤ የአባትህ የሆነውንም የበዓል መሠዊያ አፍርስ፤ በእርሱም ዙሪያ ያለውን የማምለኪያ ዐጸድ ቍረጥ፤'),
  ('ecd19cd8-f57b-5305-ab84-b83e5415ce5a', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 20, 26, 'በዚያም ተራራ አናት ላይ ለአምላክህ ለእግዚአብሔር መሠዊያ አሳምረህ ሥራ፤ ሁለተኛዉንም በሬ ውሰድ፤ በዚያም በቈረጥኸው በማምለኪያ ዐጸዱ እንጨት ላይ የሚቃጠለውን መሥዋዕት አቅርብ” አለው።'),
  ('672d089f-41b4-57b9-a654-7b28fd14d5b5', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 21, 27, 'ጌዴዎንም ከባሪያዎቹ ዐሥራ ሦስት ሰዎችን ወስዶ እግዚአብሔር እንዳለው አደረገ፤ የአባቱንም ቤተ ሰቦች፥ የከተማዉንም ሰዎች ስለፈራ ይህን በቀን ለማድረግ አልቻለም፤ ነገር ግን በሌሊት አደረገው።'),
  ('cd50bd75-120e-5a3a-a781-ebabf959037e', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 22, 28, 'የከተማውም ሰዎች ማልደው ተነሡ፤ እነሆም፥ የበዓል መሠዊያ ፈርሶ፥ በዙሪያውም ያለው የማምለኪያ ዐጸድ ተቈርጦ፥ በተሠራውም መሠዊያ ላይ ሁለተኛው በሬ ተሠውቶ አገኙት።'),
  ('8d850ca8-a912-5a17-aa29-f9cc51dffb9e', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 23, 29, 'እርስ በርሳቸውም፥ “ይህን ነገር ያደረገ ማን ነው?” ተባባሉ። በጠየቁና በመረመሩም ጊዜ፥ “ይህን ነገር ያደረገ የኢዮአስ ልጅ ጌዴዎን ነው” አሉ።'),
  ('b1f7ce20-89fd-5f57-aa2f-8e59c2f50030', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 24, 30, 'የከተማዉም ሰዎች ኢዮአስን፥ “የበዓልን መሠዊያ አፍርሶአልና፥ በዙሪያውም ያለውን የማምለኪያ ዐጸድ ቈርጦአልና ይገደል ዘንድ ልጅህን አምጣ” አሉት።'),
  ('577a1208-cfe4-5005-aea5-119491380476', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 25, 31, 'ኢዮአስም በእርሱ ላይ የተነሡበትን ሁሉ፥ “ለበዓል እናንተ ዛሬ ትበቀሉለታላችሁን? ወይስ የበደለውን ትገድሉለት ዘንድ የምታድኑት እናንተ ናችሁን? እርሱ አምላክ ከሆነስ የበደለው እስከ ነገ ድረስ ይሙት። መሠዊያዉንም ያፈረሰውን እርሱ ይበቀለው” አላቸው።'),
  ('e8f80b9f-e0e9-54fd-aeb7-ba9b6b9de2f7', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 26, 32, 'በዚያች ቀንም መሠዊያዉን አፍርሶአልና በዓል ከእርሱ ጋር ይሟገት ሲል ጌዴዎንን ይሩበኣል ብሎ ጠራው።'),
  ('fd8c7fb7-928b-5306-aa53-c9d73070dbab', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 27, 33, 'ምድያምና አማሌቅም ሁሉ፥ የምሥራቅም ልጆች አንድ ሆነው ተሰበሰቡ፤ ተሻግረውም በኢይዝራኤል ሸለቆ ሰፈሩ።'),
  ('912a423c-63f6-55db-a64f-272812c5e326', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 28, 34, 'ጌዴዎንንም የእግዚአብሔር መንፈስ አጸናው፤ እርሱም ቀንደ መለከቱን ነፋ፤ አብዔዜርም በኋላው ጮኸ።'),
  ('1b9d771e-fb3f-536b-aa5e-930b54562202', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 29, 35, 'ወደ ምናሴም ነገድ ሁሉ መልእክተኞችን ላከ፤ እርሱም ከኋላው ሆኖ ጮኸ፤ መልእክተኞችንም ወደ አሴርና ወደ ዛብሎን ወደ ንፍታሌምም ላከ፤ እነርሱም ሊቀበሉአቸው ወጡ።'),
  ('0c5d82dc-92c7-5274-a89f-393d0901b5c6', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 30, 36, 'ጌዴዎንም እግዚአብሔርን፥ “እንደ ተናገርህ የእስራኤልን ልጆች በእኔ እጅ ታድን እንደ ሆነ፥'),
  ('c9e74bf8-024b-5ffe-a0af-0fee638c5bf3', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 31, 37, 'እነሆ! በዐውድማዉ ላይ የተባዘተ የበግ ጠጕር አኖራለሁ፤ በጠጕሩ ብቻ ላይ ጠል ቢሆን በምድሩም ሁሉ ደረቅ ቢሆን፥ እንደ ተናገርህ የእስራኤልን ልጆች በእኔ እጅ እንደምታድናቸው አውቃለሁ” አለ።'),
  ('7777cccd-7357-5edb-ae8c-9b8c53c52c09', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 32, 38, 'እንዲሁም ሆነ፤ በነጋው ማልዶ ተነሣ፤ ጠጕሩንም ጨመቀው፤ ከጠጕሩም የተጨመቀው ጠል አንድ መንቀል ሙሉ ውኃ ሆነ።'),
  ('3568e470-f1c4-5cbf-a64d-358f3926a52e', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 33, 39, 'ጌዴዎንም እግዚአብሔርን አለው፥ “በቍጣህ አትቈጣኝ፤ ደግሞ አንዲት ነገር ልናገር፤ ጠጕሩ ብቻውን ደረቅ ይሁን፤ በምድሩም ላይ ጠል ይውረድ።”'),
  ('ac675377-aa9f-53f7-a4c1-5844b0b641b2', '499078b9-0f93-5762-a4c8-2d6142eceace', '51bb6722-faf2-5e0b-a839-f326b15c1efe', 34, 40, 'እግዚአብሔርም በዚያች ሌሊት እንዲሁ አደረገ፤ ጠጕሩ ብቻ ደረቅ ሆነ፥ በምድሩም ሁሉ ላይ ጠል ወረደ።'),
  ('fe803689-ab28-5c13-a92d-0ea018cf04d5', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 1, 1, 'ጌዴዎን የተባለውም ይሩበኣል ከእርሱም ጋር የነበሩ ሕዝብ ሁሉ ማልደው ተነሡ፤ በአሮኤድ ምንጭ አጠገብ ሰፈሩ፤ የምድያምም ሰፈር ከእነርሱ ወደ ሰሜን በኩል በሞሬ ኮረብታ አጠገብ በሸለቆው ውስጥ ነበረ።'),
  ('a878d983-c87a-56e6-a953-4d0b810d343e', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 2, 2, 'እግዚአብሔርም ጌዴዎንን፥ “ከአንተ ጋር ያለው ሕዝብ በዝቶአል፤ ስለዚህ እስራኤል፦ እጄ አዳነኝ ብሎ እንዳይታበይብኝ እኔ ምድያምን በእጃቸው አሳልፌ አልሰጣቸውም።”'),
  ('7b72dbc0-aa03-5280-a087-b605c02f36ee', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 3, 3, 'እግዚአብሔርም አሁን እንግዲህ፥ “የፈራ፥ የደነገጠም ከገለዓድ ተራራ ተነሥቶ ይመለስ ብለህ በሕዝቡ ጆሮ አውጅ” አለው። ከሕዝቡም ሃያ ሁለት ሺህ ተመለሱ፤ ዐሥርም ሺህ ቀሩ።'),
  ('9b18b1a9-86a8-5702-ae2e-0641ec035030', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 4, 4, 'እግዚአብሔርም ጌዴዎንን፥ “ሕዝቡ ገና ብዙ ነው፤ ወደ ውኃ አውርዳቸው፤ በዚያም እፈትናቸዋለሁ፤ እኔም፦ ይህ ከአንተ ጋር ይሂድ የምለው እርሱ ከአንተ ጋር ይሄዳል፤ እኔም፦ ይህ ከአንተ ጋር አይሂድ የምለው እርሱ አይሄድም” አለው።'),
  ('0e37b9bc-3568-580a-a684-1d6c24fbf056', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 5, 5, 'ሕዝቡንም ወደ ውኃ አወረደ። እግዚአብሔርም ጌዴዎንን፥ “ውሻ እንደሚጠጣ ውኃ በምላሱ የሚጠጣውን ሁሉ፥ እርሱን ለብቻው አድርገው፤ እንዲሁም ሊጠጣ በጕልበቱ የሚንበረከከውን ሁሉ ለብቻው አድርገው” አለው።'),
  ('4a71fa57-d526-500d-ab56-188ad8a5fdad', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 6, 6, 'በእጃቸውም ውኃ ወደ አፋቸው አድርገው የጠጡት ቍጥር ሦስት መቶ ሆነ፤ የቀሩት ሕዝብ ግን ውኃ ሊጠጡ በጕልበታቸው ተንበረከኩ።'),
  ('5d267c2d-5a0d-5e76-a31a-9afe37e1ec3c', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 7, 7, 'እግዚአብሔርም ጌዴዎንን፥ “በእጃቸው ውኃ በጠጡት በሦስት መቶ ሰዎች አድናችኋለሁ፤ ምድያምንም በእጅህ አሳልፌ እሰጥሃለሁ፤ የቀሩት ሕዝብ ሁሉ ግን ወደ ስፍራቸው ይመለሱ” አለው።'),
  ('5fc209aa-2c07-56b9-aa1f-4491c9c001bf', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 8, 8, 'የሕዝቡንም ስንቅና ቀንደ መለከት በእጃቸው ወሰዱ፤ የቀሩትንም የእስራኤል ሰዎች ሁሉ ወደ ድንኳናቸው ሰደዳቸው፤ ሦስቱን መቶ ሰዎች ግን በእርሱ ዘንድ ጠበቃቸው፤ የምድያምም ሰፈር ከእርሱ በታች በሸለቆው ውስጥ ነበረ።'),
  ('da3ae8ad-c838-5bc9-a960-4a33ca877ec9', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 9, 9, 'በዚያችም ሌሊት እግዚአብሔር፥ “በእጅህ አሳልፌ ሰጥቻቸዋለሁና ተነሥተህ ወደ ሰፈር ውረድ።'),
  ('24173185-6ca1-5f29-a626-8817c1357177', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 10, 10, 'ብቻህንም ለመውረድ ብትፈራ አንተ ከሎሌህ ፋራን ጋር ወደ ሰፈሩ ውረድ፤'),
  ('8f88db3a-5842-5f9c-af98-3ce701206a4a', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 11, 11, 'የሚናገሩትንም አድምጣቸው፤ ከዚያም በኋላ እጆችህ ይበረታሉ፤ ወደ ሰፈርም ትወርዳለህ” አለው። እርሱም ከሎሌው ፋራን ጋር ከሰፈሩ በአንድ ወገን የአምሳ አለቃ ጦር ወደ ሰፈረበት ወረደ።'),
  ('b2529214-1a62-540d-a3f9-4224c9ef92b9', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 12, 12, 'ብዛታቸውም እንደ አንበጣ የሆነ ምድያማውያንና አማሌቃውያን የምሥራቅም ልጆች ሁሉ በሸለቆው ውስጥ ሰፍረው ነበር፤ የግመሎቻቸውም ብዛት ቍጥር እንደሌለው በባሕር ዳር እንዳለ አሸዋ ነበረ።'),
  ('5b7d0e83-f872-55d8-a868-4c1f0f7016d7', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 13, 13, 'ጌዴዎንም በደረሰ ጊዜ አንድ ሰው ሕልምን ለባልንጀራው ሲያጫውት፥ “እነሆ፥ ሕልም አለምሁ፤ እነሆም፥ አንዲት የገብስ እንጎቻ ወደ ምድያም ሰፈር ተንከባልላ ወረደች፤ ወደ ድንኳኑም ደርሳ እስኪወድቅ ድረስ መታችው፤ ገለበጠችውም፤ ድንኳኑም ወደቀ” ይል ነበር።'),
  ('b84a0be5-806d-5132-a774-284260d40d03', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 14, 14, 'ባልንጀራውም መልሶ፥ “ይህ ነገር ከእስራኤል ሰው ከኢዮአስ ልጅ ከጌዴዎን ሰይፍ በቀር ሌላ አይደለም፤ እግዚአብሔር ምድያምንና ሠራዊቱን ሁሉ በእጁ አሳልፎ ሰጥቶአል” አለው።'),
  ('59e673f9-9052-5940-a6a1-887839a08377', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 15, 15, 'ጌዴዎንም ሕልሙንና ትርጓሜዉን በሰማ ጊዜ ለእግዚአብሔር ሰገደ፤ ወደ እስራኤልም ሰፈር ተመልሶ፥ “እግዚአብሔር የምድያምን ሠራዊት በእጃችሁ አሳልፎ ሰጥቶአልና ተነሡ” አለ።'),
  ('968dd1c0-42fb-57f0-aa79-87ffb5f949db', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 16, 16, 'ሦስቱንም መቶ ሰዎች በሦስት ወገን ከፈላቸው፤ በሁሉም እጅ ቀንደ መለከትና ባዶ ማሰሮ፥ በማሰሮዉም ውስጥ ችቦ ሰጣቸው።'),
  ('84d580bc-fa79-5695-a619-3868856b2c77', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 17, 17, 'እርሱም፥ “እኔን ተመልከቱ፤ እንዲሁም አድርጉ፤ እነሆም፥ ወደ ሰፈሩ ዳርቻ በደረስሁ ጊዜ እኔ እንደማደርግ እንዲሁ እናንተ አድርጉ፤'),
  ('3e657279-6488-52b2-a7f1-df2a9ad7238a', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 18, 18, 'እኔ ከእኔም ጋር ያሉት ሁሉ ቀንደ መለከት ስንነፋ፥ እናንተ ደግሞ በሰፈሩ ዙሪያ ሁሉ ቀንደ መለከታችሁን ንፉ፦ ኀይል የእግዚአብሔር፥ ሰይፍ የጌዴዎን በሉ” አላቸው።'),
  ('9446f26b-69fc-582b-aa7c-2f24d995575a', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 19, 19, 'ጌዴዎንም፥ ከእርሱም ጋር የነበሩት መቶ ሰዎች በመካከለኛው ትጋት መጀመሪያ ዘብ ጠባቂዎች ሳይነቁ ወደ ሰፈሩ ዳርቻ መጡ፤ ቀንደ መለከቶችንም ነፉ፤ በእጃቸውም የነበሩትን ማሰሮዎች ሰባበሩ፤'),
  ('cd046383-f087-5b51-a632-a9637705818b', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 20, 20, 'ሦስቱም ወገኖች ቀንደ መለከቶችን ነፉ፤ ማሰሮዎችንም ሰበሩ፤ በግራ እጃቸውም ችቦዎችን፥ በቀኝ እጃቸውም ቀንደ መለከቶችን ይዘው እየነፉ፥ “የእግዚአብሔርና የጌዴዎን ሰይፍ” ብለው ጮኹ።'),
  ('57ba6f6b-282a-5415-aacd-0b2cda66bbe2', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 21, 21, 'ሁሉም በየቦታው፥ በሰፈሩ ዙሪያ ቆመ፤ ሠራዊቱም ሁሉ ደንግጠው ሸሹ።'),
  ('f089820f-fd40-559f-a02b-62424631f223', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 22, 22, 'ሦስቱንም መቶ ቀንደ መለከቶችን ነፉ፤ እግዚአብሔርም የሰውን ሁሉ ሰይፍ በባልንጀራዉና በሠራዊቱ ሁሉ ላይ አደረገ፤ ሠራዊቱም በጽሬራ በኩል እስከ ቤትሲጣ ጋራጋታ ድረስ በጣባት አጠገብ እስካለው እስከ አቤልሜሁላ ዳርቻ ድረስ ሸሸ።'),
  ('5d66bf6e-355e-5b2a-ab09-5cdacd344b03', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 23, 23, 'የእስራኤልም ሰዎች ከንፍታሌምና ከአሴር፥ ከምናሴም ሁሉ ተሰብስበው ምድያምን አሳደዱ።'),
  ('de29f692-736d-590f-af42-a68ef203cafc', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 24, 24, 'ጌዴዎንም፥ “ምድያማውያንን ለመግጠም ውረዱ፥ እስከ ቤትባራም ድረስ ያለውን ውኃ፥ ዮርዳኖስንም፥ ያዙባቸው” ብሎ መልእክተኞችን በኤፍሬም ወዳለው ተራራማ ሀገር ሁሉ ላከ። የኤፍሬምም ሰዎች ሁሉ ተሰብስበው እስከ ቤትባራ ድረስ ውኃውን፥ ዮርዳኖስንም ቀድመው ያዙ።'),
  ('4a7e5529-3bbb-5ec4-aa4c-16b59f431f8a', '8062d7ab-7aa8-5d50-a290-7df0a6044226', '81b3afd7-09c4-541a-aebf-f2bd2d7339e1', 25, 25, 'የምድያምን ሁለቱን አለቆች ሔሬብንና ዜብን ያዙ፤ ሔሬብንም በሱርኤራብ ገደሉት፥ ዜብንም በኢያፌቅ ገደሉት፤ የምድያምንም ሰዎች አሳደዱ፤ የሔሬብንና የዜብንም ራስ ይዘው ወደ ዮርዳኖስ ማዶ ወደ ጌዴዎን አመጡ።'),
  ('f58c5492-93b8-5228-a7ff-0970ba50eab2', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 1, 1, 'የኤፍሬም ሰዎችም፥ “ይህ ያደረግህብን ምንድን ነው? ምድያምን ለመዋጋት በወጣህ ጊዜ ለምን አልጠራኸንም?” አሉት። ጽኑ ጥልም ተጣሉት።'),
  ('113ee20e-335e-50e3-af6a-41f0536119ec', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 2, 2, 'እርሱም፥ “እኔ ዛሬ እናንተ እንዳደረጋችሁት ምን አደረግሁ? የኤፍሬም ወይን ቃርሚያ ከአቢዔዜር ወይን መከር አይሻልምን?'),
  ('1f130f58-6626-5d79-ac25-b95db42b8280', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 3, 3, 'እግዚአብሔር የምድያምን አለቆች ሔሬብንና ዜብን በእጃችሁ አሳልፎ ሰጥቶአቸዋል እናንተ ያደረጋችሁትን የሚመስል እኔ ምን ማድረግ እችል ኖርአል?” አላቸው። ከዚህ በኋላ ተዉት፤ ይህን ቃል በተናገራቸውም ጊዜ መንፈሳቸው ዐረፈች።'),
  ('27cfd581-a8c5-5fc9-afc5-a5b929668a01', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 4, 4, 'ጌዴዎንም ወደ ዮርዳኖስ መጥቶ ተሻገረ፤ ከእርሱም ጋር ያሉት ሦስት መቶ ሰዎች ተሻገሩ፤ ምንም እንኳ ቢራቡም ያሳድዱ ነበር።'),
  ('1dac4e95-6157-506a-a337-fe116ac91a42', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 5, 5, 'የሱኮትንም ሰዎች፥ “ተርበዋልና እኔን ለተከተሉ ሰዎች እባካችሁ እህል ስጡአቸው፤ እኔም የምድያምን ነገሥታት ዛብሄልንና ስልማናን አሳድዳለሁ” አላቸው።'),
  ('4c9414dc-b204-56a3-a88b-6662b399548c', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 6, 6, 'የሱኮትም አለቆች፥ “እኛ ለሠራዊትህ እህል እንድንሰጥ የዛብሄልና የስልማና እጅ አሁን በእጅህ ነውን?” አሉ።'),
  ('a5c8a87c-e7ad-5dcc-a630-a3425798ca04', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 7, 7, 'ጌዴዎንም፥ “እግዚአብሔር ዛብሄልንና ስልማናን በእጄ አሳልፎ ቢሰጠኝ እኔ በምድረ በዳ እሾህና በኩርንችት ሥጋችሁን እገርፋለሁ” አለ።'),
  ('27621061-e005-5efd-ae66-c3b718f1faed', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 8, 8, 'ከዚያም ወደ ፋኑሄል ወጣ፤ ለፋኑሄልም ሰዎች እንዲሁ አላቸው፤ የፋኑሄልም ሰዎች የሱኮት ሰዎች እንደ መለሱ መለሱለት።'),
  ('75c3bc24-e7f8-5f50-ac51-9de89cb0e341', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 9, 9, 'እርሱም የፋኑሄልን ሰዎች፥ “በደኅና በተመለስሁ ጊዜ ይህን ግንብ አፈርሰዋለሁ” ብሎ ተናገራቸው።'),
  ('8f32f2ce-915c-5471-a5c6-5617cb304d5e', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 10, 10, 'ዛብሄልና ስልማናም ከሠራዊቶቻቸው ጋር በቀርቀር ነበሩ፤ ሰይፍ የሚመዝዙ መቶ ሃያ ሺህ ሰዎች ወድቀው ነበርና ከምሥራቅ ሰዎች ሠራዊት ሁሉ የቀሩ ዐሥራ አምስት ሺህ ያህል ሰዎች ነበሩ።'),
  ('2f1fdb74-8674-5faa-a72d-78ccd76f09cb', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 11, 11, 'ጌዴዎንም በድንኳን የሚኖሩ ሰዎች ባሉበት መንገድ በኖቤትና በዮግቤል በምሥራቅ በኩል ወጣ፤ ሠራዊቱም ተዘልሎ ሳለ አጠፋቸው።'),
  ('f48637db-ba68-53a0-af0a-29289a97b139', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 12, 12, 'ዛብሄልና ስልማናም ሸሹ፤ እርሱም አሳደዳቸው፤ ሁለቱንም የምድያም ነገሥታት ዛብሄልንና ስልማናን ያዘ፤ ጌዴዎንም ሠራዊቱን ሁሉ አጠፋ።'),
  ('0ad9bffd-30ae-50db-a884-311025e8bd3c', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 13, 13, 'የኢዮአስ ልጅ ጌዴዎንም ከአሬስ ዳገት ከጦርነት ተመለሰ።'),
  ('f6000476-7e8d-540d-a9e1-dd5e4c1e790e', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 14, 14, 'ከሱኮትም ሰዎች አንድ ብላቴና ይዞ መረመረው፤ እርሱም ሰባ ሰባቱን የሱኮትን አለቆችና ሽማግሌዎችን አስቈጠራቸው።'),
  ('bdc444ca-a458-56c9-abf2-919b6e85d3d5', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 15, 15, 'ጌዴዎንም ወደ ሱኮት አለቆች መጥቶ፥ “ለደከሙት ሰዎችህ እህል እንሰጥ ዘንድ የዛብሄልና የስልማና እጅ አሁን በእጅህ ነውን? ብላችሁ የተላገዳችሁብኝ፥ ዛብሄልና ስልማና እነሆ፥” አለ።'),
  ('b295837f-74c0-51fe-ad4a-4708f7a70854', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 16, 16, 'የከተማዪቱንም ሽማግሌዎችና አለቆች ያዘ፥ የምድረ በዳንም እሾህና ኩርንችት ወስዶ የሱኮትን ሰዎች ገረፋቸው።'),
  ('aff7f0c6-dc25-5ef2-af08-72055782e986', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 17, 17, 'የፋኑሄልንም ግንብ አፈረሰ፤ የከተማዪቱንም ሰዎች ገደላቸው።'),
  ('2ca76a7e-9675-5ae4-aa4d-83598a72f1c2', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 18, 18, 'ዛብሄልንና ስልማናን፥ “በታቦር የገደላችኋቸው ሰዎች እንዴት ያሉ ነበሩ?” አላቸው፤ እነርሱም፥ “እንዳንተ ያሉ ነበሩ፤ አንተንም ይመስሉ ነበር፤ መልካቸውም እንደ ነገሥት ልጆች መልክ ነበረ” ብለው መለሱለት።'),
  ('31ce9612-965d-5657-aefe-8b8ba7cde906', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 19, 19, 'ጌዴዎንም፥ “የእናቴ ልጆች ወንድሞቼ ነበሩ፤ አድናችኋቸው ቢሆን ኖሮ፥ ሕያው እግዚአብሔርን! እኔ አልገድላችሁም ነበር” አለ።'),
  ('30dfb8df-86c6-5359-a47a-0403add2d630', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 20, 20, 'በኵሩንም ዮቶርን፥ “ተነሥተህ ግደላቸው” አለው፤ ብላቴናው ግን ገና ትንሽ ነበረና ስለ ፈራ ሰይፉን አልመዘዘም።'),
  ('7e160ff0-0f56-59db-aee1-f5feb741126c', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 21, 21, 'ዛብሄልና ስልማናም፥ “ኀይልህ እንደ ጐልማሳ ኀይል ነውና አንተ ተነሥተህ ውደቅብን” አሉት። ጌዴዎንም ተነሥቶ ዛብሄልንና ስልማናን ገደለ፤ በግመሎቻቸውም አንገት የነበሩትን ሥሉሴዎች ማረከ።'),
  ('2cd2b53b-4d2c-5dc8-a16b-6b620664c506', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 22, 22, 'የእስራኤልም ሰዎች ጌዴዎንን፥ “ከምድያም እጅ አድነኸናልና አንተ፥ ልጅህም፥ የልጅ ልጅህም ደግሞ ግዙን” አሉት።'),
  ('bc98bfe4-542b-5bda-a680-5e7c90340af4', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 23, 23, 'ጌዴዎንም፥ “እኔ አልገዛችሁም፤ ልጄም አይገዛችሁም፤ እግዚአብሔር ይገዛችኋል እንጂ” አላቸው።'),
  ('e658e420-195e-5a65-a3ef-8f50334b9fbe', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 24, 24, 'እስማኤላውያንም ስለ ነበሩ የወርቅ ጕትቻ ነበራቸውና ጌዴዎን፥ “ሁላችሁም ከምርኮአችሁ ጕትቻችሁን እንድትሰጡኝ እለምናችኋለሁ” አላቸው።'),
  ('2ba21ae4-971a-5e10-a69d-f1fb917a8851', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 25, 25, 'እነርሱም፥ “መስጠትን ፈቅደን እንሰጥሃለን” ብለው መለሱለት። መጐናጸፊያም አነጠፉ፤ ሰውም ሁሉ የምርኮውን ጕትቻ በዚያ ላይ ጣለ።'),
  ('b45407f5-6d32-595e-a564-8bba5599236c', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 26, 26, 'የለመነውም የወርቅ ጕትቻ ሚዛኑ ከአምባሩ፥ ከድሪውም፥ የምድያምም ነገሥታት ከለበሱት ከቀዩ ቀሚስ፥ በግመሎቻቸውም አንገት ከነበሩት ሥሉሴዎች ሌላ ሺህ ሰባት መቶ ሰቅለ ወርቅ ነበረ።'),
  ('ee6028c3-b00d-535a-ae9f-2a92cefda027', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 27, 27, 'ጌዴዎንም ምስል አድርጎ ሠራው፤ በከተማውም በኤፍራታ አኖረው፤ እስራኤልም ሁሉ ተከትሎ አመነዘረበት፤ ለጌዴዎንና ለቤቱም ወጥመድ ሆነ።'),
  ('84948db8-1c8c-5ed6-add8-f0f46266620b', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8a7a84e3-a26c-5812-a014-37622dade727', 28, 28, 'ምድያምም በእስራኤል ልጆች ተዋረዱ፤ ራሳቸውንም ዳግመኛ አላነሡም፤ በጌዴዎንም ዕድሜ ምድሪቱ አርባ ዓመት ዐረፈች።'),
  ('1e43c066-1f29-55df-a574-0bcf491d2209', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8544e26f-d3e7-5235-a4b7-b5bb48f23377', 1, 29, 'የኢዮአስም ልጅ ይሩበኣል ሄዶ በቤቱ ተቀመጠ።'),
  ('d887c386-11b2-57a4-aca2-53e5fd6faf45', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8544e26f-d3e7-5235-a4b7-b5bb48f23377', 2, 30, 'ለጌዴዎንም ብዙ ሚስቶች ነበሩትና ከአብራኩ የወጡ ሰባ ልጆች ነበሩት።'),
  ('38a5afe4-4218-52d6-a898-8549f45ffd06', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8544e26f-d3e7-5235-a4b7-b5bb48f23377', 3, 31, 'በሴኬምም የነበረችው ዕቅብቱ ወንድ ልጅ ወለደችለት፤ ስሙንም አቤሜሌክ ብሎ ጠራው።'),
  ('e2181f7c-7ea3-5f2e-a110-24fc503ef9b1', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8544e26f-d3e7-5235-a4b7-b5bb48f23377', 4, 32, 'የኢዮአስም ልጅ ጌዴዎን በመልካም ሽምግልና ሞተ፤ በአብያዜራውያንም ከተማ በኤፍራታ በነበረችው በአባቱ በኢዮአስ መቃብር ተቀበረ።'),
  ('6f238f7c-c1db-5f4b-a132-0ee8bcd4531c', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8544e26f-d3e7-5235-a4b7-b5bb48f23377', 5, 33, 'እንዲህም ሆነ፤ ጌዴዎን ከሞተ በኋላ የእስራኤል ልጆች ተመለሱ፤ በዓሊምንም ተከትለው አመነዘሩ፤ በዓሊምም አምላክ ይሆናቸው ዘንድ ከእርሱ ጋር ቃል ኪዳን ገቡ።'),
  ('6ec4fc73-5f3f-58cb-acf5-eb5332f7b119', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8544e26f-d3e7-5235-a4b7-b5bb48f23377', 6, 34, 'የእስራኤልም ልጆች በዙሪያቸው ከነበሩት ከጠላቶቻቸው ሁሉ እጅ ያዳናቸውን አምላካቸውን እግዚአብሔርን አላሰቡትም፤'),
  ('2b02302a-768d-5bbb-a6a8-3dcfffe900a1', '371c670b-8c10-5ac6-ab4e-508ff20f190e', '8544e26f-d3e7-5235-a4b7-b5bb48f23377', 7, 35, 'እርሱም ለእስራኤል በጎ ነገርን ሁሉ እንዳደረገ መጠን፥ እነርሱ ይሩበኣል ለተባለው ለጌዴዎን ቤት ወረታ አላደረጉም።'),
  ('2a7c1370-c61b-5bad-aa93-e93ab1101943', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 1, 1, 'የይሩበኣል ልጅ አቤሜሌክም ወደ ሰቂማ ወደ እናቱ ወንድሞች ሄደ፤ ለእነርሱም፥ ለእናቱ አባት ቤተ ሰቦችም ሁሉ እንዲህ ሲል ተናገረ፦'),
  ('f5111972-b752-5c89-adf2-510d5e47d49c', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 2, 2, '“ለሰቂማ ሰዎች ሁሉ፦ ሰባ የሆኑት የይሩበኣል ልጆች ሁሉ ቢገዙአችሁ ወይስ አንድ ሰው ቢገዛችሁ ምን ይሻላችኋል? ብላችሁ ንገሩአቸው፤ ደግሞም እኔ የአጥንታችሁ ፍላጭ፥ የሥጋችሁ ቍራጭ እንደ ሆንሁ አስቡ።”'),
  ('8d16b60e-2002-5fd4-af0d-cf00e616b795', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 3, 3, 'የእናቱም ወንድሞች ይህን ቃል ሁሉ ስለ እርሱ በሰቂማ ሰዎች ሁሉ ጆሮ ተናገሩ፤ እነርሱም፥ “እርሱ ወንድማችን ነው” ብለው ልባቸውን ወደ አቤሜሌክ መለሱት።'),
  ('e08bba94-a329-5ff3-a163-60750861e35d', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 4, 4, 'ከበዓልም ቤት ሰባ ብር ሰጡት፤ በዚያም አቤሜሌክ ወንበዴዎችንና አስደንጋጮችን ቀጠረበት፤ እነርሱም ተከትለውት ሄዱ።'),
  ('c9ad2957-a920-588e-a12e-65b0c6af5a1a', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 5, 5, 'ወደ አባቱም ቤት ወደ ኤፍራታ ገባ፤ ሰባ የሆኑትን የይሩበኣልን ልጆች ወንድሞቹን በአንድ ድንጋይ ላይ ገደላቸው፤ ትንሹ የይሩበኣል ልጅ ኢዮአታም ግን ተሸሽጎ ነበርና ተረፈ።'),
  ('a31db56e-76aa-5180-a59f-13eb4ee2293f', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 6, 6, 'የሰቂማም ሰዎች ሁሉ፥ የመሐሎንም ቤት ሁሉ ተሰበሰቡ፤ ሄደውም በሰቂማ በዐምዱ አጠገብ ባለው የወይራ ዛፍ በታች አቤሜሌክን አነገሡ።'),
  ('2306206d-78fb-5fd9-ac31-f897bff9a898', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 7, 7, 'ይህንም ነገር ለኢዮአታም በነገሩት ጊዜ፥ ሄዶ በገሪዛን ተራራ ራስ ላይ ቆመ፤ ድምፁንም አንሥቶ አለቀሰ፤ እንዲህም አላቸው፥ “የሰቂማ ሰዎች ሆይ! ስሙኝ እግዚአብሔርም ይስማችሁ።'),
  ('7653d06c-518e-5b84-a5ba-f778a3b8b1ea', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 8, 8, 'አንድ ጊዜ ዛፎች በላያቸው ንጉሥ ሊያነግሡ ሄዱ፤ ወይራንም፦ በእኛ ላይ ንገሺልን አሉአት።'),
  ('e1fb6611-f549-541b-a6fe-0e6d9c133270', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 9, 9, 'ወይራዋ ግን፦ እግዚአብሔር ሰዎችን የሚያከብርበትን ቅባቴን ትቼ በዛፎች ላይ ለመንገሥ ልሂድን? አለቻቸው።'),
  ('51aeafad-bd09-53e8-a292-2b2647936b50', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 10, 10, 'ዛፎችም በለሲቱን፦ መጥተሽ በላያችን ንገሺልን አሉአት።'),
  ('f61f12b3-d3e0-569b-aa6f-120cc3bd6b95', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 11, 11, 'በለሷ ግን፦ ጣፋጭነቴንና መልካሙን ፍሬዬን ትቼ በዛፎች ላይ እነግሥ ዘንድ ልሂድን? አለቻቸው።'),
  ('afe0df44-dbfc-5587-a788-359418afa75f', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 12, 12, 'ዛፎችም ሁሉ ወይኑን፦ መጥተህ በላያችን ንገሥ አሉት።'),
  ('db3c463e-40bf-5f77-a354-576844216caa', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 13, 13, 'ወይኑም፦ እግዚአብሔርንና ሰውን ደስ የሚያሰኘውን የወይን ጠጅነቴን ትቼ በዛፎች ላይ እነግሥ ዘንድ ልሂድን? አላቸው።'),
  ('cb132cac-ce76-5095-a304-01bc2bec984d', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 14, 14, 'ዛፎችም ዶግን፦ መጥተሽ በላያችን ንገሺ አሉአት፤'),
  ('36f32202-9776-58ef-a969-c6b895ee18c9', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 15, 15, 'ዶግም ዛፎቹን፦ በእውነት እኔን በእናንተ ላይ ካነገሣችሁኝ እሳት ከዶግ ወጥቶ የሊባኖስን ዝግባ ካልበላው ከጥላዬ በታች ታርፉ ዘንድ ኑ አለቻቸው።'),
  ('25866898-c934-53c1-af31-3031672f70ec', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 16, 16, 'አሁን እንግዲህ አቤሜሌክን በማንገሣችሁ እውነትንና ቅንነትን አድርጋችሁ እንደ ሆነ፥ ለይሩበኣልም፥ ለቤቱም በጎ አድርጋችሁ እንደሆነና እንደ እጁም ዋጋ መጠን ለእርሱ የተገባውን አድርጋችሁ እንደ ሆነ፥'),
  ('6d76843d-0ca8-5724-a43d-875179e9e667', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 17, 17, 'አባቴስ ለእናንተ እንደ ተጋደለ፥ በፊታችሁም ሰውነቱን ለሞት አሳልፎ እንደ ሰጠ፥ ከምድያምም እጅ እንደ አዳናችሁ፥'),
  ('95f593b7-32d6-5264-a088-bf3617460395', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 18, 18, 'እናንተም ዛሬ በአባቴ ቤት ተነሥታችኋል፤ ሰባ የሆኑትን ልጆቹንም በአንድ ድንጋይ ላይ ገድላችኋል፤ ወንድማችሁም ስለሆነ የዕቅብቱን ልጅ አቤሜሌክን በሰቂማ ሰዎች ላይ አንግሣችኋል፥'),
  ('58979c16-1823-50a9-a097-c0f438e671d2', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 19, 19, 'ለይሩበኣልና ለቤቱ እውነትንና ቅንነትን ዛሬ አድርጋችሁ እንደ ሆነ የተባረካችሁ ሁኑ፤ በአቤሜሌክም ደስ ይበላችሁ፤ እርሱም ደግሞ በእናንተ ደስ ይበለው፤'),
  ('98b84542-eb2c-5fab-ade5-f4f409b0c608', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 20, 20, 'እንዲህ ባይሆን ግን ከአቤሜሌክ እሳት ትውጣ፤ የሰቂማንም ሰዎች፥ የመሐሎንንም ቤት ትብላ፤ ያም ባይሆን ከሰቂማ ሰዎች ከመሐሎንም ቤት እሳት ትውጣ፤ አቤሜሌክንም ትብላው።”'),
  ('432e6408-45c3-514c-a130-84e4cde40449', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '5d0fd84e-ad01-5b64-af6b-137accd6a922', 21, 21, 'ኢዮአታምም ሸሽቶ አመለጠ፤ ወንድሙን አቤሜሌክንም ፈርቶ ወደ ብኤር ሄደ፤ በዚያም ተቀመጠ።'),
  ('b8ad0ed8-3616-5d18-a472-bdd0840b8efa', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 1, 22, 'አቤሜሌክም በእስራኤል ላይ ሦስት ዓመት ገዥ ሆነ።'),
  ('76641670-ea5b-5c09-a48f-f80cf32bd434', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 2, 23, 'እግዚአብሔርም በአቤሜሌክና በሰቂማ ሰዎች መካከል ክፉን መንፈስ ሰደደ፤ የሰቂማም ሰዎች የአቤሜሌክን ቤት ከዱት።'),
  ('65e11158-c5b1-5e38-a869-fb75e45b763a', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 3, 24, 'ይህም የሆነው፥ በሰባው የይሩበኣል ልጆች ላይ የተደረገው ዐመፅ እንዲመጣ፥ ደማቸውም በገደላቸው በወንድማቸው በአቤሜሌክ ላይ፥ ወንድሞቹንም እንዲገድል እጆቹን ባጸኑአቸው በሰቂማ ሰዎች ላይ እንዲሆን ነው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('33c6c2f1-3e05-5f0b-a51a-197d3e7ef10f', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 4, 25, 'የሰቂማም ሰዎች በተራሮች ራስ ላይ ድብቅ ጦር አደረጉ፤ መንገድ ተላላፊዎችንም ሁሉ ይዘርፉ ነበር፤ ለአቤሜሌክም ይህን አወሩለት።'),
  ('0c18a142-93d8-532e-a6fa-baf2feb9ea07', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 5, 26, 'የአቤድም ልጅ ገዓል ከወንድሞቹ ጋር መጣ፤ የሰቂማ ሰዎችም ከእርሱ ጋር ተባበሩ።'),
  ('ba146411-2462-5c44-a390-798b7450735a', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 6, 27, 'ወደ እርሻውም ወጡ፤ ወይናቸውንም ለቀሙ፤ ጠመቁትም፤ የደስታም በዓል አደረጉ፤ ወደ አምላካቸውም ቤት ገቡ፤ በሉም፤ ጠጡም፤ አቤሜሌክንም ረገሙት።'),
  ('4d3bff50-a3e2-543b-a275-470c2b03e69c', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 7, 28, 'የአቤድም ልጅ ገዓል፥ “አቤሜሌክ ማን ነው? እንገዛለትስ ዘንድ የሴኬም ልጅ ማን ነው? እርሱ የይሩበኣል ልጅ አይደለምን? ዜቡልስ የእርሱ ጠባቂ አይደለምን? ከሴኬም አባት ከኤሞር ሰዎች ጋርስ አገልጋዩ አይደለምን? ስለምንስ ለዚህ እንገዛለን?'),
  ('893c4051-73f9-5c75-a76f-0d5dfd0f33b9', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 8, 29, 'ይህ ሕዝብ ከእጄ በታች ቢሆን ኖሮ አቤሜሌክን አሳድደው ነበር” አለ። አቤሜሌክንም፥ “ሠራዊትህን አብዝተህ ና፤ ውጣ” አለው።'),
  ('ab523f3c-e6d3-5dba-a5eb-8b7863f2b2ff', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 9, 30, 'የከተማዪቱ ገዥ ዜቡልም የአቤድን ልጅ የገዓልን ቃል በሰማ ጊዜ እጅግ ተቈጣ።'),
  ('b0f5bd54-cb73-52f3-aef4-3e17bacdb1bc', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 10, 31, 'እንዲህም ብሎ ወደ አቤሜሌክ ከእጅ መንሻ ጋር መልእክተኞችን ላከ፥ “እነሆ፥ የአቤድ ልጅ ገዓልና ወንድሞቹ ወደ ሰቂማ መጥተዋል፤ እነሆም፥ በአንተ ምክንያት ከተማዪቱን ይወጓታል።'),
  ('2437a0db-56c3-5b75-a7a7-694ce8240457', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 11, 32, 'አሁንም አንተና ከአንተ ጋር ያሉት ሕዝብ በሌሊት ተነሡ፤ በሜዳም ሸምቁ፤'),
  ('40c546ed-63a5-5ea9-ad1c-a1516fa3d9b8', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 12, 33, 'ነገም ፀሐይ በወጣች ጊዜ ማልደህ ተነሣ፤ ከተማዪቱንም ክበባት፤ እነሆም፥ እርሱና ከእርሱ ጋር ያሉት ሕዝብ በአንተ ላይ በወጡ ጊዜ እጅህ እንዳገኘች አድርግበት።”'),
  ('1ba76df1-08d5-52cd-a928-91ec7bafd726', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 13, 34, 'አቤሜሌክና ከእርሱም ጋር ያሉት ሕዝብ ሁሉ በሌሊት መጡ። ሰቂማንም በአራት ወገን ከበቡአት።'),
  ('f1f0bfcc-3b32-57f9-ad30-c41a3810dce9', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 14, 35, 'በነጋም ጊዜ የአቤድ ልጅ ገዓል ወጥቶ በከተማዪቱ መግቢያ በር ቆመ፤ አቤሜሌክና ከእርሱ ጋር ያሉት ሕዝብም ከሸመቁበት ስፍራ ተነሡ።'),
  ('bb3a8a83-50c6-5615-a71c-104c43c9fcfb', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 15, 36, 'የአቤድ ልጅ ገዓልም ሕዝቡን ባየ ጊዜ ዜቡልን፥ “እነሆ፥ ከተራሮች ራስ ሕዝብ ይወርዳል” አለው። ዜቡልም፥ “ሰዎችን የሚመስለውን የተራሮችን ጥላ ታያለህ” አለው።'),
  ('6337aa33-a80e-5cb9-ac83-b515ad3ed096', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 16, 37, 'ገዓልም ደግሞ፥ “እነሆ፥ ሕዝብ በባሕር በኩል ወደ ምድር መካከል ይወርዳል፤ የአንድም አለቃ ሠራዊት በአድባሩ ዛፍ መንገድ አንጻር ይመጣል” ብሎ ተናገረ።'),
  ('f668d012-fccf-5ba1-a25f-fa43744ac090', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 17, 38, 'ዜቡልም፥ “እንገዛለት ዘንድ አቤሜሌክ ማን ነው? ያልህበት አፍህ አሁን የት አለ? ይህ የናቅኸው ሕዝብ አይደለምን? አሁንም ወጥተህ ከእነርሱ ጋር ተዋጋ” አለው።'),
  ('4b1b79ae-158a-5c10-ad42-ef6bdbce190c', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 18, 39, 'ገዓልም በሰቂማ ሰዎች ፊት ወጣ፤ ከአቤሜሌክም ጋር ተዋጋ።'),
  ('052baf07-f5f7-5ef7-a5f4-98fc68e0c308', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 19, 40, 'አቤሜሌክም አሳደደው፤ በፊቱም ሸሸ፤ እስከ ከተማው በርም አደባባይ ድረስ ብዙዎች ተጐድተው ወደቁ።'),
  ('d70cea83-784b-51e1-a48e-80f47a729c8c', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 20, 41, 'አቤሜሌክም በአሪማ ተቀመጠ፤ ዜቡልም ገዓልንና ወንድሞቹን በሰቂማ እንዳይኖሩ ከለከላቸው።'),
  ('0b067d2e-02ea-5d75-a758-b574b5ce93e2', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 21, 42, 'በነጋውም ሕዝቡ ወደ እርሻ ወጡ፤ ለአቤሜሌክም ነገሩት።'),
  ('cfda7856-2028-5eda-a3a6-6d3b1da7d2fd', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 22, 43, 'ሕዝቡንም ወስዶ በሦስት ወገን ከፈላቸው፤ በሜዳም ሸመቀ፤ ተመለከተም፤ እነሆም፥ ሕዝቡ ከከተማ ወጡ፤ ተነሣባቸውም፤ ገደላቸውም።'),
  ('9d3d1362-da5f-5718-aaf6-348818355d1b', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 23, 44, 'አቤሜሌክም ከእርሱም ጋር ያሉት ሠራዊት በከተማዪቱ መግቢያ በር ሸምቀው ቆሙ። እነዚያ ሁለቱ ሠራዊት ግን ወደ ጫካው ተበትነው አጠፉአቸው።'),
  ('eaef0714-3687-5c2b-aafa-e2c8f1f82237', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 24, 45, 'አቤሜሌክም በዚያ ቀን ሁሉ ከከተማዪቱ ጋር ተዋጋ፤ ከተማዪቱንም ይዞ በእርስዋ የነበሩትን ሕዝብ ገደለ፤ ከተማዪቱንም አፈረሰ፤ ጨውም ዘራባት።'),
  ('0ebea600-6374-5278-a685-4c4d8bacdd8d', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 25, 46, 'በሰቂማም ግንብ ውስጥ የነበሩ ሰዎች ሁሉ ይህን በሰሙ ጊዜ ወደ በዓል ቤት ወደ ምሽጉ ውስጥ ገቡ።'),
  ('7a2e2819-0960-5f28-a2db-c136e0605679', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 26, 47, 'ለአቤሜሌክም በሰቂማ ግንብ ውስጥ ያሉ ሰዎች ሁሉ አንድ ሆነው እንደ ተሰበሰቡ ነገሩት።'),
  ('9d42c23f-edea-59c4-aafc-7a2e9e091f64', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 27, 48, 'አቤሜሌክና ከእርሱ ጋር ያሉትም ሕዝብ ሁሉ ወደ ሄርሞን ተራራ ወጡ፤ አቤሜሌክም በእጁ መጥረቢያ ወስዶ የዛፉን ቅርንጫፍ ቈረጠ፤ አንሥቶም በጫንቃው ላይ ተሸከመው፤ ከእርሱም ጋር ለነበሩት ሕዝብ፥ “እኔ ሳደርግ ያያችሁትን፥ እናንተም ፈጥናችሁ እኔ እንዳደረግሁ አድርጉ” አላቸው።'),
  ('831e9caa-2232-523f-ab5c-9e038089727d', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 28, 49, 'ሕዝቡም ሁሉ እንዲሁ እያንዳንዳቸው የዛፉን ቅርንጫፎች ቈረጡ፤ አቤሜሌክንም ተከትለው በምሽጉ ዙሪያ አኖሩአቸው፤ ምሽጉንም በላያቸው በእሳት አቃጠሉት፤ የሰቂማም ግንብ ሰዎች ሁሉ ደግሞ አንድ ሺህ የሚያህሉ ወንድና ሴት ሞቱ።'),
  ('86a4b8de-210f-54f6-a6ff-51ba30cc1301', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 29, 50, 'አቤሜሌክም ወደ ቴቤስ መጣ።'),
  ('3fec2f77-cb8c-5365-ad2d-ae9ce6974aee', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 30, 51, 'በእርስዋም ተቀመጠ፤ እጅም አደረጋት። በከተማዪቱም ውስጥ ብርቱ ግንብ ነበረ፤ የከተማዪቱም ሰዎች ሁሉ፥ ወንዱና ሴቱ ሁሉ፥ ወደዚያ ሸሹ፤ ደጁንም በኋላቸው ዘጉ፤ ወደ ግንቡም ሰገነት ላይ ወጡ።'),
  ('6056e95c-5f12-51ca-a856-4c700d05c35d', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 31, 52, 'አቤሜሌክም ወደ ግንቡ ሄደ። እነርሱም ተዋጉት። አቤሜሌክም በእሳት ሊያቃጥለው ወደ ግንቡ ደጅ ቀረበ።'),
  ('b17cc419-8134-5780-af61-af04e70d25e8', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 32, 53, 'አንዲትም ሴት በአቤሜሌክ ራስ ላይ የወፍጮ መጅ ጣለችበት፤ አናቱንም ሰበረችው።'),
  ('8faf1202-e996-5360-a254-d9510d54c80c', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 33, 54, 'እርሱም ፈጥኖ ጋሻ ዣግሬውን ጠርቶ፥ “ሴት ገደለችው እንዳይሉ ሰይፍህን መዝዘህ ግደለኝ” አለው፤ ጐልማሳውም ወጋው፤ አቤሜሌክም ሞተ።'),
  ('2a476ed3-6fcf-5c2a-a2b9-ca2c3dd70938', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 34, 55, 'የእስራኤልም ሰዎች አቤሜሌክ እንደ ሞተ ባዩ ጊዜ እያንዳንዱ ወደ ስፍራው ተመለሰ።'),
  ('22de0d0c-456d-5285-a269-461705cfebc5', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 35, 56, 'እንዲሁ ሰባ ወንድሞቹን በመግደል አቤሜሌክ በአባቱ ቤት ላይ ያደረገውን ክፋት እግዚአብሔር መለሰበት።'),
  ('acf5360d-c50d-521c-af91-41475778f310', '86d4e35e-0cb9-5b32-a882-70f14a173cd8', '93df80ec-ccab-5fec-a39d-1fc81e7cd7a4', 36, 57, 'እግዚአብሔርም የሰቂማን ሰዎች ክፋት ሁሉ በራሳቸው ላይ መለሰባቸው፤ የይሩበኣል ልጅ የኢዮአታምም ርግማን ደረሰባቸው።'),
  ('be706cdc-ccf7-5c4b-a6cb-5e038bf1062a', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '447bb83a-db04-5aa4-a78c-ad3eca97a7a5', 1, 1, 'ከአቤሜሌክም በኋላ ከይሳኮር ነገድ የሆነ የአባቱ ወንድም ልጅ የፎሓ ልጅ ቶላ እስራኤልን ለማዳን ተነሣ፤ እርሱም በኤፍሬም ተራራ በሳምር ተቀምጦ ነበር።'),
  ('ac6d647b-5fe3-5e61-a0a2-bec6bbfe751f', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '447bb83a-db04-5aa4-a78c-ad3eca97a7a5', 2, 2, 'እስራኤልንም ሃያ ሦስት ዓመት ገዛ፤ ሞተም፤ በሳምርም ተቀበረ።'),
  ('aa971fcf-6230-50d3-a79b-476a4b32c207', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', 'b4503313-5f4d-51ce-ad7b-6e1327bd34b0', 1, 3, 'ከእርሱም በኋላ ገለዓዳዊዉ ኢያዕር ተነሣ፤ እስራኤልንም ሃያ ሁለት ዓመት ገዛ።'),
  ('34c5802c-7305-5d31-ad52-3a436229c250', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', 'b4503313-5f4d-51ce-ad7b-6e1327bd34b0', 2, 4, 'በሠላሳ ሁለት የአህያ ግልገሎች ይቀመጡ የነበሩ ሠላሳ ሁለት ልጆችም ነበሩት፤ ለእነርሱም እስከ ዛሬ ድረስ የኢያዕር መንደሮች የተባሉ በገለዓድ ምድር ያሉ ሠላሳ ሁለት ከተሞች ነበሩአቸው።'),
  ('23c3ab4d-836b-5eb3-af64-4b4f22891b88', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', 'b4503313-5f4d-51ce-ad7b-6e1327bd34b0', 3, 5, 'ኢያዕርም ሞተ፤ በራሞንም ተቀበረ።'),
  ('7584c210-1629-550c-a919-823a0e533da0', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 1, 6, 'የእስራኤልም ልጆች በእግዚአብሔር ፊት እንደ ገና ክፉ ሥራ ሠሩ፤ በዓሊምንና አስታሮትን፥ የሶርያንም አማልክት፥ የሲዶናንም አማልክት፥ የሞዓብንም አማልክት፥ የአሞንንም ልጆች አማልክት፥ የፍልስጥኤማውያንንም አማልክት አመለኩ፤ እግዚአብሔርንም ተዉ፤ አላመለኩትምም።'),
  ('5e32872b-60f9-5316-ac9d-0e833bb9c8ad', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 2, 7, 'እግዚአብሔርም በእስራኤል ላይ ፈጽሞ ተቈጣ፤ በፍልስጥኤማውያን እጅና በአሞን ልጆች እጅም አሳልፎ ሰጣቸው።'),
  ('a0ac3bbc-ab3b-5c9f-a997-be6a50038ee3', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 3, 8, 'በዚያም ጊዜ የእስራኤልን ልጆች ሥቃይ አበዙባቸው፤ በዮርዳኖስ ማዶ በአሞሬዎናውያን ሀገር በገለዓድ ውስጥ ያሉትን የእስራኤልን ልጆች ሁሉ ዐሥራ ስምንት ዓመት አስጨነቁአቸው።'),
  ('128d9a4d-ae22-58db-a794-246cbc7d390b', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 4, 9, 'የአሞንም ልጆች ከይሁዳ፥ ከብንያምና ከኤፍሬም ቤት ጋር ደግሞ ሊዋጉ ዮርዳኖስን ተሻገሩ፤ እስራኤልም እጅግ ተጨነቁ።'),
  ('e3c9b803-5791-5da6-afed-33150f52aa47', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 5, 10, 'የእስራኤልም ልጆች፥ “አንተን አምላካችንን ትተን በዓሊምን አምልከናልና ኀጢአት ሠርተናል” ብለው ወደ እግዚአብሔር ጮኹ።'),
  ('8b2b2706-af78-5f84-a08f-eb5c58b43d7c', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 6, 11, 'እግዚአብሔርም የእስራኤልን ልጆች አላቸው፥ “ግብፃውያን፥ አሞሬዎናውያንም፥ የአሞንና የሞአብም ልጆች፥ ፍልስጥኤማውያንም፥'),
  ('eb69cf77-8bd4-5324-a595-546c62347610', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 7, 12, 'ሲዶናውያንም፥ ምድያማውያንም፥ አማሌቃውያንም አላስጨነቋችሁምን? ወደ እኔም ጮኻችሁ፤ እኔም ከእጃቸው አዳንኋችሁ።'),
  ('f1cf6b8a-5748-5794-af65-ff6653f20248', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 8, 13, 'እናንተ ግን ተዋችሁኝ፤ ሌሎችንም አማልክት አመለካችሁ፤ ስለዚህም ደግሞ አላድናችሁም።'),
  ('4679695e-85f0-54ca-ab0c-ab7f5e7d2010', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 9, 14, 'ሄዳችሁ ወደ መረጣችኋቸው አማልክት ጩኹ፤ እነርሱም በመከራችሁ ጊዜ ያድኑአችሁ።”'),
  ('8b5932b8-e471-5f01-a902-c4480af5b5ed', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 10, 15, 'የእስራኤልም ልጆች እግዚአብሔርን፥ “እኛ ኀጢአትን ሠርተናል፤ አንተ በፊትህ ደስ የሚያሰኝህን አድርግብን፤ ዛሬ ግን እባክህ አድነን” አሉት።'),
  ('2e4416dd-1ed3-55fa-adce-b056bbebcc19', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 11, 16, 'ሌሎችንም አማልክት ከመካከላቸው አስወገዱ፤ እግዚአብሔርንም ብቻ አመለኩ፤ ደስም አሰኙት፤ የእስራኤልም ልጆች ከሥቃይ የተነሣ አእምሮአቸውን አጥተው ነበር።'),
  ('bdd34299-b945-54ce-aefe-e8181e565395', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 12, 17, 'የአሞንም ልጆች ወጥተው በገለዓድ ሰፈሩ። የእስራኤልም ልጆች ተሰብስበው በመሴፋ ሰፈሩ።'),
  ('c6794213-6488-572b-af64-ff1c6bb01bf6', '0ea491d3-3b28-50b9-afd1-c33a6a2e905e', '6e63a3a0-f5e2-53e1-aa86-4518912dbf09', 13, 18, 'የገለዓድ ሕዝብ አለቆችም እርስ በርሳቸው፥ “ከአሞን ልጆች ጋር መዋጋትን የሚጀምር ማን ነው? እርሱ በገለዓድ ሰዎች ሁሉ ላይ አለቃ ይሆናል” አሉ።'),
  ('ba72efd2-1a50-5c76-a60a-f8cc9433f548', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 1, 1, 'ገለዓዳዊዉም ዮፍታሔ ጽኑዕ ኀያል ሰው የጋለሞታ ሴትም ልጅ ነበረ። ለገለዓድም ዮፍታሔን ወለደችለት።'),
  ('00c9c8df-0644-5757-adcc-5110ee1024db', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 2, 2, 'የገለዓድም ሚስት ወንዶች ልጆችን ወለደችለት፤ ልጆችዋም ባደጉ ጊዜ ዮፍታሔን፥ “የሌላ ሴት ልጅ ነህና በአባታችን ቤት አትወርስም” ብለው አስወጡት።'),
  ('d70be484-1fb5-536d-ab68-7ddad23f766b', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 3, 3, 'ዮፍታሔም ከወንድሞቹ ፊት ሸሽቶ በጦብ ምድር ተቀመጠ፤ ድሆች ሰዎችም ተሰብስበው ዮፍታሔን ተከተሉት።'),
  ('995600ae-9f04-5228-a80a-4d1698bc0726', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 4, 4, 'ከዚያም ወራት በኋላ የአሞን ልጆች እስራኤልን ተዋጉአቸው።'),
  ('a4cfb7ff-fa15-51eb-a68a-c25b7c685fce', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 5, 5, 'የገለዓድ ሽማግሌዎችም ዮፍታሔን ከጦብ ምድር ለማምጣት ሄዱ።'),
  ('78833594-e885-5e62-a20d-1bf0f528ef26', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 6, 6, 'ዮፍታሔንም፥ “ና፥ ከአሞን ልጆች ጋር እንድንዋጋ መስፍን ሁነን” አሉት።'),
  ('36c5ec8b-804e-5958-adbc-6bab8b79191e', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 7, 7, 'ዮፍታሔም የገለዓድን ሽማግሌዎች፥ “የጠላችሁኝ፥ ከአባቴም ቤት ያስወጣችሁኝ እናንተ አይደላችሁምን? አሁን በተጨነቃችሁ ጊዜ ለምን ወደ እኔ መጣችሁ?” አላቸው።'),
  ('03295ca7-e454-525c-a35f-1bdbaa285a1d', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 8, 8, 'የገለዓድም ሽማግሌዎች ዮፍታሔን፥ “እንዲህ አይደለም፤ ከእኛ ጋር እንድትወጣ፥ ከአሞንም ልጆች ጋር እንድቷጋ፥ ስለዚህ አሁን ወደ አንተ ተመልሰን መጣን፤ በገለዓድም ሰዎች ሁሉ ላይ አለቃችን ትሆናለህ” አሉት።'),
  ('2360c396-228f-5865-addc-d608d944964e', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 9, 9, 'ዮፍታሔም የገለዓድን ሽማግሌዎች፥ “ከአሞን ልጆች ጋር ለመዋጋት ብትወስዱኝ፥ እግዚአብሔርም በእጄ አሳልፎ ቢሰጣቸው፥ እኔ አለቃችሁ እሆናለሁን?” አላቸው።'),
  ('ff1b6c67-5652-508d-a049-bbef80d86f7d', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 10, 10, 'የገለዓድም ሽማግሌዎች ዮፍታሔን፥ “እግዚአብሔር በመካከላችን ምስክር ይሁን፤ በርግጥ እንደ ቃልህ እናደርጋለን” አሉት።'),
  ('1b5c0f3d-d1c4-5e85-a233-aaa1704b1381', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 11, 11, 'ዮፍታሔም ከገለዓድ ሽማግሌዎች ጋር ሄደ፤ ሕዝቡም መስፍን ይሆናቸው ዘንድ በላያቸው አለቃ አድርገው ሾሙት፤ ዮፍታሔም ቃሉን ሁሉ በእግዚአብሔር ፊት በመሴፋ ተናገረ።'),
  ('db749dcf-b735-5b34-af3c-5dc428f8c01d', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 12, 12, 'ዮፍታሔም ወደ አሞን ልጆች ንጉሥ፥ “ሀገሬን ለመውጋት ወደ እኔ የምትመጣ አንተ ከእኔ ጋር ምን አለህ?” ብሎ መልእክተኞችን ላከ።'),
  ('a87405c6-63df-50e8-a0a8-5af2a783641c', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 13, 13, 'የአሞንም ልጆች ንጉሥ የዮፍታሔን መልእክተኞች፥ “እስራኤል ከግብፅ በወጣ ጊዜ ከአርኖን ጀምሮ እስከ ያቦቅና እስከ ዮርዳኖስ ድረስ ምድሬን ስለ ወሰደ ነው፤ አሁንም በሰላም መልሱልኝ” ብሎ መለሰላቸው።'),
  ('3592685a-8291-5785-a4ba-d3fa3013b076', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 14, 14, 'ዮፍታሔም የላካቸው ወደ ዮፍታሔ ተመለሱ፤ ዮፍታሔም ወደ አሞን ልጆች ንጉሥ መልእክተኞችን እንደ ገና ላከ፤ እንዲህም አለው፦'),
  ('32c8043a-9c41-5f90-a043-742e451372f9', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 15, 15, 'ዮፍታሔ እንዲህ ይላል፥ “እስራኤል ከግብፅ በወጡ ጊዜ የሞዓብን ምድር፥ የአሞንንም ልጆች ምድር አልወሰዱም፤'),
  ('984d3b5e-ef62-5090-af81-6921d907040c', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 16, 16, 'ነገር ግን እስራኤል በምድረ በዳ እስከ ኤርትራ ባሕር ሄዱ፤ ወደ ቃዴስም ደረሱ፤'),
  ('7dac62c9-8ec0-578c-a4e5-3d49deb5bf6d', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 17, 17, 'እስራኤል ወደ ኤዶምያስ ንጉሥ፦ ‘በምድርህ እንዳልፍ፥ እባክህ፥ ፍቀድልኝ’ ብሎ መልእክተኞችን ላከ፤ የኤዶምያስም ንጉሥ እንቢ አለ። እንዲሁም ወደ ሞዓብ ንጉሥ ላከ፤ እርሱም እንቢ አለ።'),
  ('a11e1fb1-1ad2-570d-ab7e-0999ad96c46f', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 18, 18, 'እስራኤልም በቃዴስ ተቀመጠ። በምድረ በዳም በኩል አለፈ፤ የኤዶምያስንና የሞዓብንም ምድር ዞሩ፤ ከሞዓብ ምድርም በምሥራቅ በኩል መጡ፤ በአርኖንም ማዶ ሰፈሩ፤ አርኖንም የሞዓብ ድንበር ነበረና ወደ ሞዓብ ድንበር አልገቡም።'),
  ('ca3d7d4e-866b-56f4-a7d5-57be6a7d9976', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 19, 19, 'እስራኤልም ወደ አሞራዊው ወደ ሐሴቦን ንጉሥ ወደ ሴዎን መልእክተኞችን ላከ፤ እስራኤልም፦ ‘በምድርህ በኩል ወደ ስፍራችን፥ እባክህ፥ አሳልፈን’ አለው።'),
  ('467e526b-3570-5d3a-a366-160d5f22d1bb', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 20, 20, 'ሴዎንም እስራኤል በድንበሩ እንዲያልፍ እንቢ አለ፤ ነገር ግን ሴዎን ሕዝቡን ሁሉ ሰበሰበ፤ በኢያሴርም ሰፈረ፤ ከእስራኤልም ጋር ተዋጋ።'),
  ('3c7a48da-1402-54cd-ae80-17cbce530469', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 21, 21, 'የእስራኤልም አምላክ እግዚአብሔር ሴዎንንና ሕዝቡን ሁሉ በእስራኤል እጅ አሳልፎ ሰጠ፤ ገደሉአቸውም፤ እስራኤልም በዚያ ምድር ተቀምጠው የነበሩትን የአሞሬዎናውያንን ምድር ሁሉ ወረሱ።'),
  ('4f4c5e32-fa8c-537a-a31c-199715418cfc', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 22, 22, 'ከአርኖንም እስከ ያቦቅ ድረስ፥ ከምድረ በዳውም እስከ ዮርዳኖስ ድረስ የአሞሬዎናውያንን አውራጃ ሁሉ ወረሱ።'),
  ('83e7cf37-c870-5a2f-a4f1-31b43fc4966f', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 23, 23, 'አሁንም የእስራኤል አምላክ እግዚአብሔር ከሕዝቡ ከእስራኤል ፊት አሞሬዎናውያንን አስወገደ፤ አንተም በተራህ ትወርሳለህን?'),
  ('4a5e6ce9-848c-5f94-aa63-36bf12808d7c', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 24, 24, 'አምላክህ ኮሞስ የሚሰጥህን የምትወርስ አይደለህምን? እኛም አምላካችን እግዚአብሔር ከፊታችን ያስወጣቸውን የእነርሱን ምድር የምንወርስ አይደለንምን?'),
  ('e691765f-c22e-5c11-a990-0d665633cf16', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 25, 25, 'ወይስ ዛሬ ከሞዓብ ንጉሥ ከሴፎር ልጅ ከባላቅ አንተ ትሻላለህን? ወይስ እርሱ ከእስራኤል ጋር ተጣላን? ወይስ ተዋጋውን?'),
  ('5ad47bb9-a6a6-51f8-a04c-e58bfc658928', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 26, 26, 'እስራኤልም በሐሴቦንና በመንደሮችዋ፥ በአሮዔርና በመንደሮችዋ፥ በአርኖንም አቅራቢያ ባሉት ከተሞች ሁሉ ሦስት መቶ ዓመት ተቀምጦ በነበረ ጊዜ፥ በዚያ ዘመን ስለ ምን አላዳንሃቸውም ነበር?'),
  ('c8b5fbfa-b35f-5dd7-a41e-7fc29e4a9d60', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 27, 27, 'እኔ አልበደልሁህም፤ አንተ ግን ከእኔ ጋር ትዋጋ ዘንድ ክፉ አታድርግብኝ፤ ፈራጁ እግዚአብሔር በእስራኤል ልጆችና በአሞን ልጆች መካከል ዛሬ ይፍረድ።”'),
  ('de7cf98d-ce4c-5f84-a74e-a0896dbbec45', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 28, 28, 'ነገር ግን ዮፍታሔ የላከበትን ቃል የአሞን ልጆች ንጉሥ አልሰማም፤ እንቢም አላቸው።'),
  ('78bfeb3a-378e-5d5e-ad20-205fd9494b99', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 29, 29, 'የእግዚአብሔርም መንፈስ በዮፍታሔ ላይ መጣ፤ እርሱም የምናሴ ዕጣ ከምትሆን ከገለዓድ ምድርና ከገለዓድ መሴፋ፥ ወደ አሞን ልጆች ማዶ ተሻገረ።'),
  ('3e890fd9-3034-5c38-a635-1bb9c3d9b7ef', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 30, 30, 'ዮፍታሔም፥ “በእውነት የአሞንን ልጆች በእጄ አሳልፈህ ብትሰጠኝ፥'),
  ('2cd91309-8592-51c0-a065-0610cad11478', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 31, 31, 'ከአሞን ልጆች ዘንድ በደኅና በተመለስሁ ጊዜ፥ ከቤቴ ደጅ ወጥቶ የሚቀበለኝን ለእግዚአብሔር መሥዋዕት አደርገዋለሁ” ብሎ ለእግዚአብሔር ስእለት ተሳለ።'),
  ('a7923604-1d21-5841-a058-4e58de0c6fca', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 32, 32, 'ዮፍታሔም ሊዋጋቸው ወደ አሞን ልጆች ተሻገረ፤ እግዚአብሔርም በእጁ አሳልፎ ሰጣቸው።'),
  ('f53af215-aac7-54ff-a7bd-cf82647c278b', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '72788611-6023-5d73-a594-25328ad13770', 33, 33, 'ከአሮዔርም እስከ ሚኒትና እስከ አቤልክራሚም ድረስ ሃያ ከተሞችን በታላቅ ሰልፍ አጠፋቸው። የአሞንም ልጆች በእስራኤል ልጆች ፊት ተዋረዱ።'),
  ('26336a76-d8dc-5859-a66c-2c63a9542145', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '2e243ee0-52d3-5598-a67e-f9ffa3c11d42', 1, 34, 'ዮፍታሔም ወደ መሴፋ ወደ ቤቱ ተመለሰ፤ እነሆም፥ ልጁ ከበሮ ይዛ እየዘፈነች ልትቀበለው ወጣች፤ ለእርሱም የሚወድዳት አንዲት ብቻ ነበረች። ከእርስዋም በቀር ወንድ ወይም ሴት ሌላ ልጅ አልነበረውም።'),
  ('ddf3f4b7-2a4c-5913-a38d-d3fb9f2ba746', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '2e243ee0-52d3-5598-a67e-f9ffa3c11d42', 2, 35, 'እርስዋንም ባየ ጊዜ ልብሱን ቀድዶ፥ “ወዮልኝ ልጄ ሆይ! ወደ እግዚአብሔር አፌን ከፍቻለሁና፥ ከዚያውም እመለስ ዘንድ አልችልምና አሰናከልሽኝ፤ አስጨነቅሽኝም” አላት።'),
  ('b41dbf08-48c2-577d-a096-93d457148a74', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '2e243ee0-52d3-5598-a67e-f9ffa3c11d42', 3, 36, 'እርስዋም፥ “አባቴ ሆይ፥ አፍህን ወደ እግዚአብሔር ከከፈትህ፥ እግዚአብሔር በጠላቶችህ በአሞን ልጆች ላይ ተበቅሎልሃልና በአፍህ እንደ ተናገርህ አድርግብኝ” አለችው።'),
  ('4b684a79-556c-5a51-ab6b-4d1cd22b774b', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '2e243ee0-52d3-5598-a67e-f9ffa3c11d42', 4, 37, 'አባቷንም፥ “ይህ ነገር ይደረግልኝ፤ ከዚህ ሄጄ በተራሮች ላይ እንድወጣና እንድወርድ፥ ከባልንጀሮቼም ጋር ለድንግልናዬ እንዳለቅስ ሁለት ወር አሰናብተኝ” አለችው።'),
  ('a2b16c60-5c3b-53a3-a014-cee37d00d138', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '2e243ee0-52d3-5598-a67e-f9ffa3c11d42', 5, 38, 'እርሱም፥ “ሂጂ” አለ። ሁለት ወርም አሰናበታት፤ ከባልንጀሮችዋም ጋር ሄደች፤ በተራሮችም ላይ ለድንግልናዋ አለቀሰች።'),
  ('7a820c95-1c02-54b6-a53b-18fdf4d72488', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '2e243ee0-52d3-5598-a67e-f9ffa3c11d42', 6, 39, 'ሁለት ወርም ከተፈጸመ በኋላ ወደ አባቷ ተመለሰች፤ ዮፍታሔም የተሳለውን ስእለት አደረገ፤ እርስዋም ወንድ አላወቀችም ነበር።'),
  ('c85ae779-bba5-5aaa-a193-b17481534972', '5686c18e-e5fa-5deb-a7c8-eac10fb62923', '2e243ee0-52d3-5598-a67e-f9ffa3c11d42', 7, 40, 'የእስራኤልም ሴቶች ልጆች ለገለዓዳዊዉ ለዮፍታሔ ልጅ በዓመት አራት ቀን ያለቅሱላት ዘንድ በዓመት በዓመት ይሄዱ ነበር። ይህችም በእስራኤል ዘንድ ሥርዐት ሆነች።'),
  ('71818801-c7c8-5286-aeee-2c0e69a67616', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 1, 1, 'የኤፍሬምም ሰዎች ተሰበሰቡ፤ ወደ ጻፎንም ተሻግረው ዮፍታሔን፥ “ከአሞን ልጆች ጋር ለመዋጋት ስታልፍ ከአንተ ጋር እንድንሄድ ስለምን አልጠራኸንም? ቤትህን በአንተ ላይ በእሳት እናቃጥለዋለን” አሉት።'),
  ('31dc81ab-0935-5adb-ae9c-5fa5c2c5089b', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 2, 2, 'ዮፍታሔም፥ “እኔና ሕዝቤ የተገፋን ነን፤ የአሞን ልጆችም በጽኑዕ አሠቃዩን፤ በጠራናችሁም ጊዜ ከእጃቸው አላዳናችሁንም።'),
  ('1941a46f-7614-5083-a849-5897dd164c76', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 3, 3, 'የሚያድን እንደሌለም ባየሁ ጊዜ ሰውነቴን በእጄ አሳልፌ ለሞት በመስጠት ወደ አሞን ልጆች ተሻገርሁ፤ እግዚአብሔርም በፊቴ ጣላቸው፤ ለምንስ ዛሬ ልትወጉኝ ወደ እኔ መጣችሁ?” አላቸው።'),
  ('4f9ab41a-b11c-5ec1-a854-8e3fe318e6e6', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 4, 4, 'ዮፍታሔም የገለዓድን ሰዎች ሁሉ ሰበሰበ፤ ከኤፍሬምም ጋር ተዋጋ፤ ኤፍሬምም፥ “ገለዓዳውያን ሆይ! እናንተ በኤፍሬምና በምናሴ መካከል የተቀመጣችሁ ከኤፍሬም ሸሽታችሁ ነው” ስላሉ የገለዓድ ሰዎች ኤፍሬምን መቱ።'),
  ('78f0e2a2-e2e1-54a5-ad48-f04b80b9b586', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 5, 5, 'የገለዓድ ሰዎችም ኤፍሬም በሚያልፍበት በዮርዳኖስ ማዶ ደረሱባቸው። ከዚህ በኋላ ከኤፍሬም ያመለጡት እንሻገር ባሉ ጊዜ የገለዓድ ሰዎች፥ “በውኑ እናንተ ከኤፍሬም ወገን ናችሁን?” ቢሉአቸው “አይደለንም” አሉ።'),
  ('41b7a930-c1f7-55c2-a1f9-fd75927b9704', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 6, 6, 'እነርሱም፥ “አሁን ሺቦሌት በሉ” አሉአቸው፤ እነርሱም አጥርተው መናገር አልቻሉምና፥ “ሲቦሌት” አሉ፤ ይዘውም በዮርዳኖስ መሸጋገርያ አረዱአቸው፤ በዚያም ጊዜ ከኤፍሬም አርባ ሁለት ሺህ ሰዎች ወደቁ።'),
  ('0149d3c3-5c2d-5558-ad94-9e8319062333', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 7, 7, 'ዮፍታሔም እስራኤልን ስድስት ዓመት ገዛ። ገለዓዳዊው ዮፍታሔም ሞተ፤ በሀገሩ በገለዓድም ተቀበረ።'),
  ('1466db3b-12bb-5ed4-ae45-44cb9729b80d', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 8, 8, 'ከእርሱም በኋላ የቤተ ልሔሙ ሐሴቦን እስራኤልን ገዛ።'),
  ('4757be8c-75f5-5df5-a1a6-baa69e6cda9e', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 9, 9, 'ሠላሳ ወንዶች ልጆችና ሠላሳ ሴቶች ልጆችንም ወለደ፤ ሠላሳ ሴቶች ልጆቹንም ወደ ውጭ ሀገር ዳረ፤ ለወንዶች ልጆቹም ከውጭ ሀገር ሠላሳ ሴቶች ልጆችን አመጣ። እስራኤልንም ሰባት ዓመት ገዛ።'),
  ('03aad731-55d7-5559-a58f-8df45701fb10', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 10, 10, 'ሐሴቦንም ሞተ፤ በቤተ ልሔምም ተቀበረ።'),
  ('72c18e6f-8166-5a10-ab95-ff324766b4d4', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 11, 11, 'ከእርሱም በኋላ ዛብሎናዊው ኤሎን እስራኤልን ዐሥር ዓመት ገዛ።'),
  ('73ec3514-7a6f-5672-a667-a3d763d77411', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 12, 12, 'ዛብሎናዊው ኤሎንም ሞተ፤ በዛብሎንም ምድር በኤሎም ተቀበረ።'),
  ('8cb7c3a3-fe11-51cd-a8b7-a30b181e08a5', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 13, 13, 'ከእርሱም በኋላ የኤፍራታዊው የኤሎን ልጅ ለቦን እስራኤልን ገዛ።'),
  ('8fa90cf5-5d88-5dbf-a3f0-1903f621eab5', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 14, 14, 'አርባም ልጆች፥ ሠላሳም የልጅ ልጆች ተወለዱለት፤ በሰባም የአህያ ግልገሎች ላይ ይቀመጡ ነበር። እስራኤልንም ስምንት ዓመት ገዛ።'),
  ('fc148407-ef14-5376-a4f2-40897bdcc01b', '2ecb309a-ef25-5388-ad53-eb1db861bb0a', '834a8eca-fa2d-569e-a19e-aa83245b6dba', 15, 15, 'የኤፍራታዊው የኤሎን ልጅ ለቦንም ሞተ፤ በተራራማውም በአማሌቃውያን ምድር በኤፍሬም ባለችው በኤፍራታ ተቀበረ።'),
  ('d11266ff-b832-56c2-a860-95b5ec571aef', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 1, 1, 'የእስራኤልም ልጆች በእግዚአብሔር ፊት እንደ ገና ክፉ ሥራ ሠሩ፤ እግዚአብሔርም በፍልስጥኤማውያን እጅ አርባ ዓመት አሳልፎ ሰጣቸው።'),
  ('a1e4c83e-09ef-5a4a-a4f9-8206223a3522', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 2, 2, 'ከዳን ወገን የሆነ ማኑሄ የሚባል አንድ የሶራሕ ሰው ነበረ፤ ሚስቱም መካን ነበረች፤ ልጅም አልወለደችም ነበር።'),
  ('1d55eb5c-b01b-56be-a2b3-d77d39103599', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 3, 3, 'የእግዚአብሔርም መልአክ ለሴቲቱ ተገልጦ እንዲህ አላት፥ “እነሆ፥ አንቺ መካን ነሽ፤ ልጅም አልወለድሽም፤ ነገር ግን ትፀንሻለሽ፤ ወንድ ልጅም ትወልጃለሽ።'),
  ('3272c265-f507-5a91-a402-614231c5594b', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 4, 4, 'አሁንም ተጠንቀቂ፤ የወይን ጠጅንና የሚያሰክር መጠጥንም አትጠጪ፤ ርኩስም ነገር አትብዪ።'),
  ('3b0ff7c8-58ff-5869-a500-4903a7565441', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 5, 5, 'እነሆ፥ ትፀንሻለሽ፤ ወንድ ልጅም ትወልጃለሽ፤ ልጁም ከእናቱ ማኅፀን ጀምሮ ለእግዚአብሔር የተለየ ናዝራዊ ይሆናልና በራሱ ላይ ምላጭ አይድረስበት፤ እርሱም እስራኤልን ከፍልስጥኤማውያን እጅ ማዳን ይጀምራል።”'),
  ('e504bd00-5550-5c74-a418-56bdf1a014f0', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 6, 6, 'ሴቲቱም ወደ ባልዋ መጥታ፥ “አንድ የእግዚአብሔር ሰው ወደ እኔ መጣ፤ መልኩም እንደ እግዚአብሔር መልአክ እጅግ የሚያስደነግጥ ነበረ፤ ከወዴትም እንደ መጣ ጠየቅሁት፥ እርሱም ስሙን አልነገረኝም።'),
  ('c86a187a-11bb-5361-a178-637c0e7a4e4a', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 7, 7, 'እርሱም፦ እነሆ፥ ትፀንሻለሽ፤ ወንድ ልጅም ትወልጃለሽ፤ እንግዲህ የወይን ጠጅንና የሚያሰክር መጠጥን አትጠጪ፥ ርኩስ ነገርንም አትብዪ፤ ልጁ ከእናቱ ማኅፀን ጀምሮ እስኪሞት ድረስ ለእግዚአብሔር የተለየ ናዝራዊ ይሆናልና አለኝ” ብላ ተናገረች።'),
  ('11fb211a-6b20-5447-aaf1-fa9e791db274', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 8, 8, 'ማኑሄም፥ “ጌታ ሆይ፥ ወደ እኛ የላክኸው የእግዚአብሔር ሰው፥ እባክህ እንደገና ወደ እኛ ይምጣ፤ ለሚወለደውም ልጅ ምን እንደምናደርግ ያስገንዝበን” ብሎ ወደ እግዚአብሔር ለመነ።'),
  ('03245eeb-2d62-56fc-a6b2-db5c433d140f', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 9, 9, 'እግዚአብሔርም የማኑሄን ቃል ሰማ፤ የእግዚአብሔርም መልአክ እንደ ገና በእርሻ ውስጥ ተቀምጣ ሳለች ወደ ሴቲቱ መጣ፤ ባልዋ ማኑሄ ግን ከእርስዋ ጋር አልነበረም።'),
  ('f79dc1a5-e24d-5865-a54f-9e626957b4c0', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 10, 10, 'ሴቲቱም ፈጥና ሮጠች ለባልዋም፥ “እነሆ፥ አስቀድሞ ወደ እኔ የመጣው ያ ሰው ደግሞ ተገለጠልኝ” ብላ ነገረችው።'),
  ('ebe31a48-e632-507a-a96a-6a9f41b1f834', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 11, 11, 'ማኑሄም ተነሥቶ ሚስቱን ተከተለ፤ ወደ ሰውዬዉም መጥቶ፥ “ከሚስቴ ጋር የተነጋገርህ አንተ ነህን?” አለው። መልአኩም፥ “እኔ ነኝ” አለ።'),
  ('52218aa0-9fd4-5799-a05b-934b9c57bd77', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 12, 12, 'ማኑሄም፥ “እነሆ፥ ቃልህ በደረሰ ጊዜ የልጁ ነገሩ፥ ግብሩስ ምንድን ነው?” አለው።'),
  ('3b5bb265-f2ea-58ae-a764-4b1dd76ef806', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 13, 13, 'የእግዚአብሔርም መልአክ ማኑሄን፥ “ለሚስትህ ከነገርኋት ሁሉ ተጠበቁ።'),
  ('b9f09e3e-08e6-5661-a589-92d8174d9005', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 14, 14, 'ከወይንም ከሚወጣው ሁሉ አትብላ፤ የወይን ጠጅንና የሚያሰክር መጠጥንም አትጠጣ፤ ርኩስንም ነገር ሁሉ አትብላ፤ ያዘዝኋትን ሁሉ ጠብቁ” አለው።'),
  ('69155316-bb73-5aae-a68c-b5b746f87f92', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 15, 15, 'ማኑሄም የእግዚአብሔርን መልአክ፥ “የፍየል ጠቦት እናዘጋጅልህ ዘንድ ግድ እንልሃለን” አለው።'),
  ('b6544164-2091-5e20-adde-c14251ca604a', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 16, 16, 'የእግዚአብሔርም መልአክ ማኑሄን፥ “አንተ የግድ ብትለኝ እህልህን አልበላም፤ የሚቃጠለውንም መሥዋዕት ብታደርግ ለእግዚአብሔር አቅርበው” አለው። ማኑሄም የእግዚአብሔር መልአክ መሆኑን አላወቀም ነበር።'),
  ('4f2eea1e-9dcc-57a1-a754-f25cd307518b', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 17, 17, 'ማኑሄም የእግዚአብሔርን መልአክ፥ “ነገርህ በደረሰ ጊዜ እንድናከብርህ ስምህ ማን ነው” አለው።'),
  ('25ca7472-125b-5986-a6dc-2540ffa878af', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 18, 18, 'የእግዚአብሔርም መልአክ፥ “ስሜ ድንቅ ነውና ለምን ትጠይቃለህ?” አለው።'),
  ('2aaa8bda-be6a-51ba-a812-cb57b7550f01', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 19, 19, 'ማኑሄም የፍየሉን ጠቦትና የእህሉን ቍርባን ወስዶ በድንጋይ ላይ ለእግዚአብሔር አቀረበው። መልአኩም ተአምራት አደረገ፤ ማኑሄና ሚስቱም ይመለከቱ ነበር።'),
  ('8feb23c5-115f-54ca-a335-ffe49e136667', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 20, 20, 'ነበልባሉም ከመሠዊያዉ ላይ ወደ ሰማይ በወጣ ጊዜ የእግዚአብሔር መልአክ በመሠዊያዉ ነበልባል ውስጥ ወደ ሰማይ ዐረገ፤ ማኑሄና ሚስቱም ተመለከቱ፤ በምድርም በግንባራቸው ወደቁ።'),
  ('556dba42-ffa7-5e0e-ada7-d6bfb68ee898', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 21, 21, 'የእግዚአብሔርም መልአክ ዳግመኛ ለማኑሄና ለሚስቱ አልተገለጠም፤ ያን ጊዜም ማኑሄ የእግዚአብሔር መልአክ መሆኑን ዐወቀ።'),
  ('da4eac77-22f6-57ed-a6f6-b61b8599866d', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 22, 22, 'ማኑሄም ሚስቱን፥ “እግዚአብሔርን አይተናልና ሞትን እንሞታለን” አላት።'),
  ('15396118-dc88-54c5-a806-2a21294a0976', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 23, 23, 'ሚስቱም፥ “እግዚአብሔርስ ሊገድለን ቢወድድ ኖሮ የሚቃጠለውን መሥዋዕትና የእህሉን ቍርባን ከእጃችን ባልተቀበለን፥ ይህንም ነገር ሁሉ ባላሳየን፥ እንዲህ ያለ ነገርም በዚህ ጊዜ ባላሰማን ነበር” አለችው።'),
  ('d4d1e64c-66be-5c5d-a992-1686b3accdef', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 24, 24, 'ሴቲቱም ወንድ ልጅ ወለደች፤ ስሙንም ሶምሶን ብላ ጠራችው፤ እግዚአብሔርም ባረከው፤ ልጁም አደገ።'),
  ('465ea17f-d2ea-51ef-add2-712e848511eb', '8dbcfcf7-01d7-5215-a6f3-fdaf499cffc3', '8dd7f39a-aeaf-5317-a34b-e7d4bc504e8a', 25, 25, 'የእግዚአብሔርም መንፈስ በሶራሕና በእስታሔል መካከል ባለው በዳን ሰፈር ውስጥ ከእርሱ ጋር ይሄድ ጀመረ።'),
  ('d6fee1b2-cb55-5299-aef3-62b9de1ecb37', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 1, 1, 'ሶምሶንም ወደ ቴምናታ ወረደ፤ በቴምናታም ከፍልስጥኤማውያን ልጆች አንዲት ሴት አየ፤ እርስዋም በፊቱ ደስ አለችው።'),
  ('25d47cd7-bcbe-5ac2-a76e-6f557de6ef16', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 2, 2, 'ወጥቶም ለአባቱና ለእናቱ፥ “በቴምናታ ከፍልስጥኤማውያን ልጆች አንዲት ሴት አይቻለሁ፤ አሁንም እርስዋን አጋቡኝ” አላቸው።'),
  ('e559ee3c-80f9-55e1-a0a1-942cd96476fa', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 3, 3, 'አባቱና እናቱም፥ “ካልተገረዙት ከፍልስጥኤማውያን ሚስት ለማግባት ትሄድ ዘንድ ከወንድሞችህ ሴቶች ልጆች፥ ከሕዝቤም ሁሉ መካከል ሴት የለችምን?” አሉት። ሶምሶንም አባቱን፥ “ለዐይኔ እጅግ ደስ አሰኝታኛለችና እርስዋን አጋባኝ” አለው።'),
  ('eca52a7b-cc57-50cf-a1be-31207289c7eb', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 4, 4, 'አባቱና እናቱም ነገሩ ከእግዚአብሔር እንደ ሆነ አላወቁም፤ እርሱ ከፍልስጥኤማውያን በቀልን ይመልስ ዘንድ ይፈልግ ነበርና። በዚያም ወራት ፍልስጥኤማውያን እስራኤልን ይገዙ ነበር።'),
  ('ffed49bb-41af-5007-af77-ac7ca308b297', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 5, 5, 'ሶምሶንም፥ አባቱና እናቱም ወደ ቴምናታ ወረዱ፤ በቴምናታም ወዳለው ወደ ወይኑ ስፍራ ፈቀቅ አለ፤ እነሆም፥ የአንበሳ ደቦል እያገሣ መጣበት።'),
  ('dac3dd67-676f-5ad7-ad7e-4959e8a8669f', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 6, 6, 'የእግዚአብሔርም መንፈስ በእርሱ ላይ አደረ፤ የፍየል ጠቦትን እንደሚጥልም ጣለው፤ በእጁም እንደ ኢምንት ሆነ፤ ያደረገውንም ለአባቱና ለእናቱ አልተናገረም።'),
  ('c34e4cab-40c1-55bc-a8f7-16eea197e294', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 7, 7, 'ሂደውም ከሴቲቱ ጋር ተነጋገሩ፤ ሶምሶንንም በፊቱ ደስ አሰኘችው።'),
  ('3d8d197f-9030-5309-a935-78a840b8f701', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 8, 8, 'ከጥቂት ቀኖችም በኋላ ሊያገባት ተመለሰ፤ የአንበሳውንም ሬሳ ያይ ዘንድ ከመንገድ ፈቀቅ አለ፤ እነሆም፥ በአንበሳው አፍ ውስጥ ንብ ሰፍሮበት ነበር፤ ማርም ነበረበት።'),
  ('3a33b8d6-a861-56d2-ab7d-d539ab495ec5', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 9, 9, 'ወስዶም በላ፤ እየበላም ሄደ፤ ወደ አባቱና ወደ እናቱም ደረሰ፤ ሰጣቸውም፤ እነርሱም በሉ፤ ማሩንም ከአንበሳው አፍ ውስጥ እንዳወጣው አልነገራቸውም።'),
  ('52ac6ba2-616f-51cf-a9c6-5f5b1b5418b5', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 10, 10, 'አባቱም ወደ ሴቲቱ ወረደ፤ ጐበዞችም እንዲሁ ያደርጉ ነበርና ሶምሶን በዚያ ሰባት ቀን በዓል አደረገ።'),
  ('90d64110-5b34-5443-ab07-dd891b1bf122', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 11, 11, 'ከዚህም በኋላ ፈርተው ሠላሳ ሰዎችን በእርሱ ላይ ሾሙ፤ ከእርሱም ጋር ተቀመጡ።'),
  ('08d61abc-03fe-577b-adca-e0f6893f553b', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 12, 12, 'ሶምሶንም አላቸው፥ “እንቆቅልሽ ልስጣችሁ፤ በሰባቱም በበዓሉ ቀኖች ውስጥ ፈትታችሁ ብትነግሩኝ፥ ሠላሳ የበፍታ ቀሚስና ሠላሳ ልውጥ ልብስ እሰጣችኋለሁ፤'),
  ('05a85e15-7504-5491-a06e-89f396eca1bf', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 13, 13, 'መፍታት ባትችሉ ግን እናንተ ለእኔ ሠላሳ የበፍታ ቀሚስና ሠላሳ ልውጥ ልብስ ትሰጡኛላችሁ።” እነርሱም፥ “ምሳሌህን መስልና እንስማህ” አሉት።'),
  ('5e8e1faa-b32b-52a6-aa47-84c434cdf3f5', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 14, 14, 'እርሱም፥ “ከበላተኛ መብል ወጣ፤ ከብርቱም ጣፋጭ ወጣ” አላቸው። እስከ ሦስት ቀንም እንቆቅልሹን መፍታት አልቻሉም።'),
  ('89e92847-9993-5c50-a280-7485540e1c3e', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 15, 15, 'ከዚህ በኋላ በአራተኛው ቀን የሶምሶንን ሚስት፥ “እንቆቅልሹን እንዲነግርሽ ባልሽን አባብይው፤ አለዚያም አንቺንና የአባትሽን ቤት በእሳት እናቃጥላለን፤ ወይስ ወደዚህ የጠራችሁን ልታደኸዩን ነውን?” አሉአት።'),
  ('1201e5b1-5869-5161-aef3-b221e17eb2dd', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 16, 16, 'የሶምሶንም ሚስት በፊቱ እያለቀሰችበት፥ “ጠልተኸኛል፤ ከቶም አትወድደኝም፤ ለሕዝቤ ልጆች የነገርኸውን እንቆቅልሽህን አልነገርኸኝምና” አለችው። እርሱም፥ “እነሆ፥ ለአባቴና ለእናቴ አልነገርኋቸውም፤ ለአንቺ እነግርሻለሁን?” አላት።'),
  ('c10d8a11-697b-5e53-aacf-643d2f7fa75d', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 17, 17, 'ሰባቱንም የበዓል ቀን አለቀሰችበት፤ እርስዋም ነዝንዛዋለችና በሰባተኛው ቀን ነገራት። ለሕዝብዋም ልጆች ነገረቻቸው።'),
  ('a9046756-b4f3-54da-a806-bbe88ac453b6', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 18, 18, 'በሰባተኛዪቱም ቀን ፀሐይ ሳትገባ የከተማዪቱ ሰዎች፥ “ከማር የሚጣፍጥ ምንድን ነው? ከአንበሳስ የሚበረታ ማን ነው?” አሉት። ሶምሶንም፥ “በጥጃዬ ባላረሳችሁ ኑሮ የእንቆቅልሼን ትርጓሜ ባላወቃችሁም ነበር” አላቸው።'),
  ('f68a41b6-62fa-5258-a083-126d6c597d02', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 19, 19, 'የእግዚአብሔርም መንፈስ በላዩ ወረደ፤ ወደ አስቀሎናም ወረደ፤ ከዚያም ሠላሳ ሰዎችን ገደለ፤ ልብሳቸውንም ገፍፎ እንቆቅልሹን ለነገሩት ሰዎች ሰጠ። ሶምሶንም ተቈጣ፤ ወደ አባቱም ቤት ተመለሰ።'),
  ('b6dc9e64-96ea-598c-ae75-396221740d2e', '29bd9bd2-f988-5829-ad25-e8fcbaee8812', '742c57fb-3db6-534a-ad4c-66360c102c17', 20, 20, 'የሶምሶንም ሚስት ከስር ሚዜው ጋር ተቀመጠች።'),
  ('1aa9b9ed-af37-5ac5-a4bc-7d8134c32d98', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '6855eb43-508e-5f5c-a27f-2d4aefcaaa57', 1, 1, 'ከጊዜም በኋላ በስንዴ መከር ጊዜ ሶምሶን የፍየል ጠቦት ይዞ ሚስቱን ሊጠይቅ ሄደና፥ “ወደ ጫጕላ ቤት ወደ ሚስቴ ልግባ” አለ፤ አባቷ ግን እንዳይገባ ከለከለው።'),
  ('194d1535-dfd9-5ad4-a580-9dece9765b14', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '6855eb43-508e-5f5c-a27f-2d4aefcaaa57', 2, 2, 'አባቷም፥ “ፈጽመህ ጠላህዋት ያልህ መስሎኝ ለሚዜህ አጋባኋት፤ ታናሽ እኅቷ ከእርስዋ ይልቅ የተዋበች አይደለችምን? እባክህ በእርስዋ ፋንታ አግባት” አለው።'),
  ('a24bf78b-1d16-5324-a1c8-62b9140e40ac', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '6855eb43-508e-5f5c-a27f-2d4aefcaaa57', 3, 3, 'ሶምሶንም፥ “ከእንግዲህ ወዲህ በፍልስጥኤማውያን ላይ ክፉ ባደርግ እኔ ንጹሕ ነኝ” አላቸው።'),
  ('dcb19822-9ad6-59d9-a2b6-f01851adf31d', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '6855eb43-508e-5f5c-a27f-2d4aefcaaa57', 4, 4, 'ሶምሶንም ሄዶ ሦስት መቶ ቀበሮችን ያዘ፤ ችቦም ወስዶ ሁለት ሁለቱን ቀበሮዎች በጅራታቸው አሰረ፤ በሁለቱም ጅራቶች መካከል አንድ ችቦ አደረገ።'),
  ('6637ecac-a0af-52dd-a71b-ecf9fbc01d09', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '6855eb43-508e-5f5c-a27f-2d4aefcaaa57', 5, 5, 'ችቦውንም አንድዶ በቆመው በፍልስጥኤማውያን እህል መካከል ሰደዳቸው፤ ነዶውንም፥ ክምሩንም፥ የቆመዉንም እህል፥ ወይኑንም፥ ወይራዉንም አቃጠለ።'),
  ('9b000c97-3baf-5406-aab0-5d67097797c1', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '6855eb43-508e-5f5c-a27f-2d4aefcaaa57', 6, 6, 'ፍልስጥኤማውያንም፥ “ይህን ያደረገ ማን ነው?” አሉ። እነርሱም፥ “ሚስቱን ወስዶ ለሚዜው አጋብቶበታልና የቴምናታዊዉ አማች ሶምሶን ነው” አሉአቸው። ፍልስጥኤማውያንም ወጥተው የአባቷን ቤትና እርስዋን አባቷንም በእሳት አቃጠሉ።'),
  ('dd3ce3d7-f980-558d-a685-c38e2d419a92', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '6855eb43-508e-5f5c-a27f-2d4aefcaaa57', 7, 7, 'ሶምሶንም አላቸው- “ይህን ብታደርጉም ደስ አይለኝም፤ በቀሌ ከአንድ ሰው ብቻ አይደለም፤ ሁላችሁንም እበቀላችኋለሁ፤ ከዚያም በኋላ አርፋለሁ።”'),
  ('0fe016f2-3c95-574f-a08a-3831e0ab1343', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '6855eb43-508e-5f5c-a27f-2d4aefcaaa57', 8, 8, 'ሶምሶንም ጭን ጭናቸውን ብሎ በታላቅ አገዳደል መታቸው፤ ወርዶም ኢጣም በምትባል ዋሻ በወንዝ ዳር ተቀመጠ።'),
  ('d02c354a-7b2c-5344-a3e8-78cae3e98386', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 1, 9, 'ፍልስጥኤማውያንም ወጡ፤ በይሁዳም ሰፈሩ፤ የአህያ መንጋጋ አጥንት በተባለ ቦታም ተበታትነው ተቀመጡ።'),
  ('0dcffdbb-015b-51d7-ae98-10ae093a4349', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 2, 10, 'የይሁዳም ሰዎች ሁሉ፥ “በእኛ ላይ የወጣችሁት ለምንድን ነው?” አሉ። እነርሱም፥ “ሶምሶንን ልናስር፥ እንዳደረገብንም ልናደርግበት መጥተናል” አሏቸው።'),
  ('e8ebbaf5-74a5-5cf5-a14c-584f86f77f97', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 3, 11, 'ከይሁዳም ሰዎች ሦስት ሺህ የሚያህሉ በኢጣም ዓለት ወዳለው ዋሻ ወርደው ሶምሶንን፥ “ገዢዎቻችን ፍልስጥኤማውያን እንደሆኑ አታውቅምን? ያደረግህብን ይህ ምንድን ነው?” አሉት። ሶምሶንም፥ “እንዳደረጉባችሁ እንዲሁ አደረግሁባቸው” አላቸው።'),
  ('601b6858-bcc1-5a92-a6e9-e5f1cca15555', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 4, 12, 'እነርሱም፥ “አስረን በፍልስጥኤማውያን እጅ አሳልፈን ልንሰጥህ መጥተናል” አሉት። ሶምሶንም፥ “እናንተ እንዳትገድሉኝ ማሉልኝ፤ ለእነርሱም አሳልፋችሁ ስጡኝ፤ እናንተ ግን ከእኔ ጋር አትዋጉ” አላቸው።'),
  ('66053d8c-fcda-58d4-a3e3-a0a1caf5cd19', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 5, 13, 'እነርሱም፥ “በገመድ አስረን በእጃቸው አሳልፈን እንሰጥሃለን እንጂ አንገድልህም” ብለው ማሉለት። በሁለትም አዲስ ገመድ አስረው ከዓለቱ ውስጥ አወጡት።'),
  ('fa47f131-439d-59bc-aad0-5e9a2d351177', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 6, 14, 'የአህያ መንጋጋ አጥንት ወደ ተባለ ቦታም ደረሰ፤ ፍልስጥኤማውያንም ደንፍተው ተቀበሉት፤ ወደ እርሱም ሮጡ። የእግዚአብሔርም መንፈስ በእርሱ ላይ አደረ፤ በክንዱም ያሉ እነዚያ ገመዶች በእሳት ላይ እንደ ተጣለ ገለባ ሆኑ፤ ማሰሪያውም ከክንዱ ተፈታ፤'),
  ('c5ded0ed-410c-5a9c-a007-15d537d5e4fd', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 7, 15, 'የወደቀ የአህያ መንጋጋ አጥንትንም በመንገድ አገኘ። እጁንም ዘርግቶ ወሰደው፤ በእርሱም አንድ ሺህ ሰው ገደለ።'),
  ('3fa4ce66-16af-5546-abbb-22686ea179a2', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 8, 16, 'ሶምሶንም፥ “በአህያ መንጋጋ አጥንት ክምር በክምር ላይ አድርጌአቸዋለሁ፤ በአህያ መንጋጋ አጥንት አንድ ሺህ ሰው ገድያለሁና” አለ።'),
  ('5a0617c5-1594-5586-aca0-dcfd1a26759f', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 9, 17, 'መናገሩንም በፈጸመ ጊዜ መንጋጋውን ከእጁ ጣለ፤ የዚያንም ስፍራ ስም “ቀትለ አጽመ መንሰክ” ብሎ ጠራው።'),
  ('5eb15046-3a38-5aaf-acd2-672c069ac897', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 10, 18, 'እርሱም እጅግ ተጠምቶ ነበርና፥ “አንተ ይህችን ታላቅ ማዳን በባሪያህ እጅ ሰጥተሃል፤ አሁንም በጥም እሞታለሁ፤ ባልተገረዙትም እጅ እወድቃለሁ” ብሎ ወደ እግዚአብሔር ጮኸ።'),
  ('4955cb0a-88f9-5331-af99-38081545d289', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 11, 19, 'እግዚአብሔርም የዚያችን የአህያ መንጋጋ አጥንት ስንጥቃት ከፈተ፤ ከእርስዋም ውኃ ወጣ፤ እርሱም ጠጣ፤ ነፍሱም ተመለሰች፤ ከውኃ ጥሙም ዐረፈ። ስለዚህም የዚያ ቦታ ስም እስከ ዛሬ ድረስ “ነቅዐ አጽመ መንሰክ” ተብሎ ተጠራ።'),
  ('d9a16f59-0694-52e4-a889-ccd0a5167f2e', 'ef43e36d-0968-50ef-a85e-1d1c072895e0', '8be5e444-c6c6-5730-a072-2f382e7e324e', 12, 20, 'በፍልስጥኤማውያንም ዘመን እስራኤልን ሃያ ዓመት ገዛቸው።'),
  ('728a2aaf-8fa4-526e-a57e-dd785604abf2', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'dd8782b6-5f04-5f78-a6be-d2cc5106d64f', 1, 1, 'ሶምሶንም ወደ ጋዛ ሄደ፥ በዚያም ጋለሞታ ሴት አይቶ ወደ እርስዋ ገባ።'),
  ('fc4b70a7-bb6f-51d2-a763-ef0a0e95894d', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'dd8782b6-5f04-5f78-a6be-d2cc5106d64f', 2, 2, 'ለጋዛ ሰዎችም፥ “ሶምሶን ወደዚህ መጥቶአል” ብለው ነገሩአቸው፤ ከበቡትም። ሌሊቱንም ሁሉ በከተማዪቱ በር ሸመቁበት፥ “ማለዳ እንገድለዋለን” ብለውም ሌሊቱን ሁሉ በዝምታ ተቀመጡ።'),
  ('b144c68b-57eb-51d1-adb5-518362f79844', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'dd8782b6-5f04-5f78-a6be-d2cc5106d64f', 3, 3, 'ሶምሶንም እስከ እኩለ ሌሊት ተኛ፤ በእኩለ ሌሊትም ተነሥቶ የከተማዪቱን በር መዝጊያ ያዘ፤ ከሁለቱ መቃኖችና ከመወርወሪያው ጋር ነቀለው፤ በትከሻውም ላይ አደረገ፤ በኬብሮንም ፊት ወዳለው ተራራ ራስ ላይ ተሸክሞት ወጣ፤ በዚያም ጣለው።'),
  ('0783baf6-906b-5afb-ac50-0d5dd86540e9', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 1, 4, 'ከዚህ በኋላ በሶሬሕ ሸለቆ የነበረች ደሊላ የተባለች አንዲት ሴትን ወደደ።'),
  ('7dabb5f1-ffc8-5796-afc4-cfec555608a9', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 2, 5, 'የፍልስጥኤማውያን መሳፍንትም ወደ እርስዋ ወጥተው፥ “እርሱን አባብለሽ በእርሱ ያለ ታላቅ ኀይል በምን እንደ ሆነ፥ እኛም እርሱን ለማዋረድ እናስረው ዘንድ የምናሸንፈው በምን እንደ ሆነ ዕወቂ፤ እኛም እያንዳንዳችን ሺህ አንድ መቶ ብር እንሰጥሻለን” አሉአት።'),
  ('5d233a40-5337-5629-a6e6-143ac475dd41', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 3, 6, 'ደሊላም ሶምሶንን፥ “ታላቅ ኀይልህ በምን እንደ ሆነ፥ በምንስ ብትታሰር እንደምትዋረድ እባክህ ንገረኝ” አለችው።'),
  ('3bf2a393-cfcc-5c54-a706-23a3230ac67d', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 4, 7, 'ሶምሶንም፥ “በሰባት ባልደረቀ በርጥብ ጠፍር ቢያስሩኝ፥ እደክማለሁ፤ እንደ ሌላም ሰው እሆናለሁ” አላት ።'),
  ('cadd6bb3-92e2-5935-a08a-942b997146ce', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 5, 8, 'የፍልስጥኤማውያን መሳፍንትም ሰባት ያልደረቀ ርጥብ ጠፍር አመጡላት፤ በእነርሱም አሰረችው።'),
  ('12e17bdb-20f5-5e20-a53d-56393f434f50', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 6, 9, 'የሚያደቡትም ሰዎች በጓዳዋ ውስጥ ተደብቀው ነበር። እርስዋም፥ “ሶምሶን ሆይ! ፍልስጥኤማውያን መጡብህ” አለችው። እርሱም ፈትል እሳት በሸተተው ጊዜ እንዲበጠስ ጠፍሩን በጣጠሰው፤ ኀይሉም በምን እንደ ሆነ አልታወቀም።'),
  ('053838bc-d38e-5830-a9b0-ab6ff03da587', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 7, 10, 'ደሊላም ሶምሶንን፥ “እነሆ፥ አታለልኸኝ፤ የነገርኸኝም ሐሰት ነው፤ አሁንም የምትታሰርበት ምን እንደሆነ፥ እባክህ ንገረኝ” አለችው።'),
  ('76221b77-3de6-5df5-aae7-a3ccec3ab989', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 8, 11, 'እርሱም፥ “ሥራ ባልተሠራባቸው ሰባት አዳዲስ ገመዶች ቢያስሩኝ፥ እደክማለሁ፤ እንደ ሌላውም ሰው እሆናለሁ” አላት።'),
  ('859689c5-6604-57ce-a1af-aee5ca2af678', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 9, 12, 'ደሊላም ሰባት አዳዲስ ገመዶች ወስዳ በእነርሱ አሰረችው፤ የሚያደቡትም ሰዎች በጓዳዋ ውስጥ ተቀምጠው ነበር። እርስዋም፥ “ሶምሶን ሆይ! ፍልስጥኤማውያን መጡብህ” አለችው። ገመዶችንም ከክንዱ እንደ ፈትል በጣጠሳቸው።'),
  ('b6cc1116-9b34-5213-a9b9-58e2d11f9879', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 10, 13, 'ደሊላም ሶምሶንን፥ “እስከ አሁን ድረስ አታለልኸኝ፤ የነገርኸኝም ሐሰት ነው፤ የምትታሰርበት ምን እንደሆነ ንገረኝ” አለችው። እርሱም፥ “የራሴን ጠጕር ሰባቱን ጕንጕን ከድር ጋር ብትጐነጕኚው፥ በግድግዳም ላይ በችካል ብትቸክዪው፥ ከሰዎች እንደ አንዱ እደክማለሁ፥” አላት።'),
  ('5e616a6d-01b0-5c77-a471-8a85b66b2a2e', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 11, 14, 'ደሊላም አስተኛችው፤ የራሱንም ጠጕር ሰባቱን ጕንጕን ከድር ጋር ጐነጐነችው፤ በግድግዳም ላይ በችካል ቸከለቻቸው፥ “ሶምሶን ሆይ! ፍልስጥኤማውያን መጡብህ” አለችው። ከእንቅልፉም ነቃ፥ ችካሉንም ከነቈንዳላው ከግድግዳው ነቀለ፤ ኀይሉም አልታወቀም።'),
  ('82082c87-2b07-5431-abd2-b51eda10a46e', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 12, 15, 'ደሊላም፥ “ ‘አንተ እወድድሻለሁ’ እንዴት ትለኛለህ? ልብህ ከእኔ ጋር አይደለም፤ ስታታልለኝ ይህ ሦስተኛ ጊዜህ ነው፥ ታላቅ ኀይልህም በምን እንደ ሆነ አልነገርኸኝም” አለችው።'),
  ('57e76574-530c-5a1c-ae63-c7b2ff6104d8', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 13, 16, 'ከዚህም በኋላ ሌሊቱን ሁሉ በነገር በዘበዘበችውና በአደከመችው ጊዜ፥ ልሙት እስኪል ድረስ ተበሳጨ።'),
  ('8b3dddac-b41d-57df-afef-c27781258450', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 14, 17, 'እርሱም፥ “ከእናቴ ማኅፀን ጀምሬ ለእግዚአብሔር ናዝራዊ ነኝና ራሴን ምላጭ አልነካኝም፤ የራሴንም ጠጕር ብላጭ ኀይሌ ከእኔ ይነሣል፤ እደክማለሁም፤ እንደ ሌላም ሰው ሁሉ እሆናለሁ” ብሎ የልቡን ሁሉ ነገራት።'),
  ('38a1dfd2-c709-593f-a91c-5027b3bfca91', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 15, 18, 'ደሊላም የልቡን ሁሉ እንደ ነገራት ባወቀች ጊዜ፥ “የልቡን ሁሉ ነግሮኛልና ይህን ጊዜ ደግሞ ኑ” ብላ ላከችና የፍልስጥኤማውያንን መሳፍንት ጠራች። የፍልስጥኤማውያንም መሳፍንት ብሩን በእጃቸው ይዘው ወደ እርስዋ መጡ።'),
  ('1638e84b-cfcb-5f6b-a950-ada8c3c04079', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 16, 19, 'እርስዋም በጕልበቷ ላይ አስተኛችው፤ ጠጕር ቈራጭም ጠራች፤ እርሱም ሰባቱን የራሱን ጕንጕን ላጨው። ይደክምም ጀመረ፤ ኀይሉም ከእርሱ ሄደ።'),
  ('97867971-9b16-523a-a622-796dc66e682e', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 17, 20, 'ደሊላም፥ “ሶምሶን ሆይ! ፍልስጥኤማውያን መጡብህ” አለችው። ከእንቅልፉም ነቅቶ፥ “እወጣለሁ፤ እንደ ወትሮውም ጊዜ አደርጋለሁ፤ አጠፋቸዋለሁም” አለ። ነገር ግን እግዚአብሔር ከእርሱ እንደ ተለየው አላወቀም።'),
  ('75c04aec-7ef2-520c-a219-f41345518bdb', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 18, 21, 'ፍልስጥኤማውያንም ይዘው ዐይኖቹን አወጡት፤ ወደ ጋዛም አውርደው በእግር ብረት አሰሩት፤ በግዞትም ሆኖ እህል ይፈጭ ነበር።'),
  ('235cfafb-205d-5f3f-a4f9-fb810d0bc0b6', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'd29ed501-feea-5204-a605-1b36d2500c03', 19, 22, 'የራሱም ጠጕር ከላጩት በኋላ ያድግ ጀመር።'),
  ('6380c071-054e-5ee4-aefa-d411b39b4a18', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'baf8d0c0-a049-5d96-a720-6b440f7b825b', 1, 23, 'የፍልስጥኤም መሳፍንትም፥ “አምላካችን ጠላታችንን ሶምሶንን በእጃችን አሳልፎ ሰጠን” እያሉ ለአምላካቸው ለዳጎን ታላቅ መሥዋዕት ይሠዉ ዘንድ፥ ደስም ይላቸው ዘንድ ተሰበሰቡ።'),
  ('4e801dba-fbf4-50ad-acf9-42a57199a8b3', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'baf8d0c0-a049-5d96-a720-6b440f7b825b', 2, 24, 'ሕዝቡም ሁሉ ባዩት ጊዜ፥ “ምድራችንን ያጠፋውን፥ ከእኛም ብዙ ሰው የገደለውን ጠላታችንን አምላካችን በእጃችን አሳልፎ ሰጠን እያሉ አምላካቸውን አመሰገኑ።'),
  ('cf5c59ab-d851-5f34-a827-ca6597077d9c', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'baf8d0c0-a049-5d96-a720-6b440f7b825b', 3, 25, 'ከዚህም በኋላ ልባቸውን ደስ ባለው ጊዜ፥ “በፊታችን እንዲጫወት ሶምሶንን ከእስር ቤት ጥሩት” አሉ። ሶምሶንንም ከእስር ቤት ጠሩት፤ በፊታቸውም ተጫወተ፤ ተዘባበቱበትም፤ በምሰሶና በምሰሶም መካከል አቆሙት።'),
  ('d7ff5620-f83b-5ccb-a4d5-889a318ec61c', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'baf8d0c0-a049-5d96-a720-6b440f7b825b', 4, 26, 'ሶምሶንም የሚመራውን ብላቴና፥ “ቤቱን የደገፉትን ምሰሶዎች እደገፍባቸው ዘንድ እባክህ አስይዘኝ” አለው፥ ብላቴናውም እንዳለው አደረገለት።'),
  ('19363275-55cb-5cd7-a4bb-be684b6e4fd2', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'baf8d0c0-a049-5d96-a720-6b440f7b825b', 5, 27, 'በቤትም ውስጥ ወንዶችና ሴቶች ሞልተውበት ነበር፤ የፍልስጥኤም መሳፍንትም ሁሉ በዚያ ነበሩ፤ በቤቱም ሰገነት ላይ ሶምሶን ሲጫወት የሚያዩ ሦስት ሺህ የሚያህሉ ወንዶችና ሴቶች ነበሩ።'),
  ('1b88c573-86be-50f2-a06c-f699f2911bcd', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'baf8d0c0-a049-5d96-a720-6b440f7b825b', 6, 28, 'ሶምሶንም ወደ እግዚአብሔር ጮኸ፥ እንዲህም አለ፥ “አቤቱ ጌታዬ ሆይ! አስበኝ፤ ጌታዬ ሆይ! አንድ ጊዜ አበርታኝ፤ እንግዲህ ስለ ሁለቱ ዐይኖቼ ፋንታ ከፍልስጥኤማውያን አንዲት በቀልን እበቀላለሁ።”'),
  ('dd8cd8a2-ed71-5aae-ab11-36f86baf0d6a', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'baf8d0c0-a049-5d96-a720-6b440f7b825b', 7, 29, 'ሶምሶንም ቤቱ ተደግፎባቸው የነበሩትን ሁለቱን መካከለኞች ምሰሶዎች ያዘ፤ አንዱን በቀኝ እጁ፥ አንዱንም በግራ እጁ ይዞ ገፋቸው።'),
  ('d6994f65-d856-578c-ad04-f07a12340918', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'baf8d0c0-a049-5d96-a720-6b440f7b825b', 8, 30, 'ሶምሶንም፥ “ከፍልስጥኤማውያን ጋር ነፍሴ ትውጣ” አለ፤ ተጎንብሶም ምሰሶዎቹን በሙሉ ኀይሉ ገፋቸው፤ ቤቱም በውስጡ በነበሩት በመሳፍንቱ፥ በሕዝቡም ሁሉ ላይ ወደቀ፤ በሞቱም የገደላቸው ሙታን በሕይወቱ ሳለ ከገደላቸው በዙ።'),
  ('781730f3-bfd3-514e-a74a-00634d092724', '5dfd43cc-6f16-5190-a7eb-c1afa5cd7528', 'baf8d0c0-a049-5d96-a720-6b440f7b825b', 9, 31, 'ወንድሞቹም፥ የአባቱ ቤተ ሰቦችም ሁሉ ወረዱ፤ ይዘውም አመጡት፤ በሶሬሕና በኢስታሔል መካከል ባለው በአባቱ በማኑሄ መቃብር ቀበሩት። እርሱም እስራኤልን ሃያ ዓመት ገዛቸው።'),
  ('eae18c7c-ab30-5f3c-a07c-44df7efebc53', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 1, 1, 'በተራራማውም በኤፍሬም ሀገር ሚካ የተባለ አንድ ሰው ነበረ።'),
  ('b95eef0e-0ebd-5b56-aa40-d56ab78c5dd6', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 2, 2, 'እናቱንም፥ “ከአንቺ ዘንድ የተሰረቀው፥ የረገምሽበትም፥ በጆሮዬም የተናገርሽበት አንድ ሺህ አንድ መቶ ብር እነሆ፥ በእኔ ዘንድ አለ፤ እኔም ወስጄው ነበር” አላት። እናቱም፥ “ልጄ ሆይ፥ እግዚአብሔር ይባርክህ” አለችው።'),
  ('1efc4365-8d7c-593c-a881-63ae27958b68', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 3, 3, 'አንዱን ሺህ አንድ መቶ ብርም ለእናቱ መለሰላት፤ እናቱም፥ “ይህን ብር የተቀረፀ ምስልና ቀልጦ የተሠራ ምስል አድርጌ ከእጄ ስለ ልጄ ለእግዚአብሔር እቀድሰዋለሁ፤ አሁንም ለአንተ እመልሰዋለሁ” አለች።'),
  ('a6491169-9a4b-5c95-a269-249166d4335c', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 4, 4, 'ለእናቱም ገንዘቡን መለሰላት እናቱም ብሩን ወስዳ ከእርሱ ሁለቱን መቶ ብር ለአንጥረኛ ሰጠችው፤ እርሱም የተቀረፀ ምስልና ቀልጦ የተሠራ ምስል አደረገው። በሚካም ቤት አስቀመጡት።'),
  ('26a76a78-d815-55ea-a8ea-e2a9015ea606', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 5, 5, 'ሰውዬውም ሚካ የአማልክት ቤት ነበረው፤ ኤፉድና ተራፊም አደረገ፤ ከልጆቹም አንዱን ቀደሰው፤ ካህንም ሆነለት።'),
  ('50747125-6147-5fbc-a585-febf60979348', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 6, 6, 'በዚያም ዘመን በእስራኤል ዘንድ ንጉሥ አልነበረም፤ ሰውም ሁሉ በፊቱ መልካም መስሎ የታየውን ያደርግ ነበር።'),
  ('44eb0403-e78d-5a4d-aa03-3a16c879fc91', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 7, 7, 'በይሁዳ ቤተ ልሔምም ከይሁዳ ወገን የሆነ አንድ ጐልማሳ ነበረ፤ እርሱም ሌዋዊ ነበረ፤ በዚያም ይቀመጥ ነበር።'),
  ('a36250c9-722d-5148-a73d-2923d13a5774', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 8, 8, 'ይህም ሰው በአገኘው ስፍራ ይኖር ዘንድ ከይሁዳ ከተማ ከቤተ ልሔም ሄደ፤ በዚያም ያድር ዘንድ ወደ ተራራማው ወደ ኤፍሬም ሀገር ወደ ሚካ ቤት ደረሰ።'),
  ('ad77c6a6-6035-568b-ae1a-b9c9ff4982cb', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 9, 9, 'ሚካም፥ “ከወዴት መጣህ?” አለው። እርሱም፥ “ከይሁዳ ቤተ ልሔም የሆንሁ ሌዋዊ ነኝ፤ የምቀመጥበትንም ስፍራ ለመሻት እሄዳለሁ” አለው።'),
  ('58e7a372-d616-51dd-a070-17fbd160f09d', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 10, 10, 'ሚካም፥ “በእኔ ዘንድ ተቀመጥ፤ አባትና ካህንም ሁነኝ፤ እኔም ልብሶችንና ምግብህን፥ በየዓመቱም ዐሥር ብር እሰጥሃለሁ” አለው።'),
  ('41c0e997-d8a5-5691-ae17-733d41df2429', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 11, 11, 'ሌዋዊዉም ሄደ። ከዚያም ሰው ጋር ይኖር ዘንድ ጀመረ፤ ጐልማሳውም ከልጆቹ እንደ አንዱ ሆነለት።'),
  ('8478622e-b2d2-5846-a9a3-b7bfdbe0cfdb', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 12, 12, 'ሚካም ሌዋዊዉን እጁን ቀባው፤ ጐልማሳውም ካህን ሆነለት፤ በሚካም ቤት ኖረ።'),
  ('edb0e233-49d7-5e10-aa1c-da43c36c9143', '4e77b564-bcbd-5351-a086-08f7ea8bf641', 'b0209aad-1f0c-566c-a4b1-605b66e5d178', 13, 13, 'ሚካም፥ “ሌዋዊ ካህን ስለ ሆነልኝ እግዚአብሔር መልካም እንዲሠራልኝ አሁን አውቃለሁ” አለ።'),
  ('09173ed2-0829-541d-aaf8-93106ddb8ef2', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 1, 1, 'በዚያም ዘመን በእስራኤል ዘንድ ንጉሥ አልነበረም። እስከዚያም ቀን ድረስ በእስራኤል ነገዶች መካከል ርስት አልደረሳቸውም ነበርና በዚያ ዘመን የዳን ነገድ የሚቀመጡባት ርስት ይሹ ነበር።'),
  ('965e0dca-bdf0-5f70-a564-029aba1749e7', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 2, 2, 'የዳንም ልጆች ከወገናቸው አምስት ጽኑዓን ሰዎች ምድሪቱን እንዲሰልሉና እንዲመረምሩ፥ “ሂዱ ምድሪቱንም ሰልሉ” ብለው ከሶራሕና ከኢስታሔል ላኩ። እነዚያም ወደ ተራራማዉ ወደ ኤፍሬም ሀገር ወደ ሚካ ቤት መጥተው በዚያ አደሩ።'),
  ('afafdee1-3bcf-5306-a858-d73e7454827e', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 3, 3, 'በሚካ ቤትም በነበሩ ጊዜ የሌዋዊዉን የጐልማሳውን ድምፅ ዐወቁ፤ ወደ እርሱም ቀርበው፥ “ወደዚህ ማን አመጣህ? በዚህስ የምታደርገው ምንድን ነው? በዚህስ ምን አለህ?” አሉት።'),
  ('11d34ccc-d3e8-5595-a656-c072ce30e854', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 4, 4, 'እርሱም፥ “ሚካ እንዲህ እንዲህ አደረገልኝ፤ ቀጠረኝም፤ እኔም ካህን ሆንሁለት” አላቸው።'),
  ('e6f6fea6-db1b-52e9-a183-66ecaa851961', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 5, 5, 'እነርሱም፥ “የምንሄድበት መንገድ የቀና መሆኑን እናውቅ ዘንድ፥ እባክህ እግዚአብሔርን ጠይቅልን” አሉት።'),
  ('ccd9ed18-4463-5cf7-ab8b-ecf27b58ffd3', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 6, 6, 'ያም ካህን፥ “የምትሄዱበት መንገድ በእግዚአብሔር ፊት ነውና በሰላም ሂዱ” አላቸው።'),
  ('9de82d85-074e-5c66-aa05-8bc667d76add', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 7, 7, 'አምስቱም ሰዎች ሄዱ፤ ወደ ሌሳም ደረሱ፤ በውስጡም የነበሩትን ሕዝብ ተዘልለው አዩአቸው፤ እንደ ሲዶናውያንም ልማድ ጸጥ ብለው፥ ዐርፈው፥ ተዘልለውም ተቀምጠው ነበር፤ በተመዘገበች የርስታቸው ምድርም ቃልን መናገር አልቻሉም፤ ከሲዶናውያንም ርቀው ይኖሩ ነበር። ከሶርያውያንም ጋር ግንኙነት አልነበራቸውም።'),
  ('3ddb9212-83fb-5995-a12a-ce52be525f3b', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 8, 8, 'እነዚያም አምስቱ ሰዎች ወደ ወንድሞቻቸው ወደ ሶራሕና ወደ እስታሔል ተመለሱ፤ ወንድሞቻቸውንም፥ “ምን አስቀምጦአችኋል?” አሉአቸው።'),
  ('7b0bc1a2-d228-5a4f-a41b-fd082f055f61', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 9, 9, 'እነርሱም፥ “ምድሪቱ እጅግ መልካም እንደ ሆነች አይተናል፤ ተነሡ፤ በእነርሱ ላይ እንውጣ፤ እናንተ ዝም ትላላችሁን? ትሄዱ ዘንድ፥ ምድሪቱንም ለመውረስ ትገቡ ዘንድ ቸል አትበሉ።'),
  ('1b676eea-d21c-5de7-a1ec-536266336483', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 10, 10, 'በሄዳችሁም ጊዜ ተዘልለው ወደ ተቀመጡ ሕዝብ ትደርሳላችሁ፤ ምድሪቱም ሰፊ ናት፤ እግዚአብሔርም በምድር ካለው ነገር ሁሉ አንዳች የማይጐድልባትን ስፍራ በእጃችሁ ሰጥቶአል” አሉ።'),
  ('a280b095-c2e4-5337-acbd-6327441a0927', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 11, 11, 'ከዳን ወገንም የጦር ዕቃ የታጠቁ ስድስት መቶ ሰዎች ከዚያ ከሶራሕና ከእስታሔል ተነሥተው ሄዱ።'),
  ('f22f8b2c-735a-5b2a-a072-451d269f883f', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 12, 12, 'ወጥተውም በይሁዳ ቂርያትይዓሪም ሰፈሩ፤ ስለዚህም የዚያ ስፍራ ስም እስከ ዛሬ ድረስ የዳን ሰፈር ተብሎ ተጠራ፤ እነሆም፥ ቦታዉ ከቂርያትይዓሪም በስተኋላ ነው።'),
  ('4ff2c8f0-0677-55b0-a183-245041e59af1', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 13, 13, 'ከዚያም ወደ ተራራማው ወደ ኤፍሬም አገር አለፉ እስከ ሚካም ቤት ደረሱ።'),
  ('1828030f-5943-5287-ae58-85801a5e54f0', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 14, 14, 'የሌሳን ምድር ሊሰልሉ ሄደው የነበሩት አምስቱ ሰዎችም ወንድሞቻቸውን፥ “በእነዚህ ቤቶች ውስጥ ኢፉድና ተራፊም፥ የተቀረፀ ምስልና ቀልጦ የተሠራ ምስልም እንዳሉ ታውቃላችሁን?፤ አሁንም የምታደርጉትን ዕወቁ” ብለው ተናገሩአቸው።'),
  ('157a6436-b3f7-54a5-a751-48dcf528d8cf', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 15, 15, 'ከመንገዱም ፈቀቅ ብለው ወደ ጐልማሳው ሌዋዊ ቤት ወደ ሚካ ቤት መጡ፤ ሰላምታም ሰጡት።'),
  ('9e291250-58b1-513c-ac00-64c754bd6d2e', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 16, 16, 'የጦር ዕቃ የታጠቁት፥ ከዳን ልጆችም የሆኑት ስድስቱ መቶ ሰዎች በደጃፉ አጠገብ ቆመው ነበር።'),
  ('72f0b4af-138d-5cbc-abff-e4d03f8b2559', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 17, 17, 'ምድሪቱንም ሊሰልሉ ሄደው የነበሩት አምስቱ ሰዎች መጥተው ወደዚያ ገቡ፤ የተቀረፀውንም ምስል ኤፉዱንም፥ ተራፊሙንም ቀልጦ የተሠራውን ምስልም ወሰዱ፤ ካህኑም የጦር ዕቃ ከታጠቁት ከስድስት መቶ ሰዎች ጋር በደጃፉ አጠገብ ቆሞ ነበር።'),
  ('11431af5-f2ef-516d-a9b6-1dcf492fea31', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 18, 18, 'እነዚህም ሰዎች ወደ ሚካ ቤት ገብተው የተቀረፀውን ምስል፥ ኤፉዱንም፥ ተራፊሙንም፥ ቀልጦ የተሠራውን ምስልም ወሰዱ፤ ካህኑም፥ “ምን ታደርጋላችሁ?” አላቸው።'),
  ('b5369651-85cb-522a-afdf-309556a0fcfc', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 19, 19, 'እነርሱም፥ “ዝም በል፤ እጅህንም በአፍህ ላይ ጫን፤ ከእኛም ጋር ና፥ አባትና ካህንም ሁንልን፤ ለአንድ ሰው ቤት ካህን መሆን ወይስ በእስራኤል ዘንድ ለነገድና ለወገን ካህን መሆን ማናቸው ይሻልሃል?” አሉት።'),
  ('2444ff76-4e83-54ca-abf1-7d3837c87ee2', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 20, 20, 'ካህኑም በልቡ ደስ አለው፤ ኤፉዱንም፥ ተራፊሙንም፥ የተቀረፀውንም ምስል፥ ቀልጦ የተሠራውንም ምስል ወሰደ፤ በሕዝቡም መካከል ገባ።'),
  ('eb82e7fc-4a36-51a9-a425-32274aa79531', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 21, 21, 'እነርሱም ተመልሰው ሄዱ፤ ቤተ ሰቡን፥ ገንዘቡንና ሀብቱንም ሁሉ፥ በፊታቸው አድርገው ወሰዱ።'),
  ('f60ddd63-2e62-5cd1-a55f-43e1f82f7fe7', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', 'f42ff2a8-ae7c-5fee-ae3e-7de705e0867b', 22, 22, 'ከሚካም ቤት ሳይርቁ ሚካና የሚካ ጎረቤቶች ጮኹ፤ የዳንንም ልጆች ተከትለው ደረሱባቸው።'),
  ('f0fc245d-4e1e-5615-a4de-b651bc44b37d', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', '106dcda1-e148-5fd7-a836-c05abce0109f', 1, 23, 'ወደ ዳንም ልጆች ጮኹ፤ የዳንም ልጆች ፊታቸውን መልሰው ሚካን፥ “የምትጮኸው ምን ሆነህ ነው?” አሉት።'),
  ('c9ae3d07-bab1-502b-ab7b-ab828927d86d', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', '106dcda1-e148-5fd7-a836-c05abce0109f', 2, 24, 'እርሱም፥ “የሠራኋቸውን አማልክቴን፥ ካህኑንም ይዛችሁ ሄዳችኋል፤ ለእኔ ምን ተዋችሁልኝ? እናንተስ፦ ለምን ትጮኻለህ እንዴት ትሉኛላችሁ?” አለ።'),
  ('1a3ff4b5-90f8-5a78-a0e3-48ec836a3d69', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', '106dcda1-e148-5fd7-a836-c05abce0109f', 3, 25, 'የዳንም ልጆች እንዲህ አሉት፥ “የተቈጡ ሰዎች እንዳያገኙህና ነፍስህም፥ የቤተ ሰቦችህም ነፍስ እንዳይጠፋብህ፥ ድምፅህ በእኛ መካከል አይሰማ።”'),
  ('a689d3c3-3278-540e-abbb-51f8c928b152', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', '106dcda1-e148-5fd7-a836-c05abce0109f', 4, 26, 'የዳንም ልጆች መንገዳቸውን ሄዱ፤ ሚካም ከእርሱ እንደ በረቱ ባየ ጊዜ ተመልሶ ወደ ቤቱ ሄደ።።'),
  ('878e2cc8-27ec-57ca-abbf-1ad28164e7d1', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', '106dcda1-e148-5fd7-a836-c05abce0109f', 5, 27, 'እነርሱም ሚካ የሠራውን ጣዖትና ለእርሱ የነበረውን ካህን ይዘው ወደ ሌሳ፥ ጸጥ ብሎ ተዘልሎም ወደ ተቀመጠው ሕዝብ መጡ፤ በሰይፍም ስለት መቱአቸው፤ ከተማዪቱንም በእሳት አቃጠሉአት።'),
  ('fe0bcc60-dcad-5a22-a6fb-f8d47c4c9538', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', '106dcda1-e148-5fd7-a836-c05abce0109f', 6, 28, 'የሚታደግም አልነበረም፤ ከሲዶና ርቀው ነበርና፥ እነርሱም ከሌሎች ሰዎች ጋር ግንኙነት አልነበራቸውምና። እርስዋም በቤትሮአብ አጠገብ ባለች ሸለቆ ውስጥ ነበረች፤ ከተማዪቱንም ሠርተው ተቀመጡባት።'),
  ('d7b88ca9-5376-5fdd-af92-556f331acfdd', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', '106dcda1-e148-5fd7-a836-c05abce0109f', 7, 29, 'ከተማዪቱንም ከእስራኤል በተወለደው በአባታቸው በዳን ስም ዳን ብለው ጠሩአት፤ የከተማዪቱም ስም አስቀድሞ ሌሳ ነበረ።'),
  ('5ef3943b-8b51-5270-a56b-8e609e638da1', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', '106dcda1-e148-5fd7-a836-c05abce0109f', 8, 30, 'የዳንም ልጆች የተቀረፀውን የሚካን ምስል ለራሳቸው አቆሙ፤ የሙሴም ልጅ የጌርሳም ልጅ ዮናታን፥ እርሱና ልጆቹ እስከ ሀገራቸው ምርኮ ድረስ ለዳን ነገድ ካህናት ነበሩ።'),
  ('c98c02e4-d697-5514-ab8c-6dc80b2e33a3', '8cd5aa1d-e98e-57f8-aaf5-0e616ebc707b', '106dcda1-e148-5fd7-a836-c05abce0109f', 9, 31, 'ሚካም ያደረገውን የተቀረፀ ምስል የእግዚአብሔር ቤት በሴሎ ባለበት ዘመን ሁሉ አቆሙ።'),
  ('512bee01-db72-58d5-a578-38eef7ba03a4', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 1, 1, 'በዚያም ዘመን ለእስራኤል ንጉሥ አልነበራቸውም። በተራራማውም በኤፍሬም ሀገር ማዶ የተቀመጠ አንድ ሌዋዊ ሰው ነበረ፤ ከይሁዳ ቤተ ልሔምም ዕቅብት አገባ።'),
  ('7eace6ad-cf46-5a25-af85-392450ecec32', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 2, 2, 'ዕቅብቱም ተጣላችው፤ ትታውም ወደ አባቷ ቤት ወደ ይሁዳ ቤተ ልሔም ሄደች፤ በዚያም አራት ወር ተቀመጠች።'),
  ('c6a71968-10d4-5077-a490-3e38b3e6096d', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 3, 3, 'ባልዋም ተነሣ፤ ከእርስዋም ዕርቅ ሽቶ ወደ እርሱ ሊመልሳት ፍለጋዋን ተከትሎ ሄደ፤ ከእርሱም ጋር አንድ ብላቴና፥ ሁለትም አህዮች ነበሩ። እርሱም ወደ አባቷ ቤት ሄደ፤ የብላቴናዪቱም አባት ባየው ጊዜ ደስ ብሎት ተቀበለው።'),
  ('5f6ebaf0-1ac1-579b-aecc-0513907fc56d', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 4, 4, 'የብላቴናዪቱም አባት አማቱ ወደ ቤቱ አገባው፤ በቤቱም ሦስት ቀን ተቀመጠ፤ በሉም፤ ጠጡም፤ በዚያም አደሩ።')
